/// Resolves the real application scene used by hosted XCTest. The helper waits
/// through a transient lifecycle transition, but never creates, substitutes,
/// or requests activation of a scene. It fails closed when the single-scene
/// test host has no unambiguous foreground-active application session.
@MainActor
func requireHostedForegroundWindowScene(
    timeout: TimeInterval = 3,
    file: StaticString = #filePath,
    line: UInt = #line
) throws -> UIWindowScene {
    func diagnosticSnapshot() -> String {
        let openSessions = UIApplication.shared.openSessions.map {
            "session=\($0.persistentIdentifier),role=\($0.role.rawValue)"
        }.sorted().joined(separator: ";")
        let connectedScenes = UIApplication.shared.connectedScenes.map {
            "session=\($0.session.persistentIdentifier)," +
                "role=\($0.session.role.rawValue)," +
                "state=\($0.activationState.rawValue)"
        }.sorted().joined(separator: ";")
        return "open=[\(openSessions)] connected=[\(connectedScenes)] " +
            "applicationState=\(UIApplication.shared.applicationState.rawValue)"
    }

    func activeWindowScenes(for session: UISceneSession) -> [UIWindowScene] {
        UIApplication.shared.connectedScenes
            .compactMap { $0 as? UIWindowScene }
            .filter {
                $0.session.role == .windowApplication &&
                    $0.session.persistentIdentifier ==
                        session.persistentIdentifier &&
                    $0.activationState == .foregroundActive
            }
    }

    let applicationSessions = UIApplication.shared.openSessions.filter {
        $0.role == .windowApplication
    }
    guard applicationSessions.count == 1,
          let session = applicationSessions.first else {
        XCTFail(
            "hosted tests require exactly one real application scene session; " +
                "applicationSessions=\(applicationSessions.count) " +
                diagnosticSnapshot(),
            file: file,
            line: line
        )
        throw HostedForegroundWindowSceneError.unavailable
    }

    let initiallyActiveScenes = activeWindowScenes(for: session)
    guard initiallyActiveScenes.count <= 1 else {
        XCTFail(
            "hosted test session resolved multiple active window scenes; " +
                "session=\(session.persistentIdentifier) " +
                "role=\(session.role.rawValue) " + diagnosticSnapshot(),
            file: file,
            line: line
        )
        throw HostedForegroundWindowSceneError.unavailable
    }
    if let scene = initiallyActiveScenes.first {
        return scene
    }

    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
        let activeScenes = activeWindowScenes(for: session)
        guard activeScenes.count <= 1 else {
            XCTFail(
                "hosted test session resolved multiple active window scenes; " +
                    "session=\(session.persistentIdentifier) " +
                    "role=\(session.role.rawValue) " + diagnosticSnapshot(),
                file: file,
                line: line
            )
            throw HostedForegroundWindowSceneError.unavailable
        }
        if let scene = activeScenes.first {
            return scene
        }
        RunLoop.current.run(
            mode: .default,
            before: Date().addingTimeInterval(0.01)
        )
    }

    XCTFail(
        "hosted test scene did not become foreground-active; " +
        "session=\(session.persistentIdentifier) " +
            "role=\(session.role.rawValue) " + diagnosticSnapshot(),
        file: file,
        line: line
    )
    throw HostedForegroundWindowSceneError.unavailable
}

private enum HostedForegroundWindowSceneError: Error {
    case unavailable
}

final class AppLaunchEnvironmentPolicyTests: XCTestCase {
    func testHostedXCTestSuppressesLastChatsNotificationAuthorizationPrompt() {
        XCTAssertFalse(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: true,
                applicationState: .active,
                sceneActivationState: .foregroundActive,
                environment: [
                    AppLaunchEnvironmentPolicy.hostedXCTestEnvironmentKey:
                        "/tmp/test.xctestconfiguration",
                    AppLaunchEnvironmentPolicy
                        .disableAccountAutoconnectEnvironmentKey: "1",
                    AppLaunchEnvironmentPolicy.isolatedStorageEnvironmentKey:
                        "1"
                ],
                arguments: ["xabber"]
            )
        )
    }

    func testPerformanceFixtureSuppressesLastChatsNotificationAuthorizationPrompt() {
        XCTAssertFalse(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: true,
                applicationState: .active,
                sceneActivationState: .foregroundActive,
                environment: [
                    ChatPerformanceUITestLaunchPolicy.uiTestMarkerKey: "1"
                ],
                arguments: [
                    "xabber",
                    ChatPerformanceUITestLaunchPolicy.launchArgument,
                    ChatPerformanceFixtureScale.small.rawValue
                ]
            )
        )
    }

    func testNormalVisibleForegroundLastChatsAllowsNotificationAuthorizationPrompt() {
        XCTAssertTrue(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: true,
                applicationState: .active,
                sceneActivationState: .foregroundActive,
                environment: [:],
                arguments: ["xabber"]
            )
        )
    }

    func testHiddenOrInactiveLastChatsSuppressesNotificationAuthorizationPrompt() {
        XCTAssertFalse(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: false,
                applicationState: .active,
                sceneActivationState: .foregroundActive,
                environment: [:],
                arguments: ["xabber"]
            )
        )
        XCTAssertFalse(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: true,
                applicationState: .inactive,
                sceneActivationState: .foregroundActive,
                environment: [:],
                arguments: ["xabber"]
            )
        )
        XCTAssertFalse(
            LastChatsNotificationAuthorizationPromptPolicy.shouldRequest(
                isLastChatsVisible: true,
                applicationState: .active,
                sceneActivationState: .foregroundInactive,
                environment: [:],
                arguments: ["xabber"]
            )
        )
    }

    func testHostedXCTestCanDisableAccountAutoconnect() {
        XCTAssertFalse(AppLaunchEnvironmentPolicy.shouldAutoconnectAccounts(
            isPushKit: false,
            environment: [
                AppLaunchEnvironmentPolicy.hostedXCTestEnvironmentKey: "/tmp/test.xctestconfiguration",
                AppLaunchEnvironmentPolicy.disableAccountAutoconnectEnvironmentKey: "1"
            ]
        ))
    }

    func testXcodebuildPrefixIsNotPartOfTestRunnerRuntimeFlag() {
        XCTAssertTrue(AppLaunchEnvironmentPolicy.shouldAutoconnectAccounts(
            isPushKit: false,
            environment: [
                AppLaunchEnvironmentPolicy.hostedXCTestEnvironmentKey: "/tmp/test.xctestconfiguration",
                "TEST_RUNNER_XABBER_DISABLE_ACCOUNT_AUTOCONNECT": "1"
            ]
        ))
    }

    func testNormalLaunchKeepsAccountAutoconnectEnabled() {
        XCTAssertTrue(AppLaunchEnvironmentPolicy.shouldAutoconnectAccounts(
            isPushKit: false,
            environment: [:]
        ))
    }

    func testPushKitLaunchKeepsAccountAutoconnectDisabled() {
        XCTAssertFalse(AppLaunchEnvironmentPolicy.shouldAutoconnectAccounts(
            isPushKit: true,
            environment: [:]
        ))
    }

    func testHostedXCTestWithoutDisableFlagKeepsAccountAutoconnectEnabled() {
        XCTAssertTrue(AppLaunchEnvironmentPolicy.shouldAutoconnectAccounts(
            isPushKit: false,
            environment: [
                AppLaunchEnvironmentPolicy.hostedXCTestEnvironmentKey: "/tmp/test.xctestconfiguration",
                AppLaunchEnvironmentPolicy.isolatedStorageEnvironmentKey: "1"
            ]
        ))
    }

    @MainActor
    func testHostedForegroundWindowSceneUsesSoleApplicationSession() throws {
        let scene = try requireHostedForegroundWindowScene()
        let applicationSessions = UIApplication.shared.openSessions.filter {
            $0.role == .windowApplication
        }

        XCTAssertEqual(applicationSessions.count, 1)
        XCTAssertEqual(scene.session.role, .windowApplication)
        XCTAssertEqual(
            scene.session.persistentIdentifier,
            try XCTUnwrap(applicationSessions.first?.persistentIdentifier)
        )
        XCTAssertEqual(scene.activationState, .foregroundActive)
    }
}

final class CommonChatStatesManagerEmissionTests: XCTestCase {
    func testExpireDoesNotEmitWhenStateSetIsUnchanged() {
        let manager = CommonChatStatesManager()
        var emissionCount = 0
        let disposable = manager.observed.subscribe(onNext: { _ in
            emissionCount += 1
        })
        defer {
            disposable.dispose()
            manager.bag = .init()
        }

        XCTAssertEqual(emissionCount, 1)

        manager.expire()

        XCTAssertEqual(emissionCount, 1)
    }

    func testClearDoesNotEmitWhenChatStateIsMissing() {
        let manager = CommonChatStatesManager()
        var emissionCount = 0
        let disposable = manager.observed.subscribe(onNext: { _ in
            emissionCount += 1
        })
        defer {
            disposable.dispose()
            manager.bag = .init()
        }

        manager.clear(jid: "missing@example.com", owner: "owner@example.com")

        XCTAssertEqual(emissionCount, 1)
    }

    func testExpireBatchesMultipleStaleStateTransitionsIntoOneEmission() {
        let manager = CommonChatStatesManager()
        var emissionCount = 0
        let disposable = manager.observed.subscribe(onNext: { _ in
            emissionCount += 1
        })
        defer {
            disposable.dispose()
            manager.bag = .init()
        }
        manager.update(jid: "one@example.com", owner: "owner@example.com", state: .typing)
        manager.update(jid: "two@example.com", owner: "owner@example.com", state: .voice)
        manager.observed.value.forEach {
            $0.date = Date(timeIntervalSinceNow: -16)
        }
        let emissionsBeforeExpiration = emissionCount

        manager.expire()

        XCTAssertEqual(emissionCount, emissionsBeforeExpiration + 1)
        XCTAssertEqual(manager.observed.value.count, 2)
        XCTAssertTrue(manager.observed.value.allSatisfy { $0.state == .none })
    }

    func testDuplicateStateRefreshesExpirationWithoutPresentationEmission() {
        let manager = CommonChatStatesManager()
        var emissionCount = 0
        let disposable = manager.observed.subscribe(onNext: { _ in
            emissionCount += 1
        })
        defer {
            disposable.dispose()
            manager.bag = .init()
        }
        manager.update(jid: "one@example.com", owner: "owner@example.com", state: .typing)
        let item = try! XCTUnwrap(manager.observed.value.first)
        item.date = Date(timeIntervalSinceNow: -10)
        let staleDate = item.date
        let emissionsBeforeRefresh = emissionCount

        manager.update(jid: "one@example.com", owner: "owner@example.com", state: .typing)

        XCTAssertEqual(emissionCount, emissionsBeforeRefresh)
        XCTAssertGreaterThan(item.date, staleDate)
    }

    func testRealStateTransitionStillEmits() {
        let manager = CommonChatStatesManager()
        var emissionCount = 0
        var emittedRawStates: [Int] = []
        let disposable = manager.observed.subscribe(onNext: { value in
            emissionCount += 1
            if let rawState = value.first?.state.rawValue {
                emittedRawStates.append(rawState)
            }
        })
        defer {
            disposable.dispose()
            manager.bag = .init()
        }
        manager.update(jid: "one@example.com", owner: "owner@example.com", state: .typing)
        let emissionsBeforeTransition = emissionCount

        manager.update(jid: "one@example.com", owner: "owner@example.com", state: .none)

        XCTAssertEqual(emissionCount, emissionsBeforeTransition + 1)
        XCTAssertTrue(emittedRawStates.contains(ChatStatesManager.ComposingType.none.rawValue))
    }
}

final class ChatFloatingHeaderLayoutPolicyTests: XCTestCase {
    func testCollectionInsetsReserveNavbarAtTopAndComposerAtBottom() {
        let insets = ChatFloatingHeaderLayoutPolicy.collectionInsets(
            composerHeight: 56,
            navigationVisualHeight: 88,
            floatingBubblesHeight: 0,
            contentHeight: 600,
            viewportHeight: 500
        )

        XCTAssertEqual(insets.top, 88)
        XCTAssertEqual(insets.bottom, 64)
        XCTAssertEqual(insets.left, 0)
        XCTAssertEqual(insets.right, 0)
    }

    func testVisibleBubblesAddTopReservationWithOuterSpacing() {
        let stackHeight = ChatFloatingHeaderLayoutPolicy.visibleStackHeight(
            visibleBubbleHeights: [52, 56],
            spacing: 8
        )
        let insets = ChatFloatingHeaderLayoutPolicy.collectionInsets(
            composerHeight: 56,
            navigationVisualHeight: 88,
            floatingBubblesHeight: stackHeight,
            contentHeight: 600,
            viewportHeight: 500
        )

        XCTAssertEqual(stackHeight, 116)
        XCTAssertEqual(insets.top, 220)
        XCTAssertEqual(insets.bottom, 64)
    }

    func testNoVisibleBubblesDoNotReserveFloatingSpacing() {
        let stackHeight = ChatFloatingHeaderLayoutPolicy.visibleStackHeight(
            visibleBubbleHeights: [],
            spacing: 8
        )
        let insets = ChatFloatingHeaderLayoutPolicy.collectionInsets(
            composerHeight: 49,
            navigationVisualHeight: 44,
            floatingBubblesHeight: stackHeight,
            contentHeight: 600,
            viewportHeight: 500
        )

        XCTAssertEqual(stackHeight, 0)
        XCTAssertEqual(insets.top, 44)
        XCTAssertEqual(insets.bottom, 57)
    }

    func testShortConversationAddsExtraTopInsetToBottomAlignMessages() {
        let insets = ChatFloatingHeaderLayoutPolicy.collectionInsets(
            composerHeight: 56,
            navigationVisualHeight: 88,
            floatingBubblesHeight: 0,
            contentHeight: 120,
            viewportHeight: 500
        )

        XCTAssertEqual(insets.top, 316)
        XCTAssertEqual(insets.bottom, 64)
    }
}

final class ChatBottomScrollAlignmentPolicyTests: XCTestCase {
    func testTargetOffsetIncludesBottomInsetForComposerClearance() {
        let composerHeight: CGFloat = 56
        let insets = UIEdgeInsets(
            top: 88,
            left: 0,
            bottom: composerHeight + ChatFloatingHeaderLayoutPolicy.composerMessageSpacing,
            right: 0
        )

        let offsetY = ChatBottomScrollAlignmentPolicy.targetContentOffsetY(
            targetMaxY: 720,
            contentHeight: 720,
            viewportHeight: 500,
            contentInsets: insets
        )

        XCTAssertEqual(offsetY, 284)
    }

    func testShortContentClampsToMinimumTopInsetOffset() {
        let insets = UIEdgeInsets(top: 316, left: 0, bottom: 64, right: 0)

        let offsetY = ChatBottomScrollAlignmentPolicy.targetContentOffsetY(
            targetMaxY: 120,
            contentHeight: 120,
            viewportHeight: 500,
            contentInsets: insets
        )

        XCTAssertEqual(offsetY, -316)
    }

    func testTargetCellCanAlignAboveComposerWhenFakeRowsFollowIt() {
        let insets = UIEdgeInsets(top: 44, left: 0, bottom: 64, right: 0)

        let offsetY = ChatBottomScrollAlignmentPolicy.targetContentOffsetY(
            targetMaxY: 720,
            contentHeight: 780,
            viewportHeight: 500,
            contentInsets: insets
        )

        XCTAssertEqual(offsetY, 284)
    }

    func testOutgoingScrollDisablesStructuralApplyAnimation() {
        XCTAssertFalse(
            ChatOutgoingAutoScrollApplyPolicy.shouldAnimateStructuralApply(
                requestedAnimated: true,
                outgoingAutoScrollDecision: .scroll(IndexPath(item: 0, section: 10))
            )
        )

        XCTAssertTrue(
            ChatOutgoingAutoScrollApplyPolicy.shouldAnimateStructuralApply(
                requestedAnimated: true,
                outgoingAutoScrollDecision: .useDefaultAndClear
            )
        )

        XCTAssertFalse(
            ChatOutgoingAutoScrollApplyPolicy.shouldAnimateStructuralApply(
                requestedAnimated: false,
                outgoingAutoScrollDecision: .scroll(IndexPath(item: 0, section: 10))
            )
        )
    }

    func testOutgoingScrollUsesImmediateReloadPath() {
        XCTAssertTrue(
            ChatOutgoingAutoScrollApplyPolicy.shouldUseImmediateReload(
                outgoingAutoScrollDecision: .scroll(IndexPath(item: 0, section: 10))
            )
        )

        XCTAssertFalse(
            ChatOutgoingAutoScrollApplyPolicy.shouldUseImmediateReload(
                outgoingAutoScrollDecision: .useDefaultAndClear
            )
        )

        XCTAssertFalse(
            ChatOutgoingAutoScrollApplyPolicy.shouldUseImmediateReload(
                outgoingAutoScrollDecision: .notHandled
            )
        )
    }

    func testPureTailAppendAtBottomUsesBottomPinnedApply() {
        let oldItems = [
            makeBottomPolicyDatasource(primary: "m1"),
            makeBottomPolicyDatasource(primary: "m2")
        ]
        let newItems = oldItems + [makeBottomPolicyDatasource(primary: "m3")]

        XCTAssertTrue(
            ChatTailAppendBottomPinPolicy.shouldPinBottom(
                old: ChatDatasourceCoordinator.makeSnapshot(items: oldItems),
                new: ChatDatasourceCoordinator.makeSnapshot(items: newItems),
                wasNearBottom: true,
                isDefaultBottomScrollDeferred: false,
                suppressDefaultBottomScroll: false,
                containsOnlyFakeMessages: false,
                outgoingAutoScrollDecision: .notHandled
            )
        )
    }

    func testTailAppendAwayFromBottomKeepsCurrentVisiblePosition() {
        let oldItems = [
            makeBottomPolicyDatasource(primary: "m1"),
            makeBottomPolicyDatasource(primary: "m2")
        ]
        let newItems = oldItems + [makeBottomPolicyDatasource(primary: "m3")]

        XCTAssertFalse(
            ChatTailAppendBottomPinPolicy.shouldPinBottom(
                old: ChatDatasourceCoordinator.makeSnapshot(items: oldItems),
                new: ChatDatasourceCoordinator.makeSnapshot(items: newItems),
                wasNearBottom: false,
                isDefaultBottomScrollDeferred: false,
                suppressDefaultBottomScroll: false,
                containsOnlyFakeMessages: false,
                outgoingAutoScrollDecision: .notHandled
            )
        )
    }

    func testNonTailDiffDoesNotUseBottomPinnedApply() {
        let oldItems = [
            makeBottomPolicyDatasource(primary: "m1"),
            makeBottomPolicyDatasource(primary: "m2")
        ]
        let newItems = [
            makeBottomPolicyDatasource(primary: "m0")
        ] + oldItems

        XCTAssertFalse(
            ChatTailAppendBottomPinPolicy.shouldPinBottom(
                old: ChatDatasourceCoordinator.makeSnapshot(items: oldItems),
                new: ChatDatasourceCoordinator.makeSnapshot(items: newItems),
                wasNearBottom: true,
                isDefaultBottomScrollDeferred: false,
                suppressDefaultBottomScroll: false,
                containsOnlyFakeMessages: false,
                outgoingAutoScrollDecision: .notHandled
            )
        )
    }

    func testAnchorNavigationSuppressesBottomPinnedTailAppend() {
        let oldItems = [
            makeBottomPolicyDatasource(primary: "m1"),
            makeBottomPolicyDatasource(primary: "m2")
        ]
        let newItems = oldItems + [makeBottomPolicyDatasource(primary: "m3")]

        XCTAssertFalse(
            ChatTailAppendBottomPinPolicy.shouldPinBottom(
                old: ChatDatasourceCoordinator.makeSnapshot(items: oldItems),
                new: ChatDatasourceCoordinator.makeSnapshot(items: newItems),
                wasNearBottom: true,
                isDefaultBottomScrollDeferred: true,
                suppressDefaultBottomScroll: false,
                containsOnlyFakeMessages: false,
                outgoingAutoScrollDecision: .notHandled
            )
        )
    }

    func testAttachmentSendCompletionRequestsOutgoingScrollSynchronouslyOnMainThread() {
        XCTAssertTrue(Thread.isMainThread)
        let chat = ChatViewController()

        chat.finishOutgoingAttachmentSend(requestScroll: true)

        XCTAssertNotNil(chat.pendingOutgoingAutoScrollRequest)
    }

    private func makeBottomPolicyDatasource(primary: String) -> ChatViewController.Datasource {
        ChatViewController.Datasource(
            primary: primary,
            jid: "romeo@example.com",
            owner: "owner@example.com",
            outgoing: false,
            sender: Sender(id: "romeo@example.com", displayName: "Romeo"),
            messageId: "\(primary)-message-id",
            sentDate: Date(timeIntervalSince1970: 1_700_000_000),
            editDate: nil,
            kind: .attributedText(NSAttributedString(string: primary)),
            withAuthor: false,
            withAvatar: false,
            error: false,
            errorType: "",
            canPinMessage: false,
            canEditMessage: false,
            canDeleteMessage: false,
            forwards: [],
            isOutgoing: false,
            isEdited: false,
            groupchatAuthorRole: "",
            groupchatAuthorId: "",
            groupchatAuthorNickname: "",
            groupchatAuthorBadge: "",
            isHasAttachedMessages: false,
            isDownloaded: true,
            state: .read,
            searchString: nil,
            errorMetadata: nil,
            burnDate: -1,
            afterburnInterval: -1,
            archivedId: "archive-\(primary)",
            queryIds: nil,
            isRead: true,
            selectedSearchResultId: nil,
            isHadHistoryGap: false,
            tailed: false,
            isFakeMessage: false,
            images: [],
            videos: [],
            files: [],
            audios: [],
            timeMarkerText: NSAttributedString(string: ""),
            indicator: .none,
            avatarUrl: nil,
            attributedAuthor: nil
        )
    }
}

final class ContinuousSplitBackgroundExperimentTests: XCTestCase {
    func testSplitCompactUsesStockCompactBackgroundMode() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .split,
                windowHorizontalSizeClass: .compact,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: false
            ),
            .stockCompact
        )
    }

    func testSplitRegularWindowAndExpandedSplitUsesSharedBackdropMode() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .split,
                windowHorizontalSizeClass: .regular,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: false
            ),
            .sharedBackdrop
        )
    }

    func testRegularWindowUsesSharedBackdropEvenWhenSplitTemporarilyCollapsed() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .split,
                windowHorizontalSizeClass: .regular,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: true
            ),
            .sharedBackdrop
        )
    }

    func testCompactWindowWinsOverRegularChildOrSplitTraits() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .split,
                windowHorizontalSizeClass: .compact,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: false
            ),
            .stockCompact
        )
    }

    func testUnresolvedSplitTraitsDeferBackgroundMode() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .split,
                windowHorizontalSizeClass: .unspecified,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: false
            ),
            .deferred
        )
    }

    func testTabsNeverUseSplitBackgroundMode() {
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .tabs,
                windowHorizontalSizeClass: .regular,
                splitHorizontalSizeClass: .regular,
                isSplitCollapsed: false
            ),
            .inactive
        )
        XCTAssertEqual(
            ContinuousSplitBackgroundExperiment.mode(
                interfaceType: .tabs,
                windowHorizontalSizeClass: .compact,
                splitHorizontalSizeClass: .compact,
                isSplitCollapsed: true
            ),
            .inactive
        )
    }
}

final class NavigationBarItemOwnershipIdempotenceTests: XCTestCase {
    func testApplyIfChangedKeepsExistingItemsWhenAssignmentIsIdentical() {
        let navigationItem = UINavigationItem()
        let left = UIBarButtonItem(barButtonSystemItem: .bookmarks, target: nil, action: nil)
        let right = UIBarButtonItem(barButtonSystemItem: .add, target: nil, action: nil)

        NavigationBarItemOwnership.applyIfChanged(
            to: navigationItem,
            left: .item(left),
            right: .item(right),
            animated: false
        )
        let installedLeft = navigationItem.leftBarButtonItem
        let installedRight = navigationItem.rightBarButtonItem

        NavigationBarItemOwnership.applyIfChanged(
            to: navigationItem,
            left: .item(left),
            right: .item(right),
            animated: false
        )

        XCTAssertTrue(navigationItem.leftBarButtonItem === installedLeft)
        XCTAssertTrue(navigationItem.rightBarButtonItem === installedRight)
    }
}

final class StackedNavigationRoutePolicyTests: XCTestCase {
    private func route(
        interfaceType: CommonConfigManager.InterfaceType,
        isPhone: Bool = false,
        hasSplitViewController: Bool = true,
        isSplitCollapsed: Bool = false,
        splitHorizontalSizeClass: UIUserInterfaceSizeClass = .regular,
        windowHorizontalSizeClass: UIUserInterfaceSizeClass = .regular,
        presenterHorizontalSizeClass: UIUserInterfaceSizeClass = .regular
    ) -> StackedNavigationRoute {
        StackedNavigationRoutePolicy.route(
            for: StackedNavigationRouteContext(
                interfaceType: interfaceType,
                isPhone: isPhone,
                hasSplitViewController: hasSplitViewController,
                isSplitCollapsed: isSplitCollapsed,
                splitHorizontalSizeClass: splitHorizontalSizeClass,
                windowHorizontalSizeClass: windowHorizontalSizeClass,
                presenterHorizontalSizeClass: presenterHorizontalSizeClass
            )
        )
    }

    func testTabsAlwaysUsesCurrentNavigationPush() {
        let route = route(interfaceType: .tabs)

        XCTAssertEqual(route, .currentNavigationPush)
        XCTAssertFalse(route.usesNavigationControllerWrapper)
        XCTAssertNil(route.targetColumn)
    }

    func testSplitPhoneUsesCurrentNavigationPush() {
        let route = route(
            interfaceType: .split,
            isPhone: true
        )

        XCTAssertEqual(route, .currentNavigationPush)
        XCTAssertFalse(route.usesNavigationControllerWrapper)
        XCTAssertFalse(route.requiresDeferredPrimaryHide)
        XCTAssertNil(route.targetColumn)
    }

    func testSplitWithoutControllerUsesCurrentNavigationPush() {
        let route = route(
            interfaceType: .split,
            hasSplitViewController: false
        )

        XCTAssertEqual(route, .currentNavigationPush)
        XCTAssertFalse(route.usesNavigationControllerWrapper)
    }

    func testSplitCollapsedUsesCurrentNavigationPush() {
        let route = route(
            interfaceType: .split,
            isSplitCollapsed: true
        )

        XCTAssertEqual(route, .currentNavigationPush)
        XCTAssertFalse(route.usesNavigationControllerWrapper)
        XCTAssertNil(route.targetColumn)
    }

    func testSplitCompactWidthUsesCurrentNavigationPush() {
        let route = route(
            interfaceType: .split,
            splitHorizontalSizeClass: .compact,
            windowHorizontalSizeClass: .compact
        )

        XCTAssertEqual(route, .currentNavigationPush)
        XCTAssertFalse(route.usesNavigationControllerWrapper)
    }

    func testExpandedRegularSplitUsesSecondaryDetailReplacementAndDeferredPrimaryHide() {
        let route = route(interfaceType: .split)

        XCTAssertEqual(route, .splitDetailReplacement)
        XCTAssertTrue(route.usesNavigationControllerWrapper)
        XCTAssertTrue(route.requiresDeferredPrimaryHide)
        XCTAssertEqual(route.targetColumn, .secondary)
    }

    func testExpandedRegularSplitIgnoresCompactPresenterColumn() {
        let route = route(
            interfaceType: .split,
            splitHorizontalSizeClass: .regular,
            windowHorizontalSizeClass: .regular,
            presenterHorizontalSizeClass: .compact
        )

        XCTAssertEqual(route, .splitDetailReplacement)
        XCTAssertTrue(route.usesNavigationControllerWrapper)
        XCTAssertTrue(route.requiresDeferredPrimaryHide)
        XCTAssertEqual(route.targetColumn, .secondary)
    }

    private func chatBackgroundMode(
        route: StackedNavigationRoute,
        interfaceType: CommonConfigManager.InterfaceType,
        continuousSplitBackgroundMode: ContinuousSplitBackgroundMode
    ) -> ChatBackgroundPresentationMode {
        ChatBackgroundPresentationPolicy.mode(
            for: ChatBackgroundPresentationContext(
                route: route,
                interfaceType: interfaceType,
                continuousSplitBackgroundMode: continuousSplitBackgroundMode
            )
        )
    }

    func testSplitCurrentNavigationPushUsesLocalChatBackdropWhenContinuousBackgroundIsActive() {
        XCTAssertEqual(
            chatBackgroundMode(
                route: .currentNavigationPush,
                interfaceType: .split,
                continuousSplitBackgroundMode: .sharedBackdrop
            ),
            .localChatBackdrop
        )
    }

    func testCompactSplitCurrentNavigationPushUsesLocalChatBackdropWithStockCompactLists() {
        XCTAssertEqual(
            chatBackgroundMode(
                route: .currentNavigationPush,
                interfaceType: .split,
                continuousSplitBackgroundMode: .stockCompact
            ),
            .localChatBackdrop
        )
    }

    func testSplitDetailReplacementUsesSharedSplitBackdropWhenContinuousBackgroundIsActive() {
        XCTAssertEqual(
            chatBackgroundMode(
                route: .splitDetailReplacement,
                interfaceType: .split,
                continuousSplitBackgroundMode: .sharedBackdrop
            ),
            .sharedSplitBackdrop
        )
    }

    func testTabsKeepAutomaticChatBackground() {
        XCTAssertEqual(
            chatBackgroundMode(
                route: .currentNavigationPush,
                interfaceType: .tabs,
                continuousSplitBackgroundMode: .sharedBackdrop
            ),
            .automatic
        )
    }

    func testInactiveContinuousBackgroundKeepsAutomaticChatBackground() {
        XCTAssertEqual(
            chatBackgroundMode(
                route: .currentNavigationPush,
                interfaceType: .split,
                continuousSplitBackgroundMode: .inactive
            ),
            .automatic
        )
    }

    func testNonChatStackedDestinationDoesNotReceiveChatBackgroundMode() {
        let mode = ChatBackgroundPresentationPolicy.destinationMode(
            for: UIViewController(),
            context: ChatBackgroundPresentationContext(
                route: .currentNavigationPush,
                interfaceType: .split,
                continuousSplitBackgroundMode: .sharedBackdrop
            )
        )

        XCTAssertNil(mode)
    }
}

final class NavigationExitPolicyTests: XCTestCase {
    func testPresentedModalRootResolvesToDismiss() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .currentNavigationPush,
                isInsidePresentedModalNavigation: true,
                canPopNavigation: false,
                hasSplitViewController: true,
                isSplitCollapsed: false
            )
        )

        XCTAssertEqual(action, .dismissModal)
    }

    func testPushedDestinationInsidePresentedModalNavigationResolvesToPop() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .currentNavigationPush,
                isInsidePresentedModalNavigation: true,
                canPopNavigation: true,
                hasSplitViewController: false,
                isSplitCollapsed: true
            )
        )

        XCTAssertEqual(action, .popNavigationStack)
    }

    func testPushedDestinationWithPreviousControllerResolvesToPop() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .currentNavigationPush,
                isInsidePresentedModalNavigation: false,
                canPopNavigation: true,
                hasSplitViewController: false,
                isSplitCollapsed: true
            )
        )

        XCTAssertEqual(action, .popNavigationStack)
    }

    func testRootControllerInsideNavigationStackDoesNotAttemptPopLoop() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .currentNavigationPush,
                isInsidePresentedModalNavigation: false,
                canPopNavigation: false,
                hasSplitViewController: false,
                isSplitCollapsed: true
            )
        )

        XCTAssertEqual(action, .none)
    }

    func testRegularSplitDetailReplacementResolvesToRevealSplitList() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .splitDetailReplacement,
                isInsidePresentedModalNavigation: false,
                canPopNavigation: false,
                hasSplitViewController: true,
                isSplitCollapsed: false
            )
        )

        XCTAssertEqual(action, .revealSplitList)
    }

    func testCompactSplitPushRouteResolvesToPop() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .currentNavigationPush,
                isInsidePresentedModalNavigation: false,
                canPopNavigation: true,
                hasSplitViewController: true,
                isSplitCollapsed: true
            )
        )

        XCTAssertEqual(action, .popNavigationStack)
    }

    func testSplitDetailReplacementTakesPriorityWhenNavigationAndSplitAreBothPresent() {
        let action = NavigationExitPolicy.action(
            for: NavigationExitPolicyContext(
                route: .splitDetailReplacement,
                isInsidePresentedModalNavigation: false,
                canPopNavigation: true,
                hasSplitViewController: true,
                isSplitCollapsed: false
            )
        )

        XCTAssertEqual(action, .revealSplitList)
    }
}

final class ContactInfoNavigationTests: XCTestCase {
    func testPushedContactInfoKeepsSystemBackAndMovesDevicesActionRight() {
        let configuration = ContactInfoNavigationBarPolicy.configuration(exitAction: .popNavigationStack)

        XCTAssertEqual(configuration.leadingStyle, .systemBack)
        XCTAssertFalse(configuration.leftItemsSupplementBackButton)
        XCTAssertTrue(configuration.showsDevicesActionInRightItems)
        XCTAssertEqual(
            ContactInfoNavigationBarPolicy.devicesButtonAccessibilityIdentifier,
            "contact_info_devices_button"
        )
    }

    func testModalRootContactInfoExposesOneDismissAction() {
        let configuration = ContactInfoNavigationBarPolicy.configuration(exitAction: .dismissModal)

        XCTAssertEqual(configuration.leadingStyle, .dismissModal)
        XCTAssertFalse(configuration.leftItemsSupplementBackButton)
        XCTAssertTrue(configuration.showsDevicesActionInRightItems)
        XCTAssertEqual(
            ContactInfoNavigationBarPolicy.dismissButtonAccessibilityIdentifier,
            "contact_info_dismiss_button"
        )
    }

    func testCallActionDismissesOnlyForModalPresentation() {
        let modalResolution = ContactInfoActionExitPolicy.resolve(
            currentController: UIViewController(),
            presentingViewController: UIViewController(),
            isBlockedByUnrelatedPresentedModal: false,
            exitAction: .dismissModal
        )
        let pushedController = UIViewController()
        let pushedResolution = ContactInfoActionExitPolicy.resolve(
            currentController: pushedController,
            presentingViewController: nil,
            isBlockedByUnrelatedPresentedModal: false,
            exitAction: .popNavigationStack
        )

        XCTAssertEqual(modalResolution.action, .dismissThenPerform)
        XCTAssertEqual(pushedResolution.action, .performImmediately)
        XCTAssertIdentical(pushedResolution.routePresenter, pushedController)
    }

    func testChatActionRoutesAfterModalDismissFromRealPresenter() {
        let currentController = UIViewController()
        let realPresenter = UIViewController()
        let resolution = ContactInfoActionExitPolicy.resolve(
            currentController: currentController,
            presentingViewController: realPresenter,
            isBlockedByUnrelatedPresentedModal: false,
            exitAction: .dismissModal
        )

        XCTAssertEqual(resolution.action, .dismissThenPerform)
        XCTAssertIdentical(resolution.routePresenter, realPresenter)
    }

    func testUnrelatedActiveModalBlocksContactInfoActionRouting() {
        let resolution = ContactInfoActionExitPolicy.resolve(
            currentController: UIViewController(),
            presentingViewController: nil,
            isBlockedByUnrelatedPresentedModal: true,
            exitAction: .popNavigationStack
        )

        XCTAssertEqual(resolution.action, .ignore)
        XCTAssertNil(resolution.routePresenter)
    }
}

final class InfoCardChatSearchRoutingTests: XCTestCase {
    private struct CapturedRoute {
        let owner: String
        let jid: String
        let conversationType: ClientSynchronizationManager.ConversationType
        let openMessageRequest: ChatOpenMessageRequest?
        let configure: ((ChatViewController?) -> Void)?
    }

    private final class LeftMenuSpy: LeftMenuSelectRootScreenDelegate {
        var selectedScreen: String?
        var selectedCategory: String?
        var capturedRoutes: [CapturedRoute] = []

        func selectRootScreenAndCategory(screen key: String, category: String?) -> Bool {
            selectedScreen = key
            selectedCategory = category
            return true
        }

        func openChatlistWithChat(
            owner: String,
            jid: String,
            conversationType: ClientSynchronizationManager.ConversationType,
            openMessageRequest: ChatOpenMessageRequest?,
            navigationSource: ChatOpenNavigationSource,
            configure: ((ChatViewController?) -> Void)?
        ) -> Bool {
            capturedRoutes.append(CapturedRoute(
                owner: owner,
                jid: jid,
                conversationType: conversationType,
                openMessageRequest: openMessageRequest,
                configure: configure
            ))
            return true
        }
    }

    private final class ChatStateSpy: ChangeChatStateProtocol {
        var openSearchBarCallCount = 0

        func openSearchBar() {
            openSearchBarCallCount += 1
        }
    }

    func testRegularContactSearchRouteBuildsConfiguredChatController() {
        let route = InfoCardChatSearchRouting.route(
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular
        )

        let chatController = InfoCardChatSearchRouting.makeChatViewController(
            for: route,
            configure: InfoCardChatSearchRouting.searchModeConfigurator()
        )

        XCTAssertEqual(chatController.owner, "alice@example.com")
        XCTAssertEqual(chatController.jid, "bob@example.com")
        XCTAssertEqual(chatController.conversationType, .regular)
        XCTAssertTrue(chatController.inSearchMode.value)
    }

    func testOmemoContactSearchRouteKeepsEncryptedConversationType() {
        let route = InfoCardChatSearchRouting.route(
            owner: "alice@example.com",
            jid: "secure@example.com",
            conversationType: .omemo
        )

        XCTAssertEqual(route.owner, "alice@example.com")
        XCTAssertEqual(route.jid, "secure@example.com")
        XCTAssertEqual(route.conversationType, .omemo)
    }

    func testGroupSearchRouteBuildsConfiguredGroupChatController() {
        let route = InfoCardChatSearchRouting.route(
            owner: "alice@example.com",
            jid: "team@conference.example.com",
            conversationType: .group
        )

        let chatController = InfoCardChatSearchRouting.makeChatViewController(
            for: route,
            configure: InfoCardChatSearchRouting.searchModeConfigurator()
        )

        XCTAssertEqual(chatController.owner, "alice@example.com")
        XCTAssertEqual(chatController.jid, "team@conference.example.com")
        XCTAssertEqual(chatController.conversationType, .group)
        XCTAssertTrue(chatController.inSearchMode.value)
    }

    func testMatchingCurrentChatReceivesSearchConfigurationWithoutReRouting() throws {
        let chatController = ChatViewController()
        chatController.owner = "alice@example.com"
        chatController.jid = "bob@example.com"
        chatController.conversationType = .regular
        let navigationController = UINavigationController(rootViewController: chatController)
        let route = InfoCardChatSearchRouting.route(
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular
        )

        let matchedChat = try XCTUnwrap(
            InfoCardChatSearchRouting.matchingCurrentChat(
                in: navigationController,
                route: route
            )
        )

        XCTAssertIdentical(matchedChat, chatController)
        XCTAssertFalse(matchedChat.inSearchMode.value)
        InfoCardChatSearchRouting.searchModeConfigurator()(matchedChat)
        XCTAssertTrue(matchedChat.inSearchMode.value)
        XCTAssertNil(
            InfoCardChatSearchRouting.matchingCurrentChat(
                in: navigationController,
                route: InfoCardChatSearchRouting.route(
                    owner: "alice@example.com",
                    jid: "other@example.com",
                    conversationType: .regular
                )
            )
        )

        let groupChatController = ChatViewController()
        groupChatController.owner = "alice@example.com"
        groupChatController.jid = "team@conference.example.com"
        groupChatController.conversationType = .group
        let groupRoute = InfoCardChatSearchRouting.route(
            owner: "alice@example.com",
            jid: "team@conference.example.com",
            conversationType: .group
        )

        XCTAssertIdentical(
            InfoCardChatSearchRouting.matchingCurrentChat(
                in: groupChatController,
                route: groupRoute
            ),
            groupChatController
        )
    }

    func testMatchingCurrentChatFindsChatInsidePresenterContainerAfterModalDismiss() throws {
        let presenter = UIViewController()
        let unrelatedController = UIViewController()
        let chatController = ChatViewController()
        chatController.owner = "alice@example.com"
        chatController.jid = "bob@example.com"
        chatController.conversationType = .regular

        let unrelatedNavigation = UINavigationController(rootViewController: unrelatedController)
        let chatNavigation = UINavigationController(rootViewController: chatController)
        presenter.addChild(unrelatedNavigation)
        unrelatedNavigation.didMove(toParent: presenter)
        presenter.addChild(chatNavigation)
        chatNavigation.didMove(toParent: presenter)

        let matchedChat = try XCTUnwrap(
            InfoCardChatSearchRouting.matchingCurrentChat(
                in: presenter,
                route: InfoCardChatSearchRouting.route(
                    owner: "alice@example.com",
                    jid: "bob@example.com",
                    conversationType: .regular
                )
            )
        )

        XCTAssertIdentical(matchedChat, chatController)
    }

    func testModalGroupInfoSearchResolvesDismissBeforeRoutingFromPresenter() {
        let currentController = UIViewController()
        let presenter = UIViewController()

        let resolution = GroupchatInfoActionExitPolicy.resolve(
            currentController: currentController,
            presentingViewController: presenter,
            exitAction: .dismissModal
        )

        XCTAssertEqual(resolution.action, .dismissThenPerform)
        XCTAssertIdentical(resolution.routePresenter, presenter)
    }

    func testGroupInfoSearchUsesLeftMenuRouteInsteadOfCurrentChatSearchDelegate() throws {
        let controller = GroupchatInfoViewController()
        controller.owner = "alice@example.com"
        controller.jid = "team@conference.example.com"

        let leftMenuSpy = LeftMenuSpy()
        let chatStateSpy = ChatStateSpy()
        controller.leftMenuDelegate = leftMenuSpy
        controller.chatStateDelegate = chatStateSpy

        controller.searchChat()

        XCTAssertEqual(chatStateSpy.openSearchBarCallCount, 0)
        let route = try XCTUnwrap(leftMenuSpy.capturedRoutes.first)
        XCTAssertEqual(leftMenuSpy.capturedRoutes.count, 1)
        XCTAssertEqual(route.owner, "alice@example.com")
        XCTAssertEqual(route.jid, "team@conference.example.com")
        XCTAssertEqual(route.conversationType, .group)

        let chatController = ChatViewController()
        XCTAssertFalse(chatController.inSearchMode.value)
        route.configure?(chatController)
        XCTAssertTrue(chatController.inSearchMode.value)
    }

    func testGroupInfoSearchButtonUsesSharedResidentChatRoute() throws {
        let controller = GroupchatInfoViewController()
        controller.owner = "alice@example.com"
        controller.jid = "team@conference.example.com"
        let leftMenuSpy = LeftMenuSpy()
        controller.leftMenuDelegate = leftMenuSpy

        controller.onSearchButtonTouchUpInside(controller.searchButton)

        let route = try XCTUnwrap(leftMenuSpy.capturedRoutes.first)
        XCTAssertEqual(leftMenuSpy.capturedRoutes.count, 1)
        XCTAssertEqual(route.conversationType, .group)
        let residentChat = ChatViewController()
        residentChat.owner = route.owner
        residentChat.jid = route.jid
        residentChat.conversationType = route.conversationType
        route.configure?(residentChat)
        XCTAssertTrue(residentChat.inSearchMode.value)
    }

    func testGroupInfoSearchReusesResidentGroupChatInSameNavigationStack() {
        let residentChat = ChatViewController()
        residentChat.owner = "alice@example.com"
        residentChat.jid = "team@conference.example.com"
        residentChat.conversationType = .group
        let navigationController = UINavigationController(rootViewController: residentChat)
        let controller = GroupchatInfoViewController()
        controller.owner = residentChat.owner
        controller.jid = residentChat.jid
        navigationController.pushViewController(controller, animated: false)

        controller.searchChat()

        XCTAssertIdentical(navigationController.topViewController, residentChat)
        XCTAssertTrue(residentChat.inSearchMode.value)
    }

    func testLeftMenuRouteContractCarriesNotificationAnchorDuringInitialChatConstruction() throws {
        let request = ChatOpenMessageRequest(
            chatJid: "bob@example.com",
            owner: "alice@example.com",
            conversationType: .regular,
            anchor: ChatMessageAnchorRef(
                messagePrimary: nil,
                archivedId: "archive-anchor",
                messageId: "message-anchor",
                authorId: "bob@example.com",
                bodyFingerprint: nil,
                sourceDate: Date(timeIntervalSinceReferenceDate: 1_000)
            ),
            highlight: true,
            markReadOnVisible: true,
            source: .pushNotification
        )
        let leftMenuSpy = LeftMenuSpy()

        leftMenuSpy.openChatlistWithChat(
            owner: request.owner,
            jid: request.chatJid,
            conversationType: request.conversationType,
            openMessageRequest: request,
            configure: nil
        )

        let route = try XCTUnwrap(leftMenuSpy.capturedRoutes.first)
        XCTAssertEqual(route.openMessageRequest, request)
    }
}

@MainActor
final class InfoCardSearchAccessibilityTests: XCTestCase {
    func testContactAndGroupInfoSearchButtonsExposeStableAutomationIdentifiersAndLabels() {
        let contactInfo = ContactInfoViewController()
        let groupInfo = GroupchatInfoViewController()

        XCTAssertEqual(contactInfo.searchButton.accessibilityIdentifier, "contact_info_search_button")
        XCTAssertEqual(groupInfo.searchButton.accessibilityIdentifier, "group_info_search_button")
        assertMeaningfulAccessibilityLabel(contactInfo.searchButton)
        assertMeaningfulAccessibilityLabel(groupInfo.searchButton)
    }

    func testChatSearchChromeIdentifiersSurviveSearchModeSubmitLoadingResultsAndCancel() throws {
        let controller = ChatViewController()
        controller.owner = "owner@example.com"
        controller.jid = "alexey.boldin@example.com"
        controller.conversationType = .regular
        let navigationController = UINavigationController(rootViewController: controller)

        navigationController.loadViewIfNeeded()
        controller.loadViewIfNeeded()
        controller.activateSearchModeFromExternalRoute(activateKeyboard: false, animated: false)

        let searchBar = controller.searchNavigationView
        let searchPanel = controller.xabberInputView.searchPanel
        XCTAssertNil(controller.navigationItem.titleView)
        assertSearchInputIdentifiers(searchBar)
        assertSearchPanelIdentifiers(searchPanel)

        searchBar.text = "alexey"
        controller.submitSearchTextFromSearchInput(searchBar.text)
        assertSearchInputIdentifiers(searchBar)
        assertSearchPanelIdentifiers(searchPanel)

        controller.applyInChatSearchPanelRenderState(.loading)
        assertSearchPanelIdentifiers(searchPanel)

        controller.searchMessagesQueue = [
            makeSearchMessage(index: 0),
            makeSearchMessage(index: 1)
        ]
        controller.selectedSearchResultId = controller.searchMessagesQueue[1].archivedId
        controller.applySearchResultsPanelState(isLoadingContext: true)
        assertSearchPanelIdentifiers(searchPanel)

        controller.showSkeletonObserver.accept(false)
        searchBar.cancelButton.sendActions(for: .touchUpInside)
        XCTAssertFalse(controller.inSearchMode.value)
        XCTAssertEqual(controller.xabberInputView.state, .normal)
        XCTAssertTrue(searchPanel.isHidden)
        assertSearchInputIdentifiers(searchBar)
        assertSearchPanelIdentifiers(searchPanel)
    }

    private func assertMeaningfulAccessibilityLabel(
        _ item: UIBarButtonItem,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        let label = item.accessibilityLabel?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        XCTAssertFalse(label.isEmpty, file: file, line: line)
    }

    private func assertSearchInputIdentifiers(
        _ searchBar: ChatSearchNavigationView,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(
            searchBar.textField.accessibilityIdentifier,
            "chat_search_input",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchBar.submitButton.accessibilityIdentifier,
            "chat_search_submit",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchBar.clearButton.accessibilityIdentifier,
            "chat_search_clear",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchBar.cancelButton.accessibilityIdentifier,
            "chat_search_cancel",
            file: file,
            line: line
        )
    }

    private func assertSearchPanelIdentifiers(
        _ searchPanel: ModernXabberInputView.SearchPanel,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(
            searchPanel.accessibilityIdentifier,
            "chat_search_results_panel",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchPanel.cancelButton.accessibilityIdentifier,
            "chat_search_cancel",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchPanel.counterLabel.accessibilityIdentifier,
            "chat_search_results_count",
            file: file,
            line: line
        )
        XCTAssertEqual(
            searchPanel.activityIndicator.accessibilityIdentifier,
            "chat_search_loading",
            file: file,
            line: line
        )
    }

    private func makeSearchMessage(index: Int) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = "primary-\(index)"
        message.owner = "owner@example.com"
        message.opponent = "alexey.boldin@example.com"
        message.conversationType = .regular
        message.messageType = MessageStorageItem.MessageDisplayType.text.rawValue
        message.archivedId = "archive-\(index)"
        message.messageId = "message-\(index)"
        message.date = Date(timeIntervalSince1970: TimeInterval(1_711_283_200 + index))
        return message
    }

    private func findView(withAccessibilityIdentifier identifier: String, in view: UIView) -> UIView? {
        if view.accessibilityIdentifier == identifier {
            return view
        }

        for subview in view.subviews {
            if let match = findView(withAccessibilityIdentifier: identifier, in: subview) {
                return match
            }
        }

        return nil
    }
}

final class ChatSearchModeActivationTests: XCTestCase {
    func testExternalActivationBeforeViewLoadRetainsRequestWithoutSubmittingQuery() {
        let controller = ChatViewController()

        controller.activateSearchModeFromExternalRoute(
            activateKeyboard: true,
            animated: false,
            initialQuery: "needle"
        )

        XCTAssertTrue(controller.inSearchMode.value)
        XCTAssertEqual(controller.pendingSearchActivationRequest?.activateKeyboard, true)
        XCTAssertEqual(controller.pendingSearchActivationRequest?.animated, false)
        XCTAssertEqual(controller.pendingSearchActivationRequest?.initialQuery, "needle")
        XCTAssertNil(controller.searchTextObserver.value)
    }

    func testExternalInitialQueryPrefillsDraftWithoutStartingSearchAfterViewLoads() {
        let controller = ChatViewController()
        let navigationController = UINavigationController(rootViewController: controller)
        controller.activateSearchModeFromExternalRoute(
            activateKeyboard: false,
            animated: false,
            initialQuery: "needle"
        )

        navigationController.loadViewIfNeeded()
        controller.loadViewIfNeeded()
        controller.configureSearchModeForCurrentActivation(
            defaultActivateKeyboard: false,
            defaultAnimated: false
        )

        XCTAssertEqual(controller.searchPresentationState.draftQuery, "needle")
        XCTAssertEqual(controller.searchPresentationState.query, "")
        XCTAssertEqual(controller.searchPresentationState.resultPhase, .idle)
        XCTAssertEqual(controller.searchNavigationView.text, "needle")
        XCTAssertNil(controller.searchTextObserver.value)
        XCTAssertNil(controller.currentSearchQueryId)
    }

    func testRepeatedExternalActivationIsIdempotentAndPreservesExistingQueryWhenNoInitialQueryIsProvided() {
        let controller = ChatViewController()
        controller.searchTextObserver.accept("existing")

        controller.activateSearchModeFromExternalRoute(
            activateKeyboard: false,
            animated: false,
            initialQuery: nil
        )
        controller.activateSearchModeFromExternalRoute(
            activateKeyboard: false,
            animated: false,
            initialQuery: nil
        )

        XCTAssertTrue(controller.inSearchMode.value)
        XCTAssertEqual(controller.searchTextObserver.value, "existing")
        XCTAssertEqual(controller.pendingSearchActivationRequest?.activateKeyboard, false)
        XCTAssertEqual(controller.pendingSearchActivationRequest?.animated, false)
        XCTAssertNil(controller.pendingSearchActivationRequest?.initialQuery)
    }

    func testCardSearchConfiguratorUsesDurableExternalActivationRequest() throws {
        let chatController = ChatViewController()

        InfoCardChatSearchRouting.searchModeConfigurator()(chatController)

        let request = try XCTUnwrap(chatController.pendingSearchActivationRequest)
        XCTAssertTrue(chatController.inSearchMode.value)
        XCTAssertTrue(request.activateKeyboard)
        XCTAssertTrue(request.animated)
        XCTAssertNil(request.initialQuery)
    }

    func testCancelSearchModeClearsSearchStateWithoutClosingController() {
        let controller = ChatViewController()
        let navigationController = UINavigationController(rootViewController: controller)
        controller.inSearchMode.accept(true)
        controller.searchTextObserver.accept("needle")
        controller.currentSearchQueryId = "query-1"

        controller.cancelSearchModeFromSearchUI()

        XCTAssertFalse(controller.inSearchMode.value)
        XCTAssertNil(controller.searchTextObserver.value)
        XCTAssertNil(controller.currentSearchQueryId)
        XCTAssertIdentical(navigationController.topViewController, controller)
        XCTAssertNil(controller.presentingViewController)
    }

