    private func makeControllerWithSearchResults(
        count: Int,
        selectedIndex: Int
    ) -> ChatViewController {
        let controller = ChatViewController()
        controller.owner = "owner@example.com"
        controller.jid = "contact@example.com"
        controller.conversationType = .regular
        controller.searchTextObserver.accept("needle")
        controller.currentSearchQueryId = "query"
        controller.searchMessagesQueue = (0..<count).map { index in
            makeMessage(index: index)
        }
        controller.selectedSearchResultId = controller.searchMessagesQueue[selectedIndex].archivedId
        var presentationState = ChatSearchPresentationState.inactive
        presentationState.reduce(.activate)
        presentationState.reduce(.queryChanged("needle"))
        presentationState.reduce(
            .resultsReceived(
                count: count,
                generation: presentationState.generation
            )
        )
        presentationState.reduce(
            .resultCommitted(
                index: selectedIndex,
                generation: presentationState.generation
            )
        )
        controller.searchPresentationState = presentationState
        return controller
    }

    private func makeSearchOpenRequest(
        controller: ChatViewController,
        index: Int
    ) -> ChatOpenMessageRequest {
        let item = controller.searchMessagesQueue[index]
        return ChatOpenMessageRequest(
            chatJid: controller.jid,
            owner: controller.owner,
            conversationType: controller.conversationType,
            anchor: ChatMessageAnchorRef(
                messagePrimary: nil,
                archivedId: item.archivedId,
                messageId: nil,
                authorId: nil,
                bodyFingerprint: nil,
                sourceDate: item.date
            ),
            highlight: true,
            markReadOnVisible: false,
            source: .search
        )
    }

    private func makeMessage(index: Int) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = "primary-\(index)"
        message.owner = "owner@example.com"
        message.opponent = "contact@example.com"
        message.conversationType = .regular
        message.messageType = MessageStorageItem.MessageDisplayType.text.rawValue
        message.archivedId = archiveID(index: index)
        message.messageId = "message-\(index)"
        message.date = Date(timeIntervalSince1970: TimeInterval(1_711_283_200 + index))
        return message
    }

    private func makeDatasource(index: Int) -> ChatViewController.Datasource {
        ChatViewController.Datasource(
            primary: "primary-\(index)",
            jid: "contact@example.com",
            owner: "owner@example.com",
            outgoing: false,
            sender: Sender(id: "contact@example.com", displayName: "Contact"),
            messageId: "message-\(index)",
            sentDate: Date(timeIntervalSince1970: TimeInterval(1_711_283_200 + index)),
            editDate: nil,
            kind: .attributedText(NSAttributedString(string: "needle \(index)")),
            withAuthor: false,
            withAvatar: false,
            error: false,
            errorType: "",
            canPinMessage: false,
            canEditMessage: false,
            canDeleteMessage: false,
            forwards: [],
            isOutgoing: false,
            isEdited: false,
            groupchatAuthorRole: "",
            groupchatAuthorId: "",
            groupchatAuthorNickname: "",
            groupchatAuthorBadge: "",
            isHasAttachedMessages: false,
            isDownloaded: true,
            state: .read,
            searchString: "needle",
            errorMetadata: nil,
            burnDate: -1,
            afterburnInterval: -1,
            archivedId: archiveID(index: index),
            queryIds: nil,
            isRead: true,
            selectedSearchResultId: nil,
            isHadHistoryGap: false,
            tailed: false,
            isFakeMessage: false,
            images: [],
            videos: [],
            files: [],
            audios: [],
            timeMarkerText: NSAttributedString(string: ""),
            indicator: .none,
            avatarUrl: nil,
            attributedAuthor: nil
        )
    }

    private func archiveID(index: Int) -> String {
        String(1_711_283_200_000_000 + index)
    }
}

private final class SearchNavigationSpyMessagesCollectionView: MessagesCollectionView {
    private(set) var scrollToItemCallCount = 0
    private(set) var explicitSetContentOffsetCallCount = 0
    private(set) var recordedSetContentOffsetAnimations: [Bool] = []
    private var isRecording = false

    override func scrollToItem(
        at indexPath: IndexPath,
        at scrollPosition: UICollectionView.ScrollPosition,
        animated: Bool
    ) {
        if isRecording {
            scrollToItemCallCount += 1
        }
    }

    override func setContentOffset(_ contentOffset: CGPoint, animated: Bool) {
        if isRecording {
            explicitSetContentOffsetCallCount += 1
            recordedSetContentOffsetAnimations.append(animated)
        }
        super.setContentOffset(contentOffset, animated: animated)
    }

    func seedContentOffset(_ contentOffset: CGPoint) {
        super.setContentOffset(contentOffset, animated: false)
    }

    func beginRecording() {
        scrollToItemCallCount = 0
        explicitSetContentOffsetCallCount = 0
        recordedSetContentOffsetAnimations = []
        isRecording = true
    }
}

@MainActor

final class ChatSearchInputBarViewTests: XCTestCase {
    func testStructureUsesOneGlassFieldWithInternalSearchClearAndDetachedCancel() throws {
        let bar = ChatSearchNavigationView(
            frame: CGRect(x: 0, y: 0, width: 390, height: ChatSearchNavigationLayout.nominalHeight)
        )
        bar.render(.init(query: "test", isRemoteSearching: false))
        bar.layoutIfNeeded()

        XCTAssertEqual(bar.surfaceView.layer.cornerRadius, NativeGlassBarStyle.cornerRadius, accuracy: 0.001)
        XCTAssertEqual(bar.textField.accessibilityIdentifier, "chat_search_input")
        XCTAssertEqual(bar.submitButton.accessibilityIdentifier, "chat_search_submit")
        XCTAssertEqual(bar.clearButton.accessibilityIdentifier, "chat_search_clear")
        XCTAssertEqual(bar.cancelButton.accessibilityIdentifier, "chat_search_cancel")
        XCTAssertTrue(bar.submitButton.isDescendant(of: bar.surfaceView.contentView))
        XCTAssertTrue(bar.clearButton.isDescendant(of: bar.surfaceView.contentView))
        XCTAssertFalse(bar.cancelButton.isDescendant(of: bar.surfaceView))
        XCTAssertEqual(bar.surfaceView.frame, CGRect(x: 16, y: 6, width: 306, height: 44))
        XCTAssertEqual(bar.cancelButton.frame, CGRect(x: 330, y: 6, width: 44, height: 44))

        if #available(iOS 26.0, *) {
            let glassEffect = try XCTUnwrap(bar.surfaceView.effect as? UIGlassEffect)
            XCTAssertTrue(glassEffect.isInteractive)
            XCTAssertEqual(glassEffect.tintColor, XabberGlassStyle.nativeGlassTintColor)
        } else {
            XCTAssertTrue(bar.surfaceView.effect is UIBlurEffect)
        }
    }

    func testIPhone16eWidthKeepsFixedSingleLineInputGeometry() {
        let bar = ChatSearchNavigationView(
            frame: CGRect(x: 0, y: 0, width: 390, height: ChatSearchNavigationLayout.nominalHeight)
        )

        bar.text = Array(repeating: "long search query", count: 60).joined(separator: " ")
        bar.layoutIfNeeded()

        XCTAssertEqual(bar.intrinsicContentSize.height, 60, accuracy: 0.001)
        XCTAssertEqual(bar.textField.maxLines, 1)
        XCTAssertEqual(bar.textField.frame.height, 44, accuracy: 0.001)
        XCTAssertEqual(bar.submitButton.frame, CGRect(x: 0, y: 0, width: 44, height: 44))
        XCTAssertEqual(bar.clearButton.frame.maxX, bar.surfaceView.bounds.maxX, accuracy: 0.001)
    }

    func testDecorativeSubmitButtonDoesNotSubmitAndReturnKeepsCurrentText() {
        let bar = ChatSearchNavigationView(
            frame: CGRect(x: 0, y: 0, width: 390, height: ChatSearchNavigationLayout.nominalHeight)
        )
        var submittedTexts: [String] = []
        bar.onSubmit = { submittedTexts.append($0) }

        bar.text = "needle"
        bar.submitButton.sendActions(for: .touchUpInside)
        let shouldReturn = bar.textField.delegate?.textFieldShouldReturn?(bar.textField)

        XCTAssertEqual(submittedTexts, ["needle"])
        XCTAssertEqual(shouldReturn, true)
        XCTAssertEqual(bar.text, "needle")
        XCTAssertFalse(bar.submitButton.isUserInteractionEnabled)
    }

    func testWhitespaceSubmitClearsControllerSearchStateWithoutStartingQuery() {
        let controller = ChatViewController()
        controller.searchTextObserver.accept("old")
        controller.currentSearchQueryId = "query-1"

        XCTAssertFalse(controller.isViewLoaded)
        controller.submitSearchTextFromSearchInput("  \n\t  ")

        XCTAssertFalse(controller.isViewLoaded)
        XCTAssertNil(controller.searchTextObserver.value)
        XCTAssertNil(controller.currentSearchQueryId)
    }

    func testSearchModeInstallsFixedTopChromeAndClearsStaleNavbarItems() throws {
        let controller = ChatViewController()
        let navigationController = UINavigationController(rootViewController: controller)
        let staleRight = UIBarButtonItem(title: "stale", style: .plain, target: nil, action: nil)
        controller.navigationItem.rightBarButtonItem = staleRight

        navigationController.loadViewIfNeeded()
        controller.loadViewIfNeeded()
        controller.activateSearchModeFromExternalRoute(activateKeyboard: false, animated: false)

        let bar = controller.searchNavigationView
        XCTAssertNil(controller.navigationItem.leftBarButtonItem)
        XCTAssertNil(controller.navigationItem.rightBarButtonItem)
        XCTAssertNil(controller.navigationItem.rightBarButtonItems)
        XCTAssertNil(controller.navigationItem.titleView)
        XCTAssertFalse(controller.navigationItem.rightBarButtonItems?.contains(where: { $0 === staleRight }) ?? false)
        XCTAssertTrue(controller.navigationItem.hidesBackButton)
        XCTAssertIdentical(bar.superview, controller.view)
        XCTAssertFalse(bar.isHidden)
        XCTAssertEqual(
            try XCTUnwrap(controller.searchInputBarHeightConstraint).constant,
            ChatSearchNavigationLayout.nominalHeight,
            accuracy: 0.001
        )
        XCTAssertNotNil(controller.searchInputBarBottomConstraint)
        XCTAssertEqual(bar.textField.accessibilityIdentifier, "chat_search_input")
        XCTAssertEqual(bar.submitButton.accessibilityIdentifier, "chat_search_submit")
        XCTAssertEqual(bar.cancelButton.accessibilityIdentifier, "chat_search_cancel")
        XCTAssertTrue(controller.xabberInputView.searchPanel.cancelButton.isHidden)
    }
}

@MainActor
final class ChatSearchBottomPanelTests: XCTestCase {
    func testPanelUsesTwoSeparatedFortyPointCapsulesAtIPhone16eWidth() throws {
        let harness = makePanelHarness()
        let panel = harness.panel

        panel.applyRenderState(
            .results(current: 0, total: 12, isLoadingContext: false),
            surfaceMode: .chat,
            animated: false
        )
        harness.layout()

        let effectViews = visualEffectViews(in: panel)
        XCTAssertTrue(effectViews.contains { $0 === panel.leadingSurfaceView })
        XCTAssertTrue(effectViews.contains { $0 === panel.trailingSurfaceView })
        XCTAssertEqual(panel.leadingSurfaceView.layer.cornerRadius, 20, accuracy: 0.001)
        XCTAssertEqual(panel.trailingSurfaceView.layer.cornerRadius, 20, accuracy: 0.001)
        XCTAssertEqual(panel.calendarButton.accessibilityIdentifier, "chat_search_calendar_button")
        XCTAssertEqual(panel.counterLabel.accessibilityIdentifier, "chat_search_results_count")
        XCTAssertEqual(panel.viewModeButton.accessibilityIdentifier, "chat_search_view_mode_control")
        XCTAssertEqual(panel.intrinsicContentSize.height, 40, accuracy: 0.001)
        XCTAssertEqual(panel.bounds.height, 40, accuracy: 0.001)
        XCTAssertEqual(panel.calendarButton.frame.size, CGSize(width: 40, height: 40))
        XCTAssertLessThanOrEqual(panel.leadingSurfaceView.frame.maxX, panel.trailingSurfaceView.frame.minX)

        if #available(iOS 26.0, *) {
            XCTAssertTrue(try XCTUnwrap(panel.leadingSurfaceView.effect as? UIGlassEffect).isInteractive)
            XCTAssertTrue(try XCTUnwrap(panel.trailingSurfaceView.effect as? UIGlassEffect).isInteractive)
        } else {
            XCTAssertTrue(panel.leadingSurfaceView.effect is UIBlurEffect)
            XCTAssertTrue(panel.trailingSurfaceView.effect is UIBlurEffect)
        }
    }

    func testCalendarAndViewModeCallbacksReplaceLegacyBottomControls() {
        let harness = makePanelHarness()
        let panel = harness.panel
        var calendarCount = 0
        var modeCount = 0
        panel.onCalendarCallback = { calendarCount += 1 }
        panel.onChangeViewStateCallback = { modeCount += 1 }
        panel.applyRenderState(
            .results(current: 0, total: 2, isLoadingContext: false),
            surfaceMode: .chat,
            animated: false
        )

        panel.calendarButton.sendActions(for: .touchUpInside)
        panel.viewModeButton.sendActions(for: .touchUpInside)

        XCTAssertEqual(calendarCount, 1)
        XCTAssertEqual(modeCount, 1)
        XCTAssertNil(panel.cancelButton.superview)
    }

    func testSearchPanelFrameMatchesComposerWidthAndCentersFortyPointBar() {
        let inputView = ModernXabberInputView(
            frame: CGRect(
                x: 0,
                y: 0,
                width: 358,
                height: ModernXabberInputView.defaultBarHeight
            )
        )

        inputView.updateBottomPanels(withOffset: 0)

        XCTAssertEqual(inputView.searchPanel.frame.minX, inputView.bounds.minX, accuracy: 0.001)
        XCTAssertEqual(inputView.searchPanel.frame.maxX, inputView.bounds.maxX, accuracy: 0.001)
        XCTAssertEqual(inputView.searchPanel.frame.width, inputView.bounds.width, accuracy: 0.001)
        XCTAssertEqual(inputView.searchPanel.frame.height, 40, accuracy: 0.001)
        XCTAssertEqual(
            inputView.searchPanel.frame.midY,
            NativeGlassBarStyle.minimumHeight / 2,
            accuracy: 0.001
        )
    }

    private func makePanelHarness() -> PanelHarness {
        PanelHarness(
            width: 358,
            height: 40
        )
    }

    private func visualEffectViews(in view: UIView) -> [UIVisualEffectView] {
        view.subviews.reduce(view is UIVisualEffectView ? [view as! UIVisualEffectView] : []) { result, subview in
            result + visualEffectViews(in: subview)
        }
    }

    @MainActor
    private final class PanelHarness {
        let container: UIView
        let panel: ModernXabberInputView.SearchPanel

        init(width: CGFloat, height: CGFloat) {
            self.container = UIView(frame: CGRect(x: 0, y: 0, width: width, height: height))
            self.panel = ModernXabberInputView.SearchPanel(frame: .zero)
            self.panel.translatesAutoresizingMaskIntoConstraints = false
            self.container.addSubview(self.panel)
            NSLayoutConstraint.activate([
                self.panel.leadingAnchor.constraint(equalTo: self.container.leadingAnchor),
                self.panel.trailingAnchor.constraint(equalTo: self.container.trailingAnchor),
                self.panel.topAnchor.constraint(equalTo: self.container.topAnchor),
                self.panel.bottomAnchor.constraint(equalTo: self.container.bottomAnchor)
            ])
            self.layout()
        }

        func layout() {
            self.container.setNeedsLayout()
            self.container.layoutIfNeeded()
            self.panel.setNeedsLayout()
            self.panel.layoutIfNeeded()
        }
    }
}

final class NotificationsNavigationTests: XCTestCase {
    func testBackPolicyPreservesModalDismiss() {
        let action = NotificationsBackPolicy.action(
            exitAction: .dismissModal,
            hasChatsRootFallback: true
        )

        XCTAssertEqual(action, .dismissModal)
    }

    func testBackPolicyPopsLocalStackBeforeChatsFallback() {
        let action = NotificationsBackPolicy.action(
            exitAction: .popNavigationStack,
            hasChatsRootFallback: true
        )

        XCTAssertEqual(action, .popNavigationStack)
    }

    func testBackPolicyFallsBackToChatsOnlyForRootSectionWithoutExitAction() {
        XCTAssertEqual(
            NotificationsBackPolicy.action(exitAction: .none, hasChatsRootFallback: true),
            .selectChatsRoot
        )
        XCTAssertEqual(
            NotificationsBackPolicy.action(exitAction: .none, hasChatsRootFallback: false),
            .none
        )
    }

    func testDetailPresentationUsesModalContainedRoutesForContactAndDeviceNotifications() {
        XCTAssertEqual(
            NotificationsDetailPresentationPolicy.presentation(
                sectionKey: "subscribtion_requests",
                category: .info
            ),
            .modalContainedContactInfo
        )
        XCTAssertEqual(
            NotificationsDetailPresentationPolicy.presentation(
                sectionKey: "notifications",
                category: .device
            ),
            .modalContainedDevices
        )
    }

    func testDetailPresentationUsesMentionChatRouteOnlyForMentionNotifications() {
        XCTAssertEqual(
            NotificationsDetailPresentationPolicy.presentation(
                sectionKey: "notifications",
                category: .mention
            ),
            .mentionChat
        )
        XCTAssertEqual(
            NotificationsDetailPresentationPolicy.presentation(
                sectionKey: "notifications",
                category: .info
            ),
            .none
        )
    }

    func testMentionRoutePolicyBlocksRouteBehindUnrelatedModal() {
        XCTAssertEqual(
            NotificationsMentionRoutePolicy.action(isBlockedByUnrelatedPresentedModal: true),
            .ignore
        )
        XCTAssertEqual(
            NotificationsMentionRoutePolicy.action(isBlockedByUnrelatedPresentedModal: false),
            .openChat
        )
    }
}

