@MainActor
final class DevicesSecurityLayoutTests: XCTestCase {
    func testDevicesListUsesSelfSizingRowsAndReadableEstimates() {
        let controller = DevicesListViewController()
        controller.loadViewIfNeeded()
        controller.configure(for: "layout@example.test")
        controller.datasource = [
            DevicesListViewController.Datasource(
                .current,
                title: "This device",
                value: String(repeating: "Current device explanation ", count: 8),
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .token,
                        title: " ",
                        value: String(repeating: "resource ", count: 12),
                        editable: false
                    ),
                    DevicesListViewController.Datasource(
                        .button,
                        title: "Terminate all other sessions",
                        value: "terminate_all_sessions",
                        editable: false
                    )
                ]
            ),
            DevicesListViewController.Datasource(
                .token,
                title: "Active devices",
                value: String(repeating: "Active devices section explanation ", count: 8),
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .session,
                        title: "Non-Verified Devices Connected",
                        value: String(repeating: "Review and verify every connected device. ", count: 8),
                        editable: false
                    ),
                    DevicesListViewController.Datasource(
                        .token,
                        title: "Desktop client with a long resource title",
                        value: String(repeating: "Long device metadata ", count: 10),
                        editable: false
                    )
                ]
            ),
            DevicesListViewController.Datasource(
                .button,
                title: "",
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .button,
                        title: "Quit account",
                        value: "quit",
                        editable: false
                    )
                ]
            )
        ]

        XCTAssertEqual(controller.tableView.rowHeight, UITableView.automaticDimension)
        XCTAssertGreaterThanOrEqual(controller.tableView.estimatedRowHeight, 44)
        XCTAssertGreaterThan(controller.tableView.estimatedSectionHeaderHeight, 0)
        XCTAssertGreaterThan(controller.tableView.estimatedSectionFooterHeight, 0)
        XCTAssertEqual(
            controller.tableView(controller.tableView, heightForRowAt: IndexPath(row: 0, section: 0)),
            UITableView.automaticDimension
        )
        XCTAssertEqual(
            controller.tableView(controller.tableView, heightForRowAt: IndexPath(row: 1, section: 0)),
            UITableView.automaticDimension
        )
        XCTAssertEqual(
            controller.tableView(controller.tableView, heightForRowAt: IndexPath(row: 0, section: 1)),
            UITableView.automaticDimension
        )
        XCTAssertEqual(
            controller.tableView(controller.tableView, heightForRowAt: IndexPath(row: 0, section: 2)),
            UITableView.automaticDimension
        )
    }

    func testTerminateAllOtherSessionsCellIsSubordinateButtonWithMinimumTarget() throws {
        let controller = DevicesListViewController()
        controller.loadViewIfNeeded()
        controller.configure(for: "terminate-all-layout@example.test")
        controller.datasource = [
            DevicesListViewController.Datasource(
                .current,
                title: "This device",
                value: "Only other device sessions are signed out.",
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .token,
                        title: " ",
                        value: "resource",
                        editable: false
                    ),
                    DevicesListViewController.Datasource(
                        .button,
                        title: String(repeating: "Terminate all other sessions ", count: 4),
                        value: "terminate_all_sessions",
                        editable: false
                    )
                ]
            )
        ]

        let cell = try XCTUnwrap(
            controller.tableView(
                controller.tableView,
                cellForRowAt: IndexPath(row: 1, section: 0)
            ) as? ButtonTableViewCell
        )
        cell.bounds = CGRect(x: 0, y: 0, width: 320, height: 1)
        cell.contentView.bounds = cell.bounds
        cell.setNeedsLayout()
        cell.layoutIfNeeded()

        let fittingSize = cell.contentView.systemLayoutSizeFitting(
            CGSize(width: 320, height: UIView.layoutFittingCompressedSize.height),
            withHorizontalFittingPriority: .required,
            verticalFittingPriority: .fittingSizeLevel
        )

        XCTAssertTrue(cell.isAccessibilityElement)
        XCTAssertTrue(cell.accessibilityTraits.contains(.button))
        XCTAssertFalse(cell.accessibilityTraits.contains(.staticText))
        XCTAssertEqual(cell.accessibilityIdentifier, "devices_terminate_all_other_sessions_button")
        XCTAssertTrue(cell.titleLabel.adjustsFontForContentSizeCategory)
        XCTAssertEqual(cell.titleLabel.numberOfLines, 0)
        XCTAssertEqual(cell.titleLabel.font.pointSize, UIFont.preferredFont(forTextStyle: .callout).pointSize)
        XCTAssertGreaterThanOrEqual(cell.minimumEffectiveHeight, 44)
        XCTAssertGreaterThan(fittingSize.height, 44)
    }

    func testDeviceDetailUsesSelfSizingRowsAndReadableEstimates() throws {
        let controller = DeviceDetailViewController()
        controller.loadViewIfNeeded()
        let tableView = try XCTUnwrap(firstTableView(in: controller.view))
        controller.datasource = [
            [
                DeviceDetailViewController.Datasource(
                    title: "Fingerprint",
                    value: String(repeating: "ABCD ", count: 18),
                    key: "omemo_fingerprint"
                )
            ],
            [
                DeviceDetailViewController.Datasource(
                    title: "Terminate session",
                    value: nil,
                    key: "terminate"
                )
            ]
        ]

        XCTAssertEqual(tableView.rowHeight, UITableView.automaticDimension)
        XCTAssertGreaterThanOrEqual(tableView.estimatedRowHeight, 44)
        XCTAssertGreaterThan(tableView.estimatedSectionHeaderHeight, 0)
        XCTAssertGreaterThan(tableView.estimatedSectionFooterHeight, 0)
        XCTAssertEqual(
            controller.tableView(tableView, heightForRowAt: IndexPath(row: 0, section: 0)),
            UITableView.automaticDimension
        )
        XCTAssertEqual(
            controller.tableView(tableView, heightForRowAt: IndexPath(row: 0, section: 1)),
            UITableView.automaticDimension
        )
    }

    private func firstTableView(in view: UIView) -> UITableView? {
        if let tableView = view as? UITableView {
            return tableView
        }

        for subview in view.subviews {
            if let tableView = firstTableView(in: subview) {
                return tableView
            }
        }

        return nil
    }
}

@MainActor
final class DeviceInfoTableCellLayoutTests: XCTestCase {
    func testDeviceLabelsAdjustForDynamicTypeAndWrap() {
        let cell = DeviceInfoTableCell(style: .default, reuseIdentifier: DeviceInfoTableCell.cellName)

        XCTAssertTrue(cell.clientLabel.adjustsFontForContentSizeCategory)
        XCTAssertTrue(cell.descriptionLabel.adjustsFontForContentSizeCategory)
        XCTAssertEqual(cell.clientLabel.numberOfLines, 0)
        XCTAssertEqual(cell.descriptionLabel.numberOfLines, 0)
    }

    func testLongDeviceTextProducesSelfSizingHeightAboveOldFixedRows() {
        let cell = DeviceInfoTableCell(style: .default, reuseIdentifier: DeviceInfoTableCell.cellName)
        cell.configure(
            client: "Xabber",
            device: String(repeating: "Very long iPhone device name ", count: 5),
            description: "",
            ip: "2001:db8:85a3::8a2e:370:7334",
            lastAuth: Date(timeIntervalSinceNow: -3_600),
            current: false,
            editable: true,
            isOnline: true,
            trustState: .trusted
        )
        cell.bounds = CGRect(x: 0, y: 0, width: 320, height: 1)
        cell.contentView.bounds = cell.bounds
        cell.setNeedsLayout()
        cell.layoutIfNeeded()

        let fittingSize = cell.contentView.systemLayoutSizeFitting(
            CGSize(width: 320, height: UIView.layoutFittingCompressedSize.height),
            withHorizontalFittingPriority: .required,
            verticalFittingPriority: .fittingSizeLevel
        )

        XCTAssertGreaterThan(fittingSize.height, 60)
    }

    func testRepeatedConfigureDoesNotAddDuplicateStaticConstraints() {
        let cell = DeviceInfoTableCell(style: .default, reuseIdentifier: DeviceInfoTableCell.cellName)

        cell.configure(
            client: "Xabber",
            device: "iPhone",
            description: "",
            ip: "192.0.2.1",
            lastAuth: Date(),
            current: false,
            editable: true,
            isOnline: true,
            trustState: .trusted
        )
        let firstWidthConstraintCount = rightStackWidthConstraintCount(in: cell)

        cell.configure(
            client: "Xabber",
            device: "iPad",
            description: "",
            ip: "192.0.2.2",
            lastAuth: Date(),
            current: false,
            editable: true,
            isOnline: false,
            trustState: .unknown
        )

        XCTAssertEqual(firstWidthConstraintCount, 1)
        XCTAssertEqual(rightStackWidthConstraintCount(in: cell), 1)
    }

    func testTrustIconStateResetsAcrossReuse() {
        let cell = DeviceInfoTableCell(style: .default, reuseIdentifier: DeviceInfoTableCell.cellName)

        cell.configure(
            client: "Xabber",
            device: "iPhone",
            description: "",
            ip: "192.0.2.1",
            lastAuth: Date(),
            current: false,
            editable: true,
            isOnline: true,
            trustState: .unknown
        )
        XCTAssertFalse(cell.trustIconView.isHidden)
        XCTAssertNotNil(cell.trustIconView.image)

        cell.prepareForReuse()
        cell.configure(
            client: "Xabber",
            device: "Desktop",
            description: "",
            ip: "192.0.2.3",
            lastAuth: Date(),
            current: false,
            editable: false,
            isOnline: false,
            trustState: nil,
            hasBundle: nil
        )

        XCTAssertTrue(cell.trustIconView.isHidden)
        XCTAssertNil(cell.trustIconView.image)
        XCTAssertEqual(cell.accessoryType, .none)
        XCTAssertEqual(cell.selectionStyle, .none)
    }

    func testAccessibilityLabelUsesDeviceSessionLanguageWithoutTokenTerminology() throws {
        let cell = DeviceInfoTableCell(style: .default, reuseIdentifier: DeviceInfoTableCell.cellName)

        cell.configure(
            client: "Xabber",
            device: "iPhone 16",
            description: "",
            ip: "192.0.2.5",
            lastAuth: Date(timeIntervalSinceNow: -120),
            current: true,
            editable: true,
            isOnline: true,
            trustState: .trusted,
            isTrustebByCertificate: true
        )

        let label = try XCTUnwrap(cell.accessibilityLabel?.lowercased())
        XCTAssertTrue(cell.isAccessibilityElement)
        XCTAssertTrue(label.contains("device"))
        XCTAssertTrue(label.contains("session"))
        XCTAssertTrue(label.contains("iphone 16"))
        XCTAssertTrue(label.contains("online"))
        XCTAssertFalse(label.contains("token"))
        XCTAssertFalse(label.contains("revoke"))
    }

    private func rightStackWidthConstraintCount(in cell: DeviceInfoTableCell) -> Int {
        cell.rightStack.constraints.filter { constraint in
            constraint.firstItem === cell.rightStack
            && constraint.firstAttribute == .width
            && constraint.relation == .equal
        }.count
    }
}

