        XCTAssertEqual(cell.stack.arrangedSubviews.filter { $0 === cell.customImageView }.count, 1)
        XCTAssertEqual(cell.stack.arrangedSubviews.filter { $0 === cell.labelsStack }.count, 1)
        XCTAssertEqual(cell.stack.arrangedSubviews.filter { $0 === cell.closeButton }.count, 1)
        XCTAssertEqual(cell.labelsStack.arrangedSubviews.filter { $0 === cell.titleLabel }.count, 1)
        XCTAssertEqual(cell.labelsStack.arrangedSubviews.filter { $0 === cell.subtitleLabel }.count, 1)
        XCTAssertEqual(cell.labelsStack.arrangedSubviews.filter { $0 === cell.blueButton }.count, 1)
        XCTAssertEqual(heightConstraintCount(for: cell.blueButton), 1)
        XCTAssertEqual(heightConstraintCount(for: cell.closeButton), 1)
    }

    func testAccessibilityLabelsIdentifyVerifyAndCloseActionsWithoutTokenTerminology() throws {
        let cell = makeCell(actionTitle: "Proceed to Verification")

        let verifyLabel = try XCTUnwrap(cell.blueButton.accessibilityLabel?.lowercased())
        let closeLabel = try XCTUnwrap(cell.closeButton.accessibilityLabel?.lowercased())

        XCTAssertTrue(verifyLabel.contains("verification"))
        XCTAssertTrue(closeLabel.contains("close"))
        XCTAssertFalse(verifyLabel.contains("token"))
        XCTAssertFalse(closeLabel.contains("token"))
    }

    private func makeCell(actionTitle: String? = nil) -> VerificationSessionTableViewCell {
        let cell = VerificationSessionTableViewCell()
        cell.configure(
            title: "Secure Your Conversation",
            subtitle: "Your device session needs verification before encrypted messages can be trusted."
        )
        if let actionTitle {
            cell.showVerificationButton(title: actionTitle)
        }
        return cell
    }

    private func minimumHeightConstant(for view: UIView) -> CGFloat {
        minimumDimensionConstant(for: view, attribute: .height)
    }

    private func minimumWidthConstant(for view: UIView) -> CGFloat {
        minimumDimensionConstant(for: view, attribute: .width)
    }

    private func minimumDimensionConstant(for view: UIView, attribute: NSLayoutConstraint.Attribute) -> CGFloat {
        view.constraints
            .filter { constraint in
                constraint.firstItem === view
                && constraint.firstAttribute == attribute
                && (constraint.relation == .greaterThanOrEqual || constraint.relation == .equal)
            }
            .map(\.constant)
            .max() ?? 0
    }

    private func heightConstraintCount(for view: UIView) -> Int {
        view.constraints.filter { constraint in
            constraint.firstItem === view
            && constraint.firstAttribute == .height
            && (constraint.relation == .greaterThanOrEqual || constraint.relation == .equal)
        }.count
    }
}

@MainActor
final class DevicesSectionTextLayoutTests: XCTestCase {
    func testHeaderAndFooterViewsUseDynamicTypeWrappingStaticText() throws {
        let controller = makeController()

        let headerView = try XCTUnwrap(
            controller.tableView.delegate?.tableView?(controller.tableView, viewForHeaderInSection: 1)
        )
        let footerView = try XCTUnwrap(
            controller.tableView.delegate?.tableView?(controller.tableView, viewForFooterInSection: 1)
        )
        let headerLabel = try XCTUnwrap(firstLabel(in: headerView))
        let footerLabel = try XCTUnwrap(firstLabel(in: footerView))

        XCTAssertTrue(headerLabel.adjustsFontForContentSizeCategory)
        XCTAssertTrue(footerLabel.adjustsFontForContentSizeCategory)
        XCTAssertEqual(headerLabel.numberOfLines, 0)
        XCTAssertEqual(footerLabel.numberOfLines, 0)
        XCTAssertEqual(headerLabel.font.pointSize, UIFont.preferredFont(forTextStyle: .subheadline).pointSize)
        XCTAssertEqual(footerLabel.font.pointSize, UIFont.preferredFont(forTextStyle: .footnote).pointSize)
        XCTAssertTrue(headerView.isAccessibilityElement)
        XCTAssertTrue(footerView.isAccessibilityElement)
        XCTAssertFalse(headerView.accessibilityTraits.contains(.button))
        XCTAssertFalse(footerView.accessibilityTraits.contains(.button))
    }

    func testFooterViewWrapsLongLocalizedTextWithinLayoutMargins() throws {
        let controller = makeController()
        let footerView = try XCTUnwrap(
            controller.tableView.delegate?.tableView?(controller.tableView, viewForFooterInSection: 1)
        )
        footerView.bounds = CGRect(x: 0, y: 0, width: 320, height: 1)
        footerView.setNeedsLayout()
        footerView.layoutIfNeeded()

        let fittingSize = footerView.systemLayoutSizeFitting(
            CGSize(width: 320, height: UIView.layoutFittingCompressedSize.height),
            withHorizontalFittingPriority: .required,
            verticalFittingPriority: .fittingSizeLevel
        )

        XCTAssertGreaterThan(fittingSize.height, UIFont.preferredFont(forTextStyle: .footnote).lineHeight * 2)
    }

    func testHeaderFooterStringTitlesAreReplacedByCustomViews() throws {
        let controller = makeController()

        XCTAssertNil(controller.tableView(controller.tableView, titleForHeaderInSection: 1))
        XCTAssertNil(controller.tableView(controller.tableView, titleForFooterInSection: 1))
        XCTAssertNotNil(controller.tableView.delegate?.tableView?(controller.tableView, viewForHeaderInSection: 1))
        XCTAssertNotNil(controller.tableView.delegate?.tableView?(controller.tableView, viewForFooterInSection: 1))
    }

    func testHeaderFooterTextDoesNotUseTokenTerminologyOrDestructiveTraits() throws {
        let controller = makeController()
        let views = [
            controller.tableView.delegate?.tableView?(controller.tableView, viewForHeaderInSection: 0),
            controller.tableView.delegate?.tableView?(controller.tableView, viewForFooterInSection: 0),
            controller.tableView.delegate?.tableView?(controller.tableView, viewForHeaderInSection: 1),
            controller.tableView.delegate?.tableView?(controller.tableView, viewForFooterInSection: 1)
        ].compactMap { $0 }

        XCTAssertFalse(views.isEmpty)
        for view in views {
            let labelText = try XCTUnwrap(firstLabel(in: view)?.text?.lowercased())
            XCTAssertFalse(labelText.contains("token"))
            XCTAssertFalse(labelText.contains("revoke"))
            XCTAssertFalse(view.accessibilityTraits.contains(.button))
        }
    }

    private func makeController() -> DevicesListViewController {
        let controller = DevicesListViewController()
        controller.loadViewIfNeeded()
        controller.configure(for: "section-text@example.test")
        controller.devices = [
            DeviceStorageItem(value: [
                "uid": "desktop-1",
                "owner": "section-text@example.test"
            ])
        ]
        controller.datasource = [
            DevicesListViewController.Datasource(
                .current,
                title: "This device",
                value: String(repeating: "Only other device sessions are signed out. ", count: 5),
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .token,
                        title: " ",
                        value: "resource",
                        editable: false
                    ),
                    DevicesListViewController.Datasource(
                        .button,
                        title: "Terminate all other sessions",
                        value: "terminate_all_sessions",
                        editable: false
                    )
                ]
            ),
            DevicesListViewController.Datasource(
                .token,
                title: "Active devices",
                value: String(repeating: "You can terminate sessions you do not need. Current device remains signed in. ", count: 5),
                editable: false
            )
        ]
        return controller
    }

    private func firstLabel(in view: UIView) -> UILabel? {
        if let label = view as? UILabel {
            return label
        }
        for subview in view.subviews {
            if let label = firstLabel(in: subview) {
                return label
            }
        }
        return nil
    }
}

@MainActor
final class DevicesSessionActionTests: XCTestCase {
    func testSwipeActionTitleUsesSessionLanguageWithoutLegacyTerminology() throws {
        let controller = makeController(includesVerificationRow: false)

        let configuration = try XCTUnwrap(
            controller.tableView.delegate?.tableView?(
                controller.tableView,
                trailingSwipeActionsConfigurationForRowAt: IndexPath(row: 0, section: 1)
            )
        )
        let action = try XCTUnwrap(configuration.actions.first)
        let title = try XCTUnwrap(action.title)
        let lowercasedTitle = title.lowercased()

        XCTAssertEqual(action.style, .destructive)
        XCTAssertEqual(title, "Terminate session")
        XCTAssertFalse(configuration.performsFirstActionWithFullSwipe)
        XCTAssertFalse(lowercasedTitle.contains("token"))
        XCTAssertFalse(lowercasedTitle.contains("revoke"))
    }

    func testSessionActionTextAndConfirmationDoNotUseLegacyTerminology() throws {
        let controller = makeController(includesVerificationRow: false)
        let action = try XCTUnwrap(
            controller.devicesSecuritySwipeAction(at: IndexPath(row: 0, section: 1))
        )

        guard case .terminateSession(_, let confirmation) = action else {
            return XCTFail("Expected a single-session termination action")
        }

        let exposedText = [
            action.title,
            confirmation.title,
            confirmation.message,
            confirmation.confirmTitle,
            confirmation.cancelTitle
        ].joined(separator: " ").lowercased()

        XCTAssertFalse(exposedText.contains("token"))
        XCTAssertFalse(exposedText.contains("revoke"))
    }

    func testRowToDeviceMappingWithoutVerificationRow() throws {
        let controller = makeController(includesVerificationRow: false)

        XCTAssertEqual(
            try uidForTerminateAction(controller, row: 0),
            "desktop-1"
        )
        XCTAssertEqual(
            try uidForTerminateAction(controller, row: 1),
            "phone-2"
        )
    }

    func testRowToDeviceMappingWithVerificationRowAndNoActionOnVerificationWarning() throws {
        let controller = makeController(includesVerificationRow: true)

        XCTAssertNil(controller.devicesSecuritySwipeAction(at: IndexPath(row: 0, section: 1)))
        XCTAssertNil(
            controller.tableView.delegate?.tableView?(
                controller.tableView,
                trailingSwipeActionsConfigurationForRowAt: IndexPath(row: 0, section: 1)
            )
        )
        XCTAssertEqual(
            try uidForTerminateAction(controller, row: 1),
            "desktop-1"
        )
        XCTAssertEqual(
            try uidForTerminateAction(controller, row: 2),
            "phone-2"
        )
    }

    func testBrokenObsoleteDeviceKeyDeletionRemainsSeparate() throws {
        let controller = makeController(includesVerificationRow: false, includesBrokenSection: true)
        let action = try XCTUnwrap(
            controller.devicesSecuritySwipeAction(at: IndexPath(row: 0, section: 2))
        )
        let configuration = try XCTUnwrap(
            controller.tableView.delegate?.tableView?(
                controller.tableView,
                trailingSwipeActionsConfigurationForRowAt: IndexPath(row: 0, section: 2)
            )
        )

        guard case .deleteBrokenKey(let deviceId) = action else {
            return XCTFail("Expected obsolete key deletion to stay separate")
        }

        XCTAssertEqual(deviceId, 42)
        XCTAssertEqual(action.title, "Delete key")
        XCTAssertEqual(configuration.actions.first?.title, "Delete key")
        XCTAssertFalse(action.requiresConfirmation)
    }

    func testSingleSessionTerminationRequiresExplicitConfirmation() throws {
        let controller = makeController(includesVerificationRow: false)
        let action = try XCTUnwrap(
            controller.devicesSecuritySwipeAction(at: IndexPath(row: 0, section: 1))
        )

        guard case .terminateSession(_, let confirmation) = action else {
            return XCTFail("Expected a single-session termination action")
        }

        let message = confirmation.message.lowercased()

        XCTAssertTrue(action.requiresConfirmation)
        XCTAssertEqual(confirmation.confirmTitle, "Terminate session")
        XCTAssertEqual(confirmation.cancelTitle, "Cancel")
        XCTAssertTrue(message.contains("selected device session"))
        XCTAssertTrue(message.contains("current device remains signed in"))
        XCTAssertTrue(message.contains("server data is not deleted"))
    }

    func testTerminateAllOtherSessionsConfirmationUsesPreciseSessionLanguage() {
        let confirmation = DevicesTerminateAllSessionsConfirmation.default
        let exposedText = [
            confirmation.title,
            confirmation.message,
            confirmation.confirmTitle,
            confirmation.cancelTitle
        ].joined(separator: " ").lowercased()
        let message = confirmation.message.lowercased()

        XCTAssertFalse(exposedText.contains("token"))
        XCTAssertFalse(exposedText.contains("revoke"))
        XCTAssertTrue(message.contains("other device sessions"))
        XCTAssertTrue(message.contains("this device remains signed in"))
        XCTAssertTrue(message.contains("account and server data is not deleted"))
    }

    func testTerminateAllOtherSessionsConfirmationMapsToRevokeAllOnlyWhenConfirmed() {
        let confirmation = DevicesTerminateAllSessionsConfirmation.default

        XCTAssertEqual(
            confirmation.effect(confirmed: true),
            .revokeAllOtherSessions
        )
        XCTAssertEqual(
            confirmation.effect(confirmed: false),
            .none
        )
    }

    private func uidForTerminateAction(
        _ controller: DevicesListViewController,
        row: Int
    ) throws -> String {
        let action = try XCTUnwrap(
            controller.devicesSecuritySwipeAction(at: IndexPath(row: row, section: 1))
        )

        guard case .terminateSession(let uid, _) = action else {
            throw XCTestError(.failureWhileWaiting, userInfo: [
                NSLocalizedDescriptionKey: "Expected terminate-session action"
            ])
        }

        return uid
    }

    private func makeController(
        includesVerificationRow: Bool,
        includesBrokenSection: Bool = false
    ) -> DevicesListViewController {
        let controller = DevicesListViewController()
        controller.loadViewIfNeeded()
        controller.configure(for: "session-action@example.test")
        controller.devices = [
            DeviceStorageItem(value: [
                "uid": "desktop-1",
                "owner": "session-action@example.test"
            ]),
            DeviceStorageItem(value: [
                "uid": "phone-2",
                "owner": "session-action@example.test"
            ])
        ]
        controller.isVerificationRequired = includesVerificationRow
        let activeDevicesSection = DevicesListViewController.Datasource(
            .token,
            title: "Active devices",
            value: "You can terminate sessions you do not need. Current device remains signed in.",
            editable: false
        )
        if includesVerificationRow {
            activeDevicesSection.childs.append(
                DevicesListViewController.Datasource(
                    .session,
                    title: "Non-Verified Devices Connected",
                    value: "Verify connected devices before trusting encrypted sessions.",
                    editable: false
                )
            )
        }
        controller.datasource = [
            DevicesListViewController.Datasource(
                .current,
                title: "This device",
                value: "Only other device sessions are signed out.",
                editable: false,
                childs: [
                    DevicesListViewController.Datasource(
                        .token,
                        title: " ",
                        value: "resource",
                        editable: false
                    ),
                    DevicesListViewController.Datasource(
                        .button,
                        title: "Terminate all other sessions",
                        value: "terminate_all_sessions",
                        editable: false
                    )
                ]
            ),
            activeDevicesSection
        ]

        if includesBrokenSection {
            let brokenDevice = SignalDeviceStorageItem()
            brokenDevice.owner = "session-action@example.test"
            brokenDevice.jid = "session-action@example.test"
            brokenDevice.deviceId = 42
            controller.brokenOmemoDevices = [brokenDevice]
            controller.datasource.append(
                DevicesListViewController.Datasource(
                    .broken,
                    title: "Obsolete devices",
                    value: nil,
                    editable: false
                )
            )
        }

        return controller
    }
}

final class NavigationTransitionMutationPolicyTests: XCTestCase {
    func testLastChatsQueuesNonCriticalMutationsDuringNavigationTransition() {
        XCTAssertTrue(
            LastChatsNavigationTransitionMutationPolicy.shouldDeferMutation(
                isTransitionActive: true,
                isCriticalForFirstFrame: false
            )
        )
        XCTAssertFalse(
            LastChatsNavigationTransitionMutationPolicy.shouldDeferMutation(
                isTransitionActive: true,
                isCriticalForFirstFrame: true
            )
        )
        XCTAssertFalse(
            LastChatsNavigationTransitionMutationPolicy.shouldDeferMutation(
                isTransitionActive: false,
                isCriticalForFirstFrame: false
            )
        )
    }

    func testLastChatsDefersBootstrapDatasetUpdateDuringNavigationTransition() {
        XCTAssertTrue(
            LastChatsBootstrapDatasetUpdatePolicy.shouldDeferDatasetUpdateForNavigationTransition(
                isBootstrapActive: true,
                isNavigationTransitionActive: true
            )
        )
        XCTAssertFalse(
            LastChatsBootstrapDatasetUpdatePolicy.shouldDeferDatasetUpdateForNavigationTransition(
                isBootstrapActive: false,
                isNavigationTransitionActive: true
            )
        )
        XCTAssertFalse(
            LastChatsBootstrapDatasetUpdatePolicy.shouldDeferDatasetUpdateForNavigationTransition(
                isBootstrapActive: true,
                isNavigationTransitionActive: false
            )
        )
    }

    func testLastChatsBootstrapCoalescingStillRunsOutsideNavigationTransition() {
        XCTAssertTrue(
            LastChatsBootstrapDatasetUpdatePolicy.shouldCoalesceDatasetUpdate(
                isBootstrapActive: true,
                hasScheduledUpdate: false
            )
        )
        XCTAssertFalse(
            LastChatsBootstrapDatasetUpdatePolicy.shouldCoalesceDatasetUpdate(
                isBootstrapActive: true,
                hasScheduledUpdate: true
            )
        )
        XCTAssertFalse(
            LastChatsBootstrapDatasetUpdatePolicy.shouldCoalesceDatasetUpdate(
                isBootstrapActive: false,
                hasScheduledUpdate: false
            )
        )
    }

    func testLastChatsDeferredBootstrapFlushesFreshDatasetAfterCompletedOrCancelledTransition() {
        XCTAssertEqual(
            LastChatsBootstrapDatasetUpdatePolicy.deferredDatasetUpdateAction(
                cancelled: false,
                hasPendingUpdate: true
            ),
            .flush
        )
        XCTAssertEqual(
            LastChatsBootstrapDatasetUpdatePolicy.deferredDatasetUpdateAction(
                cancelled: false,
                hasPendingUpdate: false
            ),
            .none
        )
        XCTAssertEqual(
            LastChatsBootstrapDatasetUpdatePolicy.deferredDatasetUpdateAction(
                cancelled: true,
                hasPendingUpdate: true
            ),
            .flush
        )
    }

    func testChatInitialDatasourcePopulationIsNonAnimatedForPreparedFirstFrame() {
        XCTAssertFalse(
            ChatNavigationTransitionMutationPolicy.shouldAnimateMutation(
                requestedAnimated: true,
                isTransitionActive: false,
                isPreparingFirstFrame: true
            )
        )
        XCTAssertFalse(
            ChatNavigationTransitionMutationPolicy.shouldAnimateMutation(
                requestedAnimated: true,
                isTransitionActive: true,
                isPreparingFirstFrame: false
            )
        )
        XCTAssertTrue(
            ChatNavigationTransitionMutationPolicy.shouldAnimateMutation(
                requestedAnimated: true,
                isTransitionActive: false,
                isPreparingFirstFrame: false
            )
        )
    }

    func testPendingOpenMessageRequestsWaitForNavigationTransitionCompletion() {
        XCTAssertTrue(
            ChatNavigationTransitionMutationPolicy.shouldDeferOpenMessageRequest(
                isTransitionActive: true,
                hasPendingRequest: true
            )
        )
        XCTAssertFalse(
            ChatNavigationTransitionMutationPolicy.shouldDeferOpenMessageRequest(
                isTransitionActive: true,
                hasPendingRequest: false
            )
        )
        XCTAssertFalse(
            ChatNavigationTransitionMutationPolicy.shouldDeferOpenMessageRequest(
                isTransitionActive: false,
                hasPendingRequest: true
            )
        )
    }
}

final class ChatSubscriptionPresentationPolicyTests: XCTestCase {
    private typealias Subscribtion = RosterStorageItem.Subsccribtion
    private typealias Ask = RosterStorageItem.Ask

    private func presentation(
        hasRosterItem: Bool = true,
        subscribtion: Subscribtion,
        ask: Ask,
        conversationType: ClientSynchronizationManager.ConversationType = .regular,
        isServerJID: Bool = false,
        isSavedChat: Bool = false,
        isBlocked: Bool = false,
        isContact: Bool = true
    ) -> ChatSubscriptionPresentation {
        ChatSubscriptionPresentationPolicy.presentation(for: ChatSubscriptionPresentationInput(
            hasRosterItem: hasRosterItem,
            subscribtion: subscribtion,
            ask: ask,
            conversationType: conversationType,
            isServerJID: isServerJID,
            isSavedChat: isSavedChat,
            isBlocked: isBlocked,
            isContact: isContact
        ))
    }

    func testRegularContactMatrixMatchesWorkbookPolicy() {
        let addActions: [ChatSubscriptionPresentation.Action] = [.addContact, .block, .close]
        let allowActions: [ChatSubscriptionPresentation.Action] = [.allowSubscription, .block, .close]
        let noActions: [ChatSubscriptionPresentation.Action] = []
        let cases: [(String, Bool, Subscribtion, Ask, ChatSubscriptionPresentation.StatusMode, ChatSubscriptionPresentation.TopPanelKind, [ChatSubscriptionPresentation.Action], Bool)] = [
            ("nil none", false, .undefined, .none, .fixed(.notInContacts), .addContact, addActions, false),
            ("nil in", false, .undefined, .in, .fixed(.incomingSubscriptionRequest), .contactRequest, addActions, false),
            ("nil out", false, .undefined, .out, .fixed(.subscriptionRequestPending), .none, noActions, false),
            ("nil both", false, .undefined, .both, .fixed(.incomingSubscriptionRequest), .contactRequest, addActions, false),
            ("undefined none", true, .undefined, .none, .fixed(.notInContacts), .addContact, addActions, false),
            ("undefined in", true, .undefined, .in, .fixed(.incomingSubscriptionRequest), .contactRequest, addActions, false),
            ("undefined out", true, .undefined, .out, .fixed(.subscriptionRequestPending), .none, noActions, false),
            ("undefined both", true, .undefined, .both, .fixed(.incomingSubscriptionRequest), .contactRequest, addActions, false),
            ("none none", true, .none, .none, .fixed(.inContacts), .none, noActions, false),
            ("none in", true, .none, .in, .fixed(.inContacts), .allowSubscription, allowActions, false),
            ("none out", true, .none, .out, .fixed(.subscriptionRequestPending), .none, noActions, false),
            ("none both", true, .none, .both, .fixed(.subscriptionRequestPending), .allowSubscription, allowActions, false),
            ("to none", true, .to, .none, .normalPresence, .none, noActions, true),
            ("to in", true, .to, .in, .normalPresence, .allowSubscription, allowActions, true),
            ("to out", true, .to, .out, .normalPresence, .none, noActions, true),
            ("to both", true, .to, .both, .normalPresence, .allowSubscription, allowActions, true),
            ("from none", true, .from, .none, .fixed(.receivesPresenceUpdates), .none, noActions, false),
            ("from in", true, .from, .in, .fixed(.receivesPresenceUpdates), .none, noActions, false),
            ("from out", true, .from, .out, .fixed(.subscriptionRequestPending), .none, noActions, false),
            ("from both", true, .from, .both, .fixed(.subscriptionRequestPending), .none, noActions, false),
            ("both none", true, .both, .none, .normalPresence, .none, noActions, true),
            ("both in", true, .both, .in, .normalPresence, .none, noActions, true),
            ("both out", true, .both, .out, .normalPresence, .none, noActions, true),
            ("both both", true, .both, .both, .normalPresence, .none, noActions, true)
        ]

        for item in cases {
            let result = presentation(hasRosterItem: item.1, subscribtion: item.2, ask: item.3)

            XCTAssertEqual(result.statusMode, item.4, item.0)
            XCTAssertEqual(result.topPanelKind, item.5, item.0)
            XCTAssertEqual(result.actions, item.6, item.0)
            XCTAssertEqual(result.showsNormalPresenceStatus, item.7, item.0)
        }
    }

    func testBypassedConversationAndEntityTypesDoNotEmitSubscriptionPresentation() {
        let bypassed = [
            presentation(subscribtion: .none, ask: .in, conversationType: .group),
            presentation(subscribtion: .none, ask: .in, conversationType: .channel),
            presentation(subscribtion: .none, ask: .in, conversationType: .notifications),
            presentation(subscribtion: .none, ask: .in, isServerJID: true),
            presentation(subscribtion: .none, ask: .in, isSavedChat: true),
            presentation(subscribtion: .none, ask: .in, isBlocked: true),
            presentation(subscribtion: .none, ask: .in, isContact: false)
        ]

        for result in bypassed {
            XCTAssertEqual(result.statusMode, .unchanged)
            XCTAssertEqual(result.topPanelKind, .none)
            XCTAssertTrue(result.actions.isEmpty)
            XCTAssertFalse(result.showsNormalPresenceStatus)
        }
    }

    func testRosterItemHelperUsesSamePolicyAsDirectInput() {
        let rosterItem = RosterStorageItem()
        rosterItem.subscribtion = .none
        rosterItem.ask = .in

        let direct = presentation(subscribtion: .none, ask: .in)
        let fromRosterItem = ChatSubscriptionPresentationPolicy.presentation(
            rosterItem: rosterItem,
            conversationType: .regular,
            isServerJID: false,
            isSavedChat: false,
            isBlocked: false
        )

        XCTAssertEqual(fromRosterItem, direct)
    }

    func testControllerPresentationAdapterMatchesSharedPolicy() throws {
        let realm = try Realm(configuration: Realm.Configuration(
            inMemoryIdentifier: "ChatSubscriptionPresentationPolicyTests-\(name)"
        ))
        let rosterItem = RosterStorageItem()
        rosterItem.owner = "romeo@example.com"
        rosterItem.jid = "juliet@example.com"
        rosterItem.subscribtion = .none
        rosterItem.ask = .in

        let viewController = ChatViewController()
        viewController.owner = rosterItem.owner
        viewController.jid = rosterItem.jid
        viewController.conversationType = .regular

        let expected = ChatSubscriptionPresentationPolicy.presentation(
            rosterItem: rosterItem,
            conversationType: .regular,
            isServerJID: false,
            isSavedChat: false,
            isBlocked: false
        )

        XCTAssertEqual(
            viewController.chatSubscriptionPresentation(rosterItem: rosterItem, realm: realm),
            expected
        )
    }

    func testEncryptedOneToOneChatsUseRegularContactPolicy() {
        for conversationType in [ClientSynchronizationManager.ConversationType.omemo, .omemo1, .axolotl] {
            let result = presentation(
                subscribtion: .to,
                ask: .in,
                conversationType: conversationType
            )

            XCTAssertEqual(result.statusMode, .normalPresence)
            XCTAssertEqual(result.topPanelKind, .allowSubscription)
            XCTAssertTrue(result.showsNormalPresenceStatus)
        }
    }
}

final class ChatSubscriptionTopBarStyleTests: XCTestCase {
    func testPinnedMessageHeightPolicyClampsToMinimumAndMaximum() {
        XCTAssertEqual(
            ChatPinnedMessageBarHeightPolicy.visualHeight(forFittingHeight: 20),
            44,
            accuracy: 0.001
        )
        XCTAssertEqual(
            ChatPinnedMessageBarHeightPolicy.visualHeight(forFittingHeight: 64),
            64,
            accuracy: 0.001
        )
        XCTAssertEqual(
            ChatPinnedMessageBarHeightPolicy.visualHeight(forFittingHeight: 140),
            88,
            accuracy: 0.001
        )
    }

    func testFloatingGlassBubbleUsesNativeGlassStyleWithoutCustomChrome() throws {
        let bubble = ChatFloatingGlassBubbleView(contentHeight: 44)
        let effectView = try XCTUnwrap(bubble.subviews.compactMap { $0 as? UIVisualEffectView }.first)

        XCTAssertEqual(bubble.measuredHeight(), 44, accuracy: 0.001)
        XCTAssertEqual(bubble.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertEqual(effectView.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertEqual(effectView.layer.borderWidth, 0, accuracy: 0.001)
        XCTAssertNil(effectView.layer.borderColor)
        if #available(iOS 26.0, *) {
            XCTAssertTrue(effectView.effect is UIGlassEffect)
        } else {
            XCTAssertTrue(effectView.effect is UIBlurEffect)
        }
    }

    func testFloatingActionPanelHostsControlsInFortyFourPointLayout() {
        let button = UIButton(type: .system)
        button.setTitle("Incoming subscription request", for: .normal)
        let panel = ChatFloatingActionPanelView(
            icon: UIImage(systemName: "person.wave.2.fill"),
            tintColor: .tintColor,
            showsCloseButton: true
        )

        panel.setContentViews([button])
        panel.frame = CGRect(x: 0, y: 0, width: 320, height: 44)
        panel.layoutIfNeeded()

        XCTAssertTrue(button.superview != nil)
        XCTAssertEqual(panel.intrinsicContentSize.height, 44, accuracy: 0.001)
        XCTAssertLessThanOrEqual(button.frame.height, 44)
        XCTAssertEqual(button.titleLabel?.lineBreakMode, .byTruncatingTail)
    }

    func testPinnedMessagePanelFitsInsideClampedGlassBubbleWithOptionalUnpin() throws {
        let bubble = ChatFloatingGlassBubbleView(contentHeight: ChatPinnedMessageBarHeightPolicy.minimumHeight)
        let panel = ChatPinnedMessagePanelView(frame: .zero)
        panel.configure(
            title: NSAttributedString(string: "Alice"),
            preview: "A longer pinned message preview that should wrap cleanly without pushing the bar past its visual limit.",
            showsUnpinButton: true
        )

        let fittingHeight = panel.preferredContentHeight(width: 320)
        bubble.setHostedView(panel, contentHeight: fittingHeight)
        bubble.frame = CGRect(x: 0, y: 0, width: 360, height: bubble.measuredHeight())
        bubble.layoutIfNeeded()
        panel.layoutIfNeeded()

        let effectView = try XCTUnwrap(bubble.subviews.compactMap { $0 as? UIVisualEffectView }.first)
        XCTAssertEqual(bubble.measuredHeight(), fittingHeight, accuracy: 0.001)
        XCTAssertGreaterThanOrEqual(fittingHeight, 44)
        XCTAssertLessThanOrEqual(fittingHeight, 88)
        XCTAssertEqual(effectView.layer.borderWidth, 0, accuracy: 0.001)
        XCTAssertEqual(effectView.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertFalse(panel.unpinButton.isHidden)
        XCTAssertLessThanOrEqual(panel.previewLabel.frame.maxY, panel.bounds.maxY + 0.5)
    }
}

final class ChatVerificationTopBarStyleTests: XCTestCase {
    func testSharedTopBubbleUsesNativeGlassSurfaceWithoutCustomChrome() throws {
        let bubble = ChatFloatingGlassBubbleView(contentHeight: NativeGlassBarStyle.minimumHeight)
        let effectView = try XCTUnwrap(visualEffectViews(in: bubble).first)

        XCTAssertEqual(bubble.measuredHeight(), NativeGlassBarStyle.minimumHeight, accuracy: 0.001)
        XCTAssertEqual(bubble.backgroundColor ?? .clear, .clear)
        XCTAssertFalse(bubble.isOpaque)
        XCTAssertNil(bubble.layer.shadowColor)
        XCTAssertEqual(bubble.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertEqual(bubble.layer.shadowRadius, 0, accuracy: 0.001)
        XCTAssertEqual(bubble.layer.shadowOffset, .zero)
        XCTAssertNil(bubble.layer.shadowPath)
        XCTAssertEqual(effectView.backgroundColor ?? .clear, .clear)
        XCTAssertFalse(effectView.isOpaque)
        XCTAssertEqual(effectView.layer.borderWidth, 0, accuracy: 0.001)
        XCTAssertNil(effectView.layer.borderColor)
        XCTAssertEqual(effectView.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertNil(effectView.layer.shadowPath)

        if #available(iOS 26.0, *) {
            let glassEffect = try XCTUnwrap(effectView.effect as? UIGlassEffect)
            XCTAssertTrue(glassEffect.isInteractive)
            XCTAssertEqual(glassEffect.tintColor, XabberGlassStyle.nativeGlassTintColor)
        } else {
            XCTAssertTrue(effectView.effect is UIBlurEffect)
        }
    }

    func testIncomingVerificationPanelIsContentOnlyFortyFourPointLayout() throws {
        let viewController = ChatViewController()
        let panel = viewController.makeRequestingVerificationPanel(isActionEnabled: true)
        let bubble = ChatFloatingGlassBubbleView(contentHeight: NativeGlassBarStyle.minimumHeight)

        bubble.setHostedView(panel, contentHeight: NativeGlassBarStyle.minimumHeight)
        bubble.frame = CGRect(x: 0, y: 0, width: 320, height: NativeGlassBarStyle.minimumHeight)
        bubble.layoutIfNeeded()

        let effectView = try XCTUnwrap(visualEffectViews(in: bubble).first)
        let actionButton = try XCTUnwrap(button(configuredTitle: "Accept verification request", in: panel))

        XCTAssertTrue(panel.isDescendant(of: effectView.contentView))
        XCTAssertFalse(panel.translatesAutoresizingMaskIntoConstraints)
        XCTAssertEqual(panel.intrinsicContentSize.height, NativeGlassBarStyle.minimumHeight, accuracy: 0.001)
        XCTAssertEqual(panel.frame.height, NativeGlassBarStyle.minimumHeight, accuracy: 0.001)
        XCTAssertEqual(panel.frame.minX, 10, accuracy: 0.001)
        XCTAssertEqual(effectView.contentView.bounds.maxX - panel.frame.maxX, 10, accuracy: 0.001)
        XCTAssertEqual(visualEffectViews(in: panel).count, 0)
        XCTAssertEqual(panel.layer.borderWidth, 0, accuracy: 0.001)
        XCTAssertEqual(panel.layer.shadowOpacity, 0, accuracy: 0.001)
        XCTAssertTrue(actionButton.isEnabled)
        XCTAssertEqual(actionButton.titleLabel?.lineBreakMode, .byTruncatingTail)
    }

    func testIncomingVerificationActionTargetsExistingFlow() throws {
        let viewController = ChatViewController()
        let panel = viewController.makeRequestingVerificationPanel(isActionEnabled: true)
        let actionButton = try XCTUnwrap(button(configuredTitle: "Accept verification request", in: panel))

        let actions = actionButton.actions(forTarget: viewController, forControlEvent: .touchUpInside) ?? []

        XCTAssertTrue(actions.contains(NSStringFromSelector(#selector(ChatViewController.onRequestingVerification(_:)))))
    }

    func testIncomingVerificationCloseTargetsExistingDismissal() {
        let viewController = ChatViewController()
        let panel = viewController.makeRequestingVerificationPanel(isActionEnabled: true)
        let actions = panel.closeButton.actions(forTarget: viewController, forControlEvent: .touchUpInside) ?? []

        XCTAssertTrue(actions.contains(NSStringFromSelector(#selector(ChatViewController.additionalNavBarPanelCancelButtonTouchUpInside(_:)))))
    }

    func testIncomingVerificationActionCanBeDisabledWhenLocalBundleIsUnavailable() throws {
        let panel = ChatViewController().makeRequestingVerificationPanel(isActionEnabled: false)
        let actionButton = try XCTUnwrap(button(configuredTitle: "Accept verification request", in: panel))

        XCTAssertFalse(actionButton.isEnabled)
    }

    private func button(configuredTitle title: String, in view: UIView) -> UIButton? {
        buttons(in: view).first {
            $0.configuration?.title == title || $0.title(for: .normal) == title
        }
    }

    private func buttons(in view: UIView) -> [UIButton] {
        view.subviews.reduce(view is UIButton ? [view as! UIButton] : []) { result, subview in
            result + buttons(in: subview)
        }
    }

    private func visualEffectViews(in view: UIView) -> [UIVisualEffectView] {
        view.subviews.reduce(view is UIVisualEffectView ? [view as! UIVisualEffectView] : []) { result, subview in
            result + visualEffectViews(in: subview)
        }
    }
}

