@MainActor
final class ModalPresentationContainmentTests: XCTestCase {
    func testActivateHidesPresenterAndMarksPresentedViewsAsModal() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        presenter.loadViewIfNeeded()
        navigationController.loadViewIfNeeded()
        root.loadViewIfNeeded()

        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root
        )

        containment.activate()

        XCTAssertTrue(presenter.view.accessibilityElementsHidden)
        XCTAssertTrue(navigationController.view.accessibilityViewIsModal)
        XCTAssertTrue(root.view.accessibilityViewIsModal)
    }

    func testRestoreReturnsAccessibilityStateToPreviousValues() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        presenter.loadViewIfNeeded()
        navigationController.loadViewIfNeeded()
        root.loadViewIfNeeded()

        presenter.view.accessibilityElementsHidden = true
        navigationController.view.accessibilityViewIsModal = true
        root.view.accessibilityViewIsModal = true

        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root
        )

        containment.activate()
        containment.restoreIfNeeded()

        XCTAssertTrue(presenter.view.accessibilityElementsHidden)
        XCTAssertTrue(navigationController.view.accessibilityViewIsModal)
        XCTAssertTrue(root.view.accessibilityViewIsModal)
    }

    func testRestoreClearsCurrentPresentedControllerOnlyForDismissedController() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        var currentPresented: UIViewController? = root

        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root,
            currentPresented: { currentPresented },
            setCurrentPresented: { currentPresented = $0 }
        )

        containment.activate()
        containment.restoreIfNeeded()

        XCTAssertNil(currentPresented)

        let other = UIViewController()
        currentPresented = other
        let secondContainment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root,
            currentPresented: { currentPresented },
            setCurrentPresented: { currentPresented = $0 }
        )

        secondContainment.activate()
        secondContainment.restoreIfNeeded()

        XCTAssertTrue(currentPresented === other)
    }

    func testDeinitRestoresAccessibilityStateForProgrammaticDismissFallback() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        presenter.loadViewIfNeeded()
        navigationController.loadViewIfNeeded()
        root.loadViewIfNeeded()

        var containment: ModalPresentationContainmentController? = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root
        )

        containment?.activate()
        XCTAssertTrue(presenter.view.accessibilityElementsHidden)
        XCTAssertTrue(navigationController.view.accessibilityViewIsModal)
        XCTAssertTrue(root.view.accessibilityViewIsModal)

        containment = nil

        XCTAssertFalse(presenter.view.accessibilityElementsHidden)
        XCTAssertFalse(navigationController.view.accessibilityViewIsModal)
        XCTAssertFalse(root.view.accessibilityViewIsModal)
    }

    func testForwardedAdaptivePresentationDelegateReceivesDismissCallbacks() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        let forwardedDelegate = RecordingAdaptivePresentationDelegate()
        forwardedDelegate.shouldDismissResult = false

        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root,
            forwardedDelegate: forwardedDelegate
        )
        let presentationController = UIPresentationController(
            presentedViewController: navigationController,
            presenting: presenter
        )

        containment.activate()

        XCTAssertFalse(containment.presentationControllerShouldDismiss(presentationController))

        containment.presentationControllerDidDismiss(presentationController)

        XCTAssertEqual(forwardedDelegate.didDismissCount, 1)
        XCTAssertEqual(forwardedDelegate.shouldDismissCount, 1)
        XCTAssertFalse(presenter.view.accessibilityElementsHidden)
    }

    func testDismissalHandlerRunsOnceOnAdaptiveDismiss() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        var dismissalHandlerCallCount = 0
        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root,
            dismissalHandler: {
                dismissalHandlerCallCount += 1
            }
        )
        let presentationController = UIPresentationController(
            presentedViewController: navigationController,
            presenting: presenter
        )

        containment.activate()
        containment.presentationControllerDidDismiss(presentationController)
        containment.presentationControllerDidDismiss(presentationController)

        XCTAssertEqual(dismissalHandlerCallCount, 1)
    }

    func testDismissalHandlerIsIdempotentAcrossRepeatedRestore() {
        let presenter = UIViewController()
        let root = UIViewController()
        let navigationController = UINavigationController(rootViewController: root)
        var dismissalHandlerCallCount = 0
        let containment = makeContainment(
            presenter: presenter,
            navigationController: navigationController,
            root: root,
            dismissalHandler: {
                dismissalHandlerCallCount += 1
            }
        )

        containment.activate()
        containment.restoreIfNeeded()
        containment.restoreIfNeeded()

        XCTAssertEqual(dismissalHandlerCallCount, 1)
    }

    private func makeContainment(
        presenter: UIViewController,
        navigationController: UINavigationController,
        root: UIViewController,
        forwardedDelegate: UIAdaptivePresentationControllerDelegate? = nil,
        currentPresented: @escaping () -> UIViewController? = { nil },
        setCurrentPresented: @escaping (UIViewController?) -> Void = { _ in },
        dismissalHandler: (() -> Void)? = nil
    ) -> ModalPresentationContainmentController {
        ModalPresentationContainmentController(
            presentingView: presenter.view,
            navigationController: navigationController,
            rootViewController: root,
            presentedContentViewController: root,
            forwardedDelegate: forwardedDelegate,
            currentControllerAccess: ModalPresentationCurrentControllerAccess(
                get: currentPresented,
                set: setCurrentPresented
            ),
            dismissalHandler: dismissalHandler
        )
    }

    private final class RecordingAdaptivePresentationDelegate: NSObject, UIAdaptivePresentationControllerDelegate {
        var didDismissCount = 0
        var shouldDismissCount = 0
        var shouldDismissResult = true

        func presentationControllerDidDismiss(_ presentationController: UIPresentationController) {
            didDismissCount += 1
        }

        func presentationControllerShouldDismiss(_ presentationController: UIPresentationController) -> Bool {
            shouldDismissCount += 1
            return shouldDismissResult
        }
    }
}

@MainActor
final class LeftMenuRootNavigationChromeRecoveryTests: XCTestCase {
    func testRecoveryRestoresChatsSidebarButton() {
        withInterfaceType(.split) {
            assertRecoveryRestoresSidebarButton(
                rootViewController: LastChatsViewController(),
                expectedIdentifier: "chats_sidebar_menu_button"
            )
        }
    }

    func testRecoveryRestoresContactsSidebarButton() {
        withInterfaceType(.split) {
            let rootViewController = ContactsCategoryViewController()
            rootViewController.isGroup = false
            assertRecoveryRestoresSidebarButton(
                rootViewController: rootViewController,
                expectedIdentifier: "contacts_sidebar_menu_button"
            )
        }
    }

    func testRecoveryRestoresGroupsSidebarButton() {
        withInterfaceType(.split) {
            let rootViewController = ContactsCategoryViewController()
            rootViewController.isGroup = true
            assertRecoveryRestoresSidebarButton(
                rootViewController: rootViewController,
                expectedIdentifier: "groups_sidebar_menu_button"
            )
        }
    }

    func testRecoveryRestoresCallsSidebarButton() {
        withInterfaceType(.split) {
            assertRecoveryRestoresSidebarButton(
                rootViewController: CallsCategoriesViewController(),
                expectedIdentifier: "calls_sidebar_menu_button"
            )
        }
    }

    func testRecoveryRestoresNotificationsSidebarButton() {
        withInterfaceType(.split) {
            assertRecoveryRestoresSidebarButton(
                rootViewController: NotificationsCategoriesViewController(),
                expectedIdentifier: "notifications_sidebar_menu_button"
            )
        }
    }

    private func assertRecoveryRestoresSidebarButton(
        rootViewController: UIViewController,
        expectedIdentifier: String
    ) {
        let splitViewController = UISplitViewController(style: .tripleColumn)
        let navigationController = UINavigationController(rootViewController: rootViewController)
        splitViewController.setViewController(UIViewController(), for: .primary)
        splitViewController.setViewController(navigationController, for: .supplementary)
        rootViewController.navigationItem.leftBarButtonItem = UIBarButtonItem(systemItem: .cancel)

        LeftMenuRootNavigationChromeRecovery.refreshRootChrome(in: splitViewController)

        XCTAssertEqual(
            rootViewController.navigationItem.leftBarButtonItem?.accessibilityIdentifier,
            expectedIdentifier
        )
    }

    private func withInterfaceType(_ interfaceType: CommonConfigManager.InterfaceType, block: () -> Void) {
        let previousInterfaceType = CommonConfigManager.shared.config.interface_type
        defer {
            CommonConfigManager.shared.config.interface_type = previousInterfaceType
        }

        CommonConfigManager.shared.config.interface_type = interfaceType.rawValue
        block()
    }
}

final class EULAAcceptanceTests: XCTestCase {
    private func makeDefaults(file: StaticString = #filePath, line: UInt = #line) throws -> (UserDefaults, String) {
        let suiteName = "xabber.eula.tests.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suiteName), file: file, line: line)
        defaults.removePersistentDomain(forName: suiteName)
        return (defaults, suiteName)
    }

    private func removeDefaults(_ suiteName: String) {
        UserDefaults.standard.removePersistentDomain(forName: suiteName)
        UserDefaults(suiteName: suiteName)?.removePersistentDomain(forName: suiteName)
    }

    func testNoStoredAcceptanceRequiresEULA() throws {
        let (defaults, suiteName) = try makeDefaults()
        defer { removeDefaults(suiteName) }

        XCTAssertFalse(EULAAcceptance.hasAcceptedCurrentVersion(defaults: defaults))
    }

    func testCurrentAcceptedVersionAllowsAppFlow() throws {
        let (defaults, suiteName) = try makeDefaults()
        defer { removeDefaults(suiteName) }

        defaults.set(true, forKey: EULAAcceptance.acceptedKey)
        defaults.set(EULAAcceptance.currentVersion, forKey: EULAAcceptance.versionKey)

        XCTAssertTrue(EULAAcceptance.hasAcceptedCurrentVersion(defaults: defaults))
    }

    func testOlderAcceptedVersionRequiresEULAAgain() throws {
        let (defaults, suiteName) = try makeDefaults()
        defer { removeDefaults(suiteName) }

        defaults.set(true, forKey: EULAAcceptance.acceptedKey)
        defaults.set("2026-01-01", forKey: EULAAcceptance.versionKey)

        XCTAssertFalse(EULAAcceptance.hasAcceptedCurrentVersion(defaults: defaults))
    }

    func testAcceptPersistsFlagVersionAndTimestamp() throws {
        let (defaults, suiteName) = try makeDefaults()
        defer { removeDefaults(suiteName) }

        let timestamp = EULAAcceptance.accept(
            date: Date(timeIntervalSince1970: 1_774_800_000),
            defaults: defaults
        )

        XCTAssertTrue(defaults.bool(forKey: EULAAcceptance.acceptedKey))
        XCTAssertEqual(defaults.string(forKey: EULAAcceptance.versionKey), EULAAcceptance.currentVersion)
        XCTAssertEqual(defaults.string(forKey: EULAAcceptance.acceptedAtKey), timestamp)
        XCTAssertNotNil(ISO8601DateFormatter().date(from: timestamp))
    }

    func testDeclineDoesNotLeaveAcceptanceStored() throws {
        let (defaults, suiteName) = try makeDefaults()
        defer { removeDefaults(suiteName) }

        EULAAcceptance.decline(defaults: defaults)

        XCTAssertFalse(defaults.bool(forKey: EULAAcceptance.acceptedKey))
        XCTAssertNil(defaults.string(forKey: EULAAcceptance.versionKey))
        XCTAssertNil(defaults.string(forKey: EULAAcceptance.acceptedAtKey))
    }
}

final class CreateNewEntityNavigationTests: XCTestCase {
    func testModalCreateFlowDismissesBeforeOpeningBotChat() {
        let currentController = UIViewController()
        let presenter = UIViewController()

        let resolution = CreateNewEntityBotRoutePolicy.resolve(
            currentController: currentController,
