            outgoing: false
        )
        let context = manager.registerSession(
            callId: call.callId,
            callUUID: call.callUUID,
            owner: call.owner,
            jid: call.jid,
            outgoing: false,
            phase: .awaitingConfirmation
        )
        manager.currentCall = call

        manager.requestIncomingAnswer(call: call, context: context, action: nil)
        manager.finishCurrentCall(reason: .signalingError, trigger: .confirmationFailure, shouldReportToCallKit: false)

        XCTAssertTrue(call.stanzaQueue.isEmpty)
        XCTAssertFalse(call.shouldSendReject)
    }

    func testCallScreenRetryStatesAreLimitedToTerminalFailures() {
        XCTAssertTrue(VoIPCall.State.notConfirmed.shouldRetryFromCallScreen)
        XCTAssertTrue(VoIPCall.State.disconnected.shouldRetryFromCallScreen)

        XCTAssertFalse(VoIPCall.State.initiated.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.proposed.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.confirmed.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.accepted.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.connecting.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.connected.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.ended.shouldRetryFromCallScreen)
        XCTAssertFalse(VoIPCall.State.holded.shouldRetryFromCallScreen)
    }

    func testCallSessionContextCancelTimersClearsAllScheduledTasks() {
        let context = CallSessionContext(
            callId: "call-id",
            callUUID: UUID(),
            owner: "owner@example.com",
            jid: "peer@example.com/resource",
            outgoing: false,
            phase: .ringing
        )
        let incoming = TestScheduledTask()
        let propose = TestScheduledTask()
        let outgoing = TestScheduledTask()
        let confirmation = TestScheduledTask()
        let media = TestScheduledTask()

        context.incomingTimeoutTask = incoming
        context.proposeSendTimeoutTask = propose
        context.outgoingTimeoutTask = outgoing
        context.confirmationTimeoutTask = confirmation
        context.mediaSetupTimeoutTask = media

        context.cancelTimers()

        XCTAssertEqual(incoming.cancelCount, 1)
        XCTAssertEqual(propose.cancelCount, 1)
        XCTAssertEqual(outgoing.cancelCount, 1)
        XCTAssertEqual(confirmation.cancelCount, 1)
        XCTAssertEqual(media.cancelCount, 1)
        XCTAssertNil(context.incomingTimeoutTask)
        XCTAssertNil(context.proposeSendTimeoutTask)
        XCTAssertNil(context.outgoingTimeoutTask)
        XCTAssertNil(context.confirmationTimeoutTask)
        XCTAssertNil(context.mediaSetupTimeoutTask)
    }

    func testOutgoingUnansweredTimeoutDismissesCallScreenAfterEndedState() {
        let manager = VoIPManager()
        let delegate = TestCallScreenDelegate()
        manager.callScreenDelegate = delegate

        manager.notifyCallScreenDidFinish(reason: .outgoingUnansweredTimeout, outgoing: true)

        XCTAssertEqual(delegate.states, [.ended])
        XCTAssertEqual(delegate.dismissCount, 1)
    }

    func testNonTimeoutFinishDoesNotDismissCallScreenAutomatically() {
        let manager = VoIPManager()
        let delegate = TestCallScreenDelegate()
        manager.callScreenDelegate = delegate

        manager.notifyCallScreenDidFinish(reason: .remoteHangup, outgoing: true)

        XCTAssertEqual(delegate.states, [.ended])
        XCTAssertEqual(delegate.dismissCount, 0)
    }

    func testUpdateMessageCanRunInsideExistingRealmWriteTransaction() throws {
        let previousConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "VoIPTerminationReasonTests-\(name)")
        defer { Realm.Configuration.defaultConfiguration = previousConfiguration }

        let owner = "owner@example.com"
        let jid = "peer@example.com"
        let callId = "call-id"
        let realm = try WRealm.safe()
        try realm.write {
            realm.deleteAll()
        }

        let message = MessageStorageItem()
        message.configureVoIPCallMessage(
            opponent: jid,
            owner: owner,
            date: Date(),
            isRead: false,
            callId: callId,
            archivedId: nil,
            outgoing: true,
            duration: 0,
            callState: .none
        )
        _ = message.save(commitTransaction: true, silentNotifications: true)

        let manager = VoIPManager()
        try realm.write {
            manager.updateMessage(
                callId,
                jid: jid,
                owner: owner,
                callStqte: .noanswer,
                duration: 30,
                terminationReason: .outgoingUnansweredTimeout,
                realm: realm
            )
        }

        let stored = try XCTUnwrap(
            realm.object(
                ofType: MessageStorageItem.self,
                forPrimaryKey: MessageStorageItem.messageIdForVoIPCall(owner: owner, jid: jid, callId: callId)
            )
        )
        let reference = try XCTUnwrap(stored.references.first)
        XCTAssertTrue(stored.isRead)
        XCTAssertEqual(reference.metadata?["callState"] as? String, MessageStorageItem.VoIPCallState.noanswer.rawValue)
        XCTAssertEqual(reference.metadata?["duration"] as? Double, 30)
        XCTAssertEqual(reference.metadata?["terminationReason"] as? String, CallTerminationReason.outgoingUnansweredTimeout.rawValue)
    }

    func testWebRTCClientNeverClosesPeerConnectionReentrantlyFromDeinit() throws {
        let repositoryRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let sourceURL = repositoryRoot.appendingPathComponent(
            "xabber/xmpp/voip/WebRTC/WebRTCClient.swift"
        )
        let source = try String(contentsOf: sourceURL, encoding: .utf8)

        XCTAssertTrue(
            source.contains("open func disconnect()"),
            "normal call teardown must retain an explicit close owner"
        )
        XCTAssertFalse(
            source.contains("deinit {\n        peerConnection.close()\n    }"),
            "a WebRTC callback may release the final client reference on the signaling thread; deinit must not close that same peer connection reentrantly"
        )
    }

    func testWebRTCOfferCompletionTransfersFinalOwnershipToMainThread() {
        let completion = expectation(description: "offer completion")
        let mainTurnAfterRelease = expectation(description: "main turn after owner release")
        let owner = WebRTCClientOwnerBox(client: WebRTCClient())

        owner.client?.offer { _, _ in
            XCTAssertTrue(
                Thread.isMainThread,
                "WebRTC callbacks must hand ownership to main before the client can be released"
            )
            owner.client?.disconnect()
            owner.client = nil
            completion.fulfill()
            DispatchQueue.main.async {
                mainTurnAfterRelease.fulfill()
            }
        }

        wait(for: [completion, mainTurnAfterRelease], timeout: 5)
        XCTAssertNil(owner.client)
    }

    func testVoIPManagerReleaseWebRTCDisconnectsExactlyOnceBeforeDroppingOwnership() {
        let manager = VoIPManager()
        let client = DisconnectSpyWebRTCClient()
        weak var releasedClient = client
        manager.webRTC = client

        manager.releaseWebRTC()
        manager.releaseWebRTC()

        XCTAssertEqual(client.disconnectCount, 1)
        XCTAssertNil(manager.webRTC)
        XCTAssertNotNil(releasedClient, "the test retains the spy while checking teardown order")
    }
}

final class AccountBootstrapTests: XCTestCase {

    private let testLoginJid = "igor.boldin@xmppdev01.xabber.com"
    private let testLoginPassword = "1234"

    func testAccountUsernameFromJIDHandlesEmptyAndMalformedValues() {
        XCTAssertEqual(Account.username(from: ""), "")
        XCTAssertEqual(Account.username(from: "xmppdev01.xabber.com"), "xmppdev01.xabber.com")
        XCTAssertEqual(Account.username(from: testLoginJid), "igor.boldin")
    }

    func testNotifyManagerExcludedDomainsIgnoresMalformedJIDs() {
        let domains = NotifyManager.excludedDomains(
            from: [
                "",
                "not a jid",
                testLoginJid,
                "room@conference.xabber.com/resource"
            ]
        )

        XCTAssertEqual(domains, [
            "xmppdev01.xabber.com",
            "conference.xabber.com"
        ])
    }

    func testXTokenManagerServerJIDIgnoresMalformedOwners() {
        XCTAssertNil(XTokenManager.serverJID(from: ""))
        XCTAssertNil(XTokenManager.serverJID(from: "not a jid"))
        XCTAssertEqual(XTokenManager.serverJID(from: testLoginJid)?.domain, "xmppdev01.xabber.com")
    }

    func testInjectXMPPCredentials() {
        CredentialsManager.shared.setItem(for: testLoginJid, password: testLoginPassword)

        let stored = CredentialsManager.shared.getItem(for: testLoginJid)
        XCTAssertEqual(stored.kind, .password)
        XCTAssertEqual(stored.creditionalString, testLoginPassword)
    }
}

final class XMPPAuthenticationFailureTests: XCTestCase {

    private func makeFailure(xml: String) throws -> XMPPAuthenticationFailure {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        let element = try XCTUnwrap(document.rootElement())
        return try XCTUnwrap(XMPPAuthenticationFailure(element: element))
    }

    func testParserReadsDocumentedFailureReasonAndText() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <account-disabled/>
          <text lang="en">Device access revoked</text>
        </failure>
        """)

        XCTAssertEqual(failure.reason, .accountDisabled)
        XCTAssertEqual(failure.text, "Device access revoked")
        XCTAssertTrue(failure.rawXML.contains("account-disabled"))
    }

    func testParserReadsFailureWithoutText() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <credentials-expired/>
        </failure>
        """)

        XCTAssertEqual(failure.reason, .credentialsExpired)
        XCTAssertNil(failure.text)
    }

    func testParserHandlesMissingCondition() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <text>Server did not include a condition</text>
        </failure>
        """)

        XCTAssertEqual(failure.reason, .missingCondition)
        XCTAssertEqual(failure.text, "Server did not include a condition")
    }

    func testParserHandlesUnknownCondition() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <custom-auth-error/>
          <text>Custom auth failure</text>
        </failure>
        """)

        XCTAssertEqual(failure.reason, .unknown("custom-auth-error"))
        XCTAssertEqual(failure.text, "Custom auth failure")
    }

    func testParserCoversStandardSASLFailureConditions() throws {
        let expectations: [(String, XMPPAuthenticationFailureReason)] = [
            ("aborted", .aborted),
            ("account-disabled", .accountDisabled),
            ("credentials-expired", .credentialsExpired),
            ("encryption-required", .encryptionRequired),
            ("incorrect-encoding", .incorrectEncoding),
            ("invalid-authzid", .invalidAuthzid),
            ("invalid-mechanism", .invalidMechanism),
            ("malformed-request", .malformedRequest),
            ("mechanism-too-weak", .mechanismTooWeak),
            ("not-authorized", .notAuthorized),
            ("temporary-auth-failure", .temporaryAuthFailure)
        ]

        for (elementName, expectedReason) in expectations {
            let failure = try makeFailure(xml: """
            <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
              <\(elementName)/>
            </failure>
            """)
            XCTAssertEqual(failure.reason, expectedReason)
        }
    }

    func testResolverRemovesAccountForRevokedDevice() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <account-disabled/>
          <text>Device access revoked</text>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .secret
        )

        XCTAssertEqual(resolution.action, .removeAccount(alertMessage: "Device was revoked"))
        XCTAssertEqual(resolution.statusMessage, "Device was revoked")
        XCTAssertFalse(resolution.shouldLogRawFailure)
    }

    func testResolverDoesNotRemoveAccountForSecondaryRevokedDeviceFailure() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <account-disabled/>
          <text>Device access revoked</text>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .secret,
            source: .secondaryStream
        )

        XCTAssertEqual(resolution.action, .reportGeneric(message: "Device was revoked"))
        XCTAssertEqual(resolution.statusMessage, "Device was revoked")
        XCTAssertTrue(resolution.shouldLogRawFailure)
    }

    func testResolverRefreshesDeviceSecretForExpiredCredentials() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <credentials-expired/>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .secret
        )

        XCTAssertEqual(resolution.action, .refreshDeviceSecret)
        XCTAssertFalse(resolution.shouldLogRawFailure)
    }

    func testResolverRejectsPasswordForNotAuthorizedPasswordAuth() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <not-authorized/>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .password
        )

        XCTAssertEqual(resolution.action, .rejectPassword(message: "Incorrect username or password"))
        XCTAssertEqual(resolution.statusMessage, "Incorrect username or password")
    }

    func testResolverRefreshesDeviceSecretForNotAuthorizedDeviceAuth() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <not-authorized/>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .token
        )

        XCTAssertEqual(resolution.action, .refreshDeviceSecret)
    }

    func testResolverRetriesTemporaryAuthFailureWithoutRevokingCredentials() throws {
        let failure = try makeFailure(xml: """
        <failure xmlns="urn:ietf:params:xml:ns:xmpp-sasl">
          <temporary-auth-failure/>
          <text>Try again later</text>
        </failure>
        """)

        let resolution = XMPPAuthenticationFailureResolution.resolve(
            failure: failure,
            credentialKind: .secret
        )

        XCTAssertEqual(resolution.action, .retryAuthentication(message: "Try again later"))
        XCTAssertTrue(resolution.shouldLogRawFailure)
        XCTAssertEqual(resolution.releaseOutcome, .authFailedRecoverable)
    }

    func testCounterTrackerReservesNextCounterBeforeSuccess() throws {
        let jid = "auth-counter-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)
        let tracker = XMPPAuthenticationCounterTracker()

        XCTAssertEqual(try tracker.counterForAuthentication(using: storage), 1)
        XCTAssertEqual(storage.currentCounter(), 2)

        tracker.authenticationDidSucceed(using: storage)
        XCTAssertEqual(storage.currentCounter(), 2)

        tracker.authenticationDidSucceed(using: storage)
        XCTAssertEqual(storage.currentCounter(), 2)
    }

    func testCounterTrackerDoesNotRollbackReservedCounterAfterFailure() throws {
        let jid = "auth-counter-failure-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)
        let tracker = XMPPAuthenticationCounterTracker()

        XCTAssertEqual(try tracker.counterForAuthentication(using: storage), 1)
        tracker.authenticationDidFail()

        XCTAssertEqual(storage.currentCounter(), 2)
    }

    func testRecoverableAuthFailureDoesNotInvalidateCredentialStorage() {
        let jid = "recoverable-auth-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)

        var firstInvalidated: Bool?
        storage.use { isInvalidated, _ in
            firstInvalidated = isInvalidated
        }

        XCTAssertEqual(firstInvalidated, false)

        storage.release(.authFailedRecoverable)

        var secondInvalidated: Bool?
        storage.use { isInvalidated, _ in
            secondInvalidated = isInvalidated
        }

        XCTAssertEqual(secondInvalidated, false)
        storage.release(.authFailedRecoverable)
    }

    func testQueuedUseAfterRecoverableFailureDoesNotReplayStaleCounter() {
        let jid = "recoverable-queue-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)

        var firstCalled = false
        var queuedCalled = false

        storage.use { _, _ in
            firstCalled = true
        }
        storage.use { _, _ in
            queuedCalled = true
        }

        XCTAssertTrue(firstCalled)
        XCTAssertFalse(queuedCalled)

        storage.release(.authFailedRecoverable)

        XCTAssertFalse(queuedCalled)

        var nextInvalidated: Bool?
        storage.use { isInvalidated, _ in
            nextInvalidated = isInvalidated
        }

        XCTAssertEqual(nextInvalidated, false)
        storage.release(.authFailedRecoverable)
    }

    func testQueuedCredentialUseSerializesCounterReservationsAfterSuccess() {
        let jid = "serialized-counter-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)
        let firstTracker = XMPPAuthenticationCounterTracker()
        let secondTracker = XMPPAuthenticationCounterTracker()

        var firstCounter: UInt64?
        var secondCounter: UInt64?

        storage.use { _, item in
            firstCounter = try? firstTracker.counterForAuthentication(using: item)
        }
        storage.use { _, item in
            secondCounter = try? secondTracker.counterForAuthentication(using: item)
        }

        XCTAssertEqual(firstCounter, 1)
        XCTAssertEqual(storage.currentCounter(), 2)
        XCTAssertNil(secondCounter)

        firstTracker.authenticationDidSucceed(using: storage)
        storage.release(.authSucceeded)

        XCTAssertEqual(secondCounter, 2)
        XCTAssertEqual(storage.currentCounter(), 3)

        secondTracker.authenticationDidFail()
        storage.release(.authFailedRecoverable)
        XCTAssertEqual(storage.currentCounter(), 3)
    }

    func testConcurrentCounterReservationsAreUniqueAndDurable() {
        let jid = "concurrent-counter-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)
        let attempts = 20
        let lock = NSLock()
        var counters: [UInt64] = []
        var failures = 0

        DispatchQueue.concurrentPerform(iterations: attempts) { _ in
            guard let reservation = try? storage.reserveCounterForAuthentication() else {
                lock.lock()
                failures += 1
                lock.unlock()
                return
            }
            lock.lock()
            counters.append(reservation.counter)
            lock.unlock()
        }

        let expected = (1...attempts).map(UInt64.init)
        XCTAssertEqual(failures, 0)
        XCTAssertEqual(counters.sorted(), expected)
        XCTAssertEqual(storage.currentCounter(), UInt64(attempts + 1))
    }

    func testCounterReservationPersistenceFailureDoesNotAdvanceCounter() {
        let jid = "counter-persistence-failure-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)

        CredentialsManager.Storage.counterPersistenceOverride = { _, _ in false }
        defer { CredentialsManager.Storage.counterPersistenceOverride = nil }

        XCTAssertThrowsError(try storage.reserveCounterForAuthentication())
        XCTAssertEqual(storage.currentCounter(), 1)
    }

    func testCounterReservationSurvivesFreshStorageRead() throws {
        let jid = "counter-relaunch-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)

        let firstReservation = try storage.reserveCounterForAuthentication()
        XCTAssertEqual(firstReservation.counter, 1)
        XCTAssertEqual(firstReservation.nextCounter, 2)

        let freshStorage = CredentialsManager.Storage(jid: jid)
        XCTAssertEqual(freshStorage.currentCounter(), 2)

        let secondReservation = try freshStorage.reserveCounterForAuthentication()
        XCTAssertEqual(secondReservation.counter, 2)
        XCTAssertEqual(secondReservation.nextCounter, 3)
    }

    func testCredentialRevocationKeepsStorageInvalidated() {
        let jid = "credential-revoked-\(UUID().uuidString)@example.com"
        CredentialsManager.shared.setItem(for: jid, token: "token")
        let storage = CredentialsManager.shared.getItem(for: jid)

        storage.use { _, _ in }
        storage.release(.credentialRevoked)
        storage.release(.authFailedRecoverable)

        var invalidated: Bool?
        storage.use { isInvalidated, _ in
            invalidated = isInvalidated
        }

        XCTAssertEqual(invalidated, true)
        storage.release(.authFailedRecoverable)
    }

    func testOCRAHotpFormattingUsesRequestedDigitCount() {
        XCTAssertEqual(DevicesOCRA.hotpString(forTruncatedHash: 123, digits: 8), "00000123")
        XCTAssertEqual(DevicesOCRA.hotpString(forTruncatedHash: 123456789, digits: 4), "6789")
    }
}

final class AccountConnectionResilienceCoordinatorTests: XCTestCase {

    func testPingSuccessResetsLivenessTimer() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)

        harness.scheduler.advance(by: 15)
        XCTAssertEqual(harness.recorder.sendPingCount, 1)

        harness.scheduler.advance(by: 7.9)
        harness.coordinator.notePingResult(success: true)
        harness.scheduler.advance(by: 8)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)

        harness.scheduler.advance(by: 7.1)
        XCTAssertEqual(harness.recorder.sendPingCount, 2)
    }

    func testPingTimeoutDoesNotCloseEstablishedSMStream() {
        let harness = makeHarness(canResume: true)

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)

        harness.scheduler.advance(by: 15)
        harness.scheduler.advance(by: 8)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertTrue(harness.recorder.staleReasons.isEmpty)
    }

    func testForcedDisconnectCallbackDoesNotScheduleSecondReconnect() {
        let harness = makeHarness(canResume: true)

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.requestImmediateReconnect(
            cause: .streamManagementAckTimeout,
            trigger: .resilienceRetry
        )
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.reconnectTriggers, [.resilienceRetry])

        harness.coordinator.streamDidDisconnect(
            cause: .streamManagementAckTimeout,
            reconnectAlreadyScheduled: true
        )
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.reconnectTriggers, [.resilienceRetry])
        XCTAssertTrue(
            harness.recorder.diagnosticsEvents.contains("resilience_disconnect_reconnect_already_scheduled")
        )
    }

    func testApplicationStanzaTimeoutIsDiagnosticOnlyForEstablishedStream() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.notePrimaryStreamAckTimeout(stanzaId: "iq-result", generation: 1)
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.sendPingCount, 0)
        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)

        harness.coordinator.noteStreamManagementAck()
        harness.scheduler.advance(by: 8)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
    }

    func testPrimaryStreamTrackingLimitIsDiagnosticOnlyForEstablishedStream() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.notePrimaryStreamTrackingLimitRejected(.countLimit(max: 1))
        harness.scheduler.advance(by: 0)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertTrue(harness.recorder.staleReasons.isEmpty)
    }

    func testForegroundOnlineWithoutConfirmedTrafficUsesNonFatalProbe() {
        let policy = AccountConnectionResiliencePolicy(
            pingInterval: 45,
            pingTimeout: 8,
            maxMissedPings: 1,
            staleActivityTimeout: 40,
            pathDebounce: 0.75,
            stableOnlineReset: 60,
            reconnectBaseDelay: 2,
            reconnectMaxDelay: 60,
            jitterRatio: 0.2,
            fastResumeDelays: [0, 1],
            outboundConfirmationTimeout: 8,
            bindingSetupTimeout: 8,
            jitter: { 0 }
        )
        let harness = makeHarness(policy: policy)

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.scheduler.advance(by: 45)

        XCTAssertEqual(harness.recorder.sendPingCount, 1)
        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertTrue(harness.recorder.staleReasons.isEmpty)
        XCTAssertFalse(harness.coordinator.healthSnapshot.isSuspectedStale)
    }

    func testOutboundApplicationConfirmationTimeoutIsDiagnosticOnly() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.noteOutboundApplicationStanza(id: "message-1")
        harness.scheduler.advance(by: 8)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertTrue(harness.recorder.staleReasons.isEmpty)
        XCTAssertEqual(harness.coordinator.healthSnapshot.lastOutboundStanzaAt, 0)
    }

    func testBlockedApplicationQueueDoesNotCloseEstablishedSMStream() {
        let harness = makeHarness(canResume: true)

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.scheduler.advance(by: 15)

        XCTAssertEqual(harness.recorder.sendPingCount, 1)

        harness.scheduler.advance(by: 8)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
    }

    func testStreamManagementAckTimeoutClosesEstablishedStream() {
        let harness = makeHarness(canResume: true)

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.noteStreamManagementAckTimeout()
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.forceCloseCauses, [.streamManagementAckTimeout])
        XCTAssertEqual(harness.recorder.reconnectTriggers, [.resilienceRetry])
        XCTAssertEqual(harness.recorder.staleReasons, [.streamManagementAckTimeout])
    }

    func testIntentionalDisconnectDoesNotAutoReconnect() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.streamDidDisconnect(cause: .backgroundSuspension)

        harness.scheduler.advance(by: 120)

        XCTAssertTrue(harness.recorder.sendPingCount == 0 || harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
    }

    func testPathUnsatisfiedPausesRetries() {
        let harness = makeHarness()

        harness.coordinator.networkPathDidChange(.init(status: .unsatisfied, interfaces: [.wifi]))
        harness.scheduler.advance(by: 0.75)
        harness.coordinator.streamDidDisconnect(cause: .accidentalSocket)
        harness.scheduler.advance(by: 120)

        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
    }

    func testPathRecoveryStartsImmediateReconnect() {
        let harness = makeHarness()

        harness.coordinator.networkPathDidChange(.init(status: .unsatisfied, interfaces: [.wifi]))
        harness.scheduler.advance(by: 0.75)
        harness.coordinator.streamDidDisconnect(cause: .accidentalSocket)
        harness.scheduler.advance(by: 10)

        harness.coordinator.networkPathDidChange(.init(status: .satisfied, interfaces: [.cellular]))
        harness.scheduler.advance(by: 0.75)

        XCTAssertEqual(harness.recorder.reconnectTriggers, [.pathRecovery])
    }

    func testPathRecoveryProbesClaimedOnlineStream() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.coordinator.networkPathDidChange(.init(status: .unsatisfied, interfaces: [.wifi]))
        harness.scheduler.advance(by: 0.75)
        harness.coordinator.networkPathDidChange(.init(status: .satisfied, interfaces: [.cellular]))
        harness.scheduler.advance(by: 0.75)

        XCTAssertEqual(harness.recorder.probeOnlineStreamCount, 1)
    }

    func testPathInterfaceChangeInvalidatesEndpointResolutionCache() {
        let harness = makeHarness()

        harness.coordinator.networkPathDidChange(.init(status: .satisfied, interfaces: [.wifi]))
        harness.scheduler.advance(by: 0.75)
        harness.coordinator.networkPathDidChange(.init(status: .satisfied, interfaces: [.cellular]))
        harness.scheduler.advance(by: 0.75)

        XCTAssertEqual(harness.recorder.endpointResolutionInvalidationReasons, ["path-changed"])
    }

    func testForegroundRecoveryInvalidatesEndpointResolutionCache() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(false)
        harness.coordinator.setForegroundActive(true)
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.endpointResolutionInvalidationReasons, ["foreground-active"])
    }

    func testSMResumeSuccessSkipsFullSetup() {
        let harness = makeHarness()

        harness.coordinator.streamManagementResumeCompleted(didResume: true, responseName: "resumed")
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.skipFullSetupCount, 1)
        XCTAssertEqual(harness.recorder.fullSetupCount, 0)
    }

    func testSMResumeFailureFallsBackToFullSetup() {
        let harness = makeHarness()

        harness.coordinator.streamManagementResumeCompleted(didResume: false, responseName: "failed")
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.skipFullSetupCount, 0)
        XCTAssertEqual(harness.recorder.fullSetupCount, 1)
    }

    func testDuplicateReconnectAttemptsAreStillBlockedByLifecycleGate() {
        let gate = AccountStreamLifecycleGate()
        let harness = makeHarness(canResume: true, gate: gate)

        harness.coordinator.scheduleReconnect(cause: .accidentalSocket, trigger: .resilienceRetry)
        harness.scheduler.advance(by: 0)
        harness.coordinator.scheduleReconnect(cause: .accidentalSocket, trigger: .resilienceRetry)
        harness.scheduler.advance(by: 0)
        harness.scheduler.advance(by: 1)

        XCTAssertEqual(harness.recorder.reconnectWasStarted, [true, false])
    }

    func testBindingWatchdogDoesNotFireBeforeTimeout() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidEnterBinding()
        harness.scheduler.advance(by: 7.9)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertTrue(harness.recorder.staleReasons.isEmpty)
    }

    func testBindingWatchdogTimeoutForceClosesAndReconnectsImmediately() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidEnterBinding()
        harness.scheduler.advance(by: 8)

        XCTAssertEqual(harness.recorder.forceCloseCauses, [.bindingTimeout])
        XCTAssertEqual(harness.recorder.reconnectTriggers, [.resilienceRetry])
        XCTAssertEqual(harness.recorder.staleReasons, [.bindingTimeout])
        XCTAssertTrue(harness.recorder.diagnosticsEvents.contains("resilience_binding_timeout"))
    }

    func testBindingWatchdogCancelsWhenStreamReachesOnline() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidEnterBinding()
        harness.scheduler.advance(by: 4)
        harness.coordinator.streamDidReachOnline(resumed: false)
        harness.scheduler.advance(by: 20)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertFalse(harness.coordinator.healthSnapshot.isSuspectedStale)
    }

    func testBindingWatchdogDoesNotStartWhenForegroundInactive() {
        let harness = makeHarness()

        harness.coordinator.streamDidEnterBinding()
        harness.scheduler.advance(by: 20)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
    }

    func testBindingWatchdogCancelsWhenPathBecomesUnsatisfied() {
        let harness = makeHarness()

        harness.coordinator.setForegroundActive(true)
        harness.coordinator.streamDidEnterBinding()
        harness.coordinator.networkPathDidChange(.init(status: .unsatisfied, interfaces: [.wifi]))
        harness.scheduler.advance(by: 0.75)
        harness.scheduler.advance(by: 20)

        XCTAssertTrue(harness.recorder.forceCloseCauses.isEmpty)
        XCTAssertTrue(harness.recorder.reconnectTriggers.isEmpty)
        XCTAssertEqual(harness.coordinator.healthSnapshot.isNetworkPathSatisfied, false)
    }

    func testImmediateReconnectBypassesBackoffForForegroundRecovery() {
        let harness = makeHarness()

        harness.coordinator.requestImmediateReconnect(cause: .accidentalSocket, trigger: .uiActionOpen)
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.reconnectTriggers, [.uiActionOpen])
    }

    func testExternalResilienceActionsNeverRunWhileStateLockIsHeld() {
        let harness = makeHarness(canResume: true)
        let coordinator = harness.coordinator

        let assertHealthSnapshotIsNotLocked: () -> Void = {
            let completed = DispatchSemaphore(value: 0)
            DispatchQueue.global(qos: .userInitiated).async {
                _ = coordinator.healthSnapshot
                completed.signal()
            }
            XCTAssertEqual(completed.wait(timeout: .now() + 0.2), .success)
        }
        harness.recorder.onCanResumeStream = assertHealthSnapshotIsNotLocked
        harness.recorder.onRequestReconnect = assertHealthSnapshotIsNotLocked
        harness.recorder.onHealthChanged = assertHealthSnapshotIsNotLocked

        coordinator.updatePendingOutgoingCount(1)
        coordinator.scheduleReconnect(cause: .accidentalSocket, trigger: .resilienceRetry)
        harness.scheduler.advance(by: 0)

        XCTAssertEqual(harness.recorder.reconnectTriggers, [.resilienceRetry])
    }

    private func makeHarness(
        canResume: Bool = false,
        gate: AccountStreamLifecycleGate? = nil,
        policy: AccountConnectionResiliencePolicy = .aggressive(jitter: { 0 })
    ) -> AccountConnectionResilienceHarness {
        let scheduler = TestAccountConnectionResilienceScheduler()
        let recorder = AccountConnectionResilienceActionRecorder(canResume: canResume, gate: gate)
        let coordinator = AccountConnectionResilienceCoordinator(
            policy: policy,
            scheduler: scheduler,
            actions: recorder.actions
        )
        return AccountConnectionResilienceHarness(
            coordinator: coordinator,
            scheduler: scheduler,
            recorder: recorder
        )
    }
}

private struct AccountConnectionResilienceHarness {
    let coordinator: AccountConnectionResilienceCoordinator
    let scheduler: TestAccountConnectionResilienceScheduler
    let recorder: AccountConnectionResilienceActionRecorder
}

private final class AccountConnectionResilienceActionRecorder {
    private let canResume: Bool
    private let gate: AccountStreamLifecycleGate?
    private(set) var sendPingCount = 0
    private(set) var forceCloseCauses: [AccountDisconnectCause] = []
    private(set) var reconnectTriggers: [AccountConnectTrigger] = []
    private(set) var reconnectWasStarted: [Bool] = []
    private(set) var probeOnlineStreamCount = 0
    private(set) var skipFullSetupCount = 0
    private(set) var fullSetupCount = 0
    private(set) var diagnosticsEvents: [String] = []
    private(set) var endpointResolutionInvalidationReasons: [String] = []
    private(set) var staleReasons: [AccountConnectionStaleReason] = []
    private(set) var healthSnapshots: [AccountConnectionHealthSnapshot] = []
    var onCanResumeStream: (() -> Void)?
    var onRequestReconnect: (() -> Void)?
    var onHealthChanged: (() -> Void)?

    init(canResume: Bool, gate: AccountStreamLifecycleGate?) {
        self.canResume = canResume
        self.gate = gate
    }

    var actions: AccountConnectionResilienceActions {
        AccountConnectionResilienceActions(
            sendPing: { [weak self] in
                self?.sendPingCount += 1
                return true
            },
            forceClose: { [weak self] cause in
                self?.forceCloseCauses.append(cause)
            },
            requestReconnect: { [weak self] trigger, _ in
                self?.onRequestReconnect?()
                self?.reconnectTriggers.append(trigger)
                guard let gate = self?.gate else {
                    self?.reconnectWasStarted.append(true)
                    return true
                }
                switch gate.beginConnect(trigger: trigger) {
                case .start:
                    self?.reconnectWasStarted.append(true)
                    return true
                case .skip:
                    self?.reconnectWasStarted.append(false)
                    return false
                }
            },
            probeOnlineStream: { [weak self] in
                self?.probeOnlineStreamCount += 1
            },
            canResumeStream: { [weak self] in
                self?.onCanResumeStream?()
                return self?.canResume ?? false
            },
            skipFullSetupAfterResume: { [weak self] in
                self?.skipFullSetupCount += 1
            },
            runFullSetupAfterAuthentication: { [weak self] in
                self?.fullSetupCount += 1
            },
            invalidateEndpointResolutionCache: { [weak self] reason in
                self?.endpointResolutionInvalidationReasons.append(reason)
            },
            markSuspectedStale: { [weak self] reason, _ in
                self?.staleReasons.append(reason)
            },
            healthChanged: { [weak self] snapshot in
                self?.onHealthChanged?()
                self?.healthSnapshots.append(snapshot)
            },
            log: { [weak self] event, _ in
                self?.diagnosticsEvents.append(event)
            }
        )
    }
}

private final class TestAccountConnectionResilienceScheduler: AccountConnectionResilienceScheduling {
    private final class Scheduled: AccountConnectionResilienceCancellable {
        let id: Int
        let due: TimeInterval
        let block: () -> Void
        var isCancelled = false

        init(id: Int, due: TimeInterval, block: @escaping () -> Void) {
            self.id = id
            self.due = due
            self.block = block
        }

        func cancel() {
            isCancelled = true
        }
    }

    private(set) var now: TimeInterval = 0
    private var nextID = 0
    private var scheduled: [Scheduled] = []

    func schedule(after delay: TimeInterval, _ block: @escaping () -> Void) -> AccountConnectionResilienceCancellable {
        nextID += 1
        let item = Scheduled(id: nextID, due: now + max(delay, 0), block: block)
        scheduled.append(item)
        return item
    }

    func advance(by interval: TimeInterval) {
        now += interval
        while let next = scheduled
            .filter({ !$0.isCancelled && $0.due <= now })
            .sorted(by: { lhs, rhs in
                if lhs.due == rhs.due {
                    return lhs.id < rhs.id
                }
                return lhs.due < rhs.due
            })
            .first {
            next.cancel()
            next.block()
        }
        scheduled.removeAll { $0.isCancelled }
    }
}

final class AccountSendReadinessCoordinatorTests: XCTestCase {

    func testReadinessStaysFalseUntilStreamManagementIsEnabled() {
        let coordinator = AccountSendReadinessCoordinator()

        coordinator.markConnecting(trigger: .initialLoad)
        coordinator.markAuthenticating()
        coordinator.markBinding()
        coordinator.markStreamManagementEnableRequested()

        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)

        coordinator.markStreamManagementEnabled()

        XCTAssertTrue(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .ready(.streamManagementEnabled))
    }

    func testSuccessfulResumeBecomesSendReadyWithoutEnableRoundTrip() {
        let coordinator = AccountSendReadinessCoordinator()

        coordinator.markConnecting(trigger: .xmppReconnect)
        coordinator.markResuming()
        coordinator.markStreamManagementResumeSucceeded()

        XCTAssertTrue(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .ready(.streamManagementResumed))
    }

    func testStreamManagementEnableFailureKeepsStrictQueueNotReady() {
        let coordinator = AccountSendReadinessCoordinator()

        coordinator.markConnecting(trigger: .initialLoad)
        coordinator.markStreamManagementEnableRequested()
        coordinator.markStreamManagementEnableFailed(reason: "failed")

        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .streamManagementFailed)
    }

    func testDisconnectBackgroundAndStreamErrorClearReadiness() {
        let coordinator = AccountSendReadinessCoordinator()

        coordinator.markStreamManagementEnabled()
        XCTAssertTrue(coordinator.snapshot.canFlushApplicationStanzas)

        coordinator.markDisconnected(cause: .backgroundSuspension)
        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .backgroundSuspended)

        coordinator.markStreamManagementEnabled()
        coordinator.markStreamError()
        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .streamError)
    }

    func testSuspectedStaleClearsSendReadiness() {
        let coordinator = AccountSendReadinessCoordinator()

        coordinator.markStreamManagementEnabled()
        XCTAssertTrue(coordinator.snapshot.canFlushApplicationStanzas)

        coordinator.markSuspectedStale(reason: AccountConnectionStaleReason.noConfirmedTraffic.rawValue)

        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)
        XCTAssertEqual(coordinator.snapshot.phase, .suspectedStale)
        XCTAssertEqual(coordinator.snapshot.reason, AccountConnectionStaleReason.noConfirmedTraffic.rawValue)
    }

    func testConnectingUsersDoesNotAffectSendReadiness() {
        let coordinator = AccountSendReadinessCoordinator()
        let jid = "send-readiness-\(UUID().uuidString)@example.com"

        AccountManager.shared.markAsConnecting(jid: jid)
        AccountManager.shared.markAsConnected(jid: jid)

        XCTAssertFalse(coordinator.snapshot.canFlushApplicationStanzas)

        AccountManager.shared.markAsNotConnecting(
            jid: jid,
            reason: "test-cleanup",
            clearAuthentication: true
        )
    }
}

final class AccountForegroundConnectionRecoveryPolicyTests: XCTestCase {

    func testHostedIsolatedTestProcessCannotRequestForegroundReconnect() {
        let decision = AccountForegroundConnectionRecoveryPolicy.decide(
            canFlushApplicationStanzas: false,
            lifecyclePhase: .idle,
            isNetworkPathSatisfied: true,
            isConnectionRecoveryAllowed: false
        )

        XCTAssertEqual(decision, .skip)
    }

    func testIdleNotReadySatisfiedPathRequestsImmediateReconnect() {
        let decision = AccountForegroundConnectionRecoveryPolicy.decide(
            canFlushApplicationStanzas: false,
            lifecyclePhase: .idle,
            isNetworkPathSatisfied: true
        )

        XCTAssertEqual(decision, .requestImmediateReconnect)
    }

    func testFailedNotReadyUnknownPathRequestsImmediateReconnect() {
        let decision = AccountForegroundConnectionRecoveryPolicy.decide(
            canFlushApplicationStanzas: false,
            lifecyclePhase: .failed,
            isNetworkPathSatisfied: nil
        )

        XCTAssertEqual(decision, .requestImmediateReconnect)
    }

    func testActiveBindingAttemptIsLeftForWatchdog() {
        let decision = AccountForegroundConnectionRecoveryPolicy.decide(
            canFlushApplicationStanzas: false,
            lifecyclePhase: .binding,
            isNetworkPathSatisfied: true
        )

        XCTAssertEqual(decision, .waitForActiveAttempt)
    }

    func testReadyOrUnsatisfiedPathSkipsForegroundRecovery() {
        XCTAssertEqual(
            AccountForegroundConnectionRecoveryPolicy.decide(
                canFlushApplicationStanzas: true,
                lifecyclePhase: .idle,
                isNetworkPathSatisfied: true
            ),
            .skip
        )
        XCTAssertEqual(
            AccountForegroundConnectionRecoveryPolicy.decide(
                canFlushApplicationStanzas: false,
                lifecyclePhase: .idle,
                isNetworkPathSatisfied: false
            ),
            .skip
        )
    }
}

final class ChatConnectionStatusTextPolicyTests: XCTestCase {

    func testBindingWithSatisfiedPathShowsConnectingInsteadOfWaitingForNetwork() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: nil,
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .binding),
            isNetworkPathSatisfied: true,
            fallbackStatus: "Online"
        )

        XCTAssertEqual(text, ChatConnectionStatusTextPolicy.connectingText)
    }

    func testUnsatisfiedPathShowsWaitingForNetwork() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: nil,
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .binding),
            isNetworkPathSatisfied: false,
            fallbackStatus: "Online"
        )

        XCTAssertEqual(text, ChatConnectionStatusTextPolicy.waitingForNetworkText)
    }

    func testBackgroundSuspendedFallsBackToContactStatus() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: nil,
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .backgroundSuspended),
            isNetworkPathSatisfied: true,
            fallbackStatus: "Last seen recently"
        )

        XCTAssertEqual(text, "Last seen recently")
    }

    func testActionTextHasPriorityOverConnectionState() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: "typing...",
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .binding),
            isNetworkPathSatisfied: false,
            fallbackStatus: "Online"
        )

        XCTAssertEqual(text, "typing...")
    }

    private func snapshot(phase: AccountSendReadinessPhase) -> AccountSendReadinessSnapshot {
        AccountSendReadinessSnapshot(
            phase: phase,
            updatedAt: Date(timeIntervalSince1970: 0),
            reason: nil
        )
    }
}

final class AccountSendCoordinatorTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "AccountSendCoordinatorTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testQueuedMessageDoesNotFlushBeforeSendReady() throws {
        var isReady = false
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        XCTAssertTrue(recorder.sentMessages.isEmpty)

        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])
    }

    func testQueuedRegularMessageCanonicalizesFullDestinationJidToBareWhenSent() throws {
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { true }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(
            opponent: "romeo@example.com",
            stanzaTo: "romeo@example.com/iPhone",
            originId: "message-1"
        ))

        let message = try XCTUnwrap(recorder.sentMessages.first)
        XCTAssertEqual(message.to?.bare, "romeo@example.com")
        XCTAssertNil(message.to?.resource)
    }

    func testPerChatOrderingWaitsForReceiptBeforeNextSend() throws {
        let isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1", createdAt: Date(timeIntervalSince1970: 1)))
        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-2", createdAt: Date(timeIntervalSince1970: 2)))

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])

        coordinator.deliveryReceiptReceived(originId: "message-1", stanzaId: "archive-1")

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-2"])
    }

    func testSuccessfulResumeDoesNotDuplicateAwaitingReceiptMessage() throws {
        var isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))
        XCTAssertEqual(recorder.sentMessages.count, 1)

        isReady = false
        coordinator.streamDidDisconnect(canResume: true)
        isReady = true
        coordinator.streamManagementResumeSucceeded()

        XCTAssertEqual(recorder.sentMessages.count, 1)
    }

    func testFullReconnectReplaysWithSameOriginIdAndRetryMarkup() throws {
        var isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        isReady = false
        coordinator.streamDidDisconnect(canResume: true)
        coordinator.streamManagementResumeFailed()
        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-1"])
        XCTAssertNotNil(recorder.sentMessages.last?.element(forName: "retry", xmlns: "https://xabber.com/protocol/delivery"))
        XCTAssertEqual(
            recorder.sentMessages.last?.element(forName: "origin-id", xmlns: "urn:xmpp:sid:0")?.attributeStringValue(forName: "id"),
            "message-1"
        )
    }

    func testServerErrorMarksQueueTerminalAndStopsRetry() throws {
        let isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))
        coordinator.terminalFailure(originId: "message-1", error: "Forbidden")
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.count, 1)
        let realm = try WRealm.safe()
        let item = try XCTUnwrap(realm.objects(OutgoingMessageQueueItem.self).first)
        XCTAssertEqual(item.state, .terminalFailed)
        XCTAssertEqual(item.lastError, "Forbidden")
    }

    func testMessageManagerInitPreservesRecoverablePendingSend() throws {
        let owner = "owner@example.com"
        let message = try storeRecoverableMessage(owner: owner, originId: "pending-1")

        let manager = MessageManager(withOwner: owner, activeStream: true)
        manager.updateSendingMessagesTimer?.invalidate()
        manager.updateSendingMessagesTimer = nil

        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: message.primary))
        XCTAssertEqual(stored.state, .sending)
        XCTAssertNil(stored.messageError)
        XCTAssertEqual(realm.objects(OutgoingMessageQueueItem.self).filter("messagePrimary == %@", message.primary).count, 1)
    }

    func testSendSimpleMessagePersistsSendingStateAndDurableQueueSynchronously() throws {
        let owner = "owner@example.com"
        let manager = MessageManager(withOwner: owner, activeStream: true)
        defer {
            manager.updateSendingMessagesTimer?.invalidate()
            manager.updateSendingMessagesTimer = nil
        }

        let originId = manager.sendSimpleMessage(
            "Hello",
            to: "romeo@example.com",
            forwarded: [],
            conversationType: .regular
        )

        let realm = try WRealm.safe()
        let message = try XCTUnwrap(realm.object(
            ofType: MessageStorageItem.self,
            forPrimaryKey: MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        ))
        XCTAssertEqual(message.state, .sending)
        XCTAssertEqual(message.body, "Hello")
        XCTAssertEqual(
            realm.objects(OutgoingMessageQueueItem.self)
                .filter("owner == %@ AND originId == %@", owner, originId)
                .count,
            1
        )
    }

    func testQueuedMessageDoesNotFlushWhileSuspectedStaleAndFlushesAfterReady() throws {
        var isReady = false
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        XCTAssertTrue(recorder.sentMessages.isEmpty)

        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])
    }

    private func makeCoordinator(
        owner: String = "owner@example.com",
        isReady: @escaping () -> Bool,
        recorder: AccountSendCoordinatorRecorder
    ) -> AccountSendCoordinator {
        AccountSendCoordinator(
            environment: AccountSendCoordinator.Environment(
                owner: owner,
                isSendReady: isReady,
                decorateMessage: { message, retry, missRetryElement in
                    if retry && !missRetryElement {
                        message.addChild(DDXMLElement(name: "retry", xmlns: "https://xabber.com/protocol/delivery"))
                    }
                    return message
                },
                sendMessage: { message in
                    recorder.sentMessages.append(message.copy() as! XMPPMessage)
                },
                log: { _, _ in }
            )
        )
    }

    private func makeRequest(
        owner: String = "owner@example.com",
        opponent: String = "romeo@example.com",
        stanzaTo: String? = nil,
        originId: String,
        createdAt: Date = Date(timeIntervalSince1970: 1)
    ) -> AccountQueuedMessageSendRequest {
        let stanzaTo = stanzaTo ?? opponent
        return AccountQueuedMessageSendRequest(
            owner: owner,
            conversationJid: opponent,
            conversationType: .regular,
            messagePrimary: MessageStorageItem.genPrimary(messageId: originId, owner: owner),
            originId: originId,
            stanzaXML: """
            <message type='chat' to='\(stanzaTo)' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            createdAt: createdAt,
            replayRequired: false
        )
    }

    @discardableResult
    private func storeRecoverableMessage(owner: String, originId: String) throws -> MessageStorageItem {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.owner = owner
        message.opponent = "romeo@example.com"
        message.outgoing = true
        message.messageId = originId
        message.primary = MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        message.conversationType = .regular
        message.displayAs = .text
        message.body = "Hello"
        message.legacyBody = "Hello"
        message.state = .sending
        message.date = Date(timeIntervalSince1970: 1)
        message.sentDate = message.date

        let stanza = MessageStanzaStorageItem()
        stanza.set(
            originId,
            for: owner,
            with: """
            <message type='chat' to='romeo@example.com' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            at: message.date,
            primary: message.primary
        )

        try realm.write {
            realm.add(message, update: .modified)
            realm.add(stanza, update: .modified)
        }
        return message
    }
}

private final class AccountSendCoordinatorRecorder {
    var sentMessages: [XMPPMessage] = []
}

final class ReliableMessageDeliveryReceiptProcessorTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "ReliableMessageDeliveryReceiptProcessorTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testReceiptAppliesMessageStateAndAdvancesOutgoingQueue() throws {
        let owner = "owner@example.com"
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = AccountSendCoordinator(
            environment: AccountSendCoordinator.Environment(
                owner: owner,
                isSendReady: { true },
                decorateMessage: { message, _, _ in message },
                sendMessage: { message in
                    recorder.sentMessages.append(message.copy() as! XMPPMessage)
                },
                log: { _, _ in }
            )
        )
        try storeSendingMessage(owner: owner, originId: "message-1")
        try storeSendingMessage(owner: owner, originId: "message-2")
        try coordinator.enqueueRegularMessage(makeRequest(owner: owner, originId: "message-1", createdAt: Date(timeIntervalSince1970: 1)))
        try coordinator.enqueueRegularMessage(makeRequest(owner: owner, originId: "message-2", createdAt: Date(timeIntervalSince1970: 2)))

        let receipt = XabberDeliveryReceipt(
            originId: "message-1",
            stanzaId: "archive-1",
            stamp: Date(timeIntervalSince1970: 100)
        )
        let applied = ReliableMessageDeliveryReceiptProcessor.apply(owner: owner, receipt: receipt) { originId, stanzaId in
            coordinator.deliveryReceiptReceived(originId: originId, stanzaId: stanzaId)
        }

        XCTAssertTrue(applied)
        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-2"])

        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(realm.object(
            ofType: MessageStorageItem.self,
            forPrimaryKey: MessageStorageItem.genPrimary(messageId: "message-1", owner: owner)
        ))
        XCTAssertEqual(stored.state, .sended)
        XCTAssertEqual(stored.archivedId, "archive-1")
        XCTAssertEqual(stored.date, Date(timeIntervalSince1970: 100))
        XCTAssertEqual(
            realm.objects(OutgoingMessageQueueItem.self)
                .filter("owner == %@ AND originId == %@", owner, "message-1")
                .count,
            0
        )
    }

    func testReceiptPublishesLiveAdmissionIdentityAfterNumericArchiveIDPersistence() throws {
        let owner = "owner@example.com"
        try storeSendingMessage(owner: owner, originId: "message-live")
        var admitted: [(conversation: ArchiveConversationKey, primaryID: String)] = []

        let applied = ReliableMessageDeliveryReceiptProcessor.apply(
            owner: owner,
            receipt: XabberDeliveryReceipt(
                originId: "message-live",
                stanzaId: "7001",
                stamp: Date(timeIntervalSince1970: 100)
            ),
            onLiveMessagePersisted: { conversation, primaryID in
                admitted.append((conversation, primaryID))
            },
            onApplied: { _, _ in }
        )

        XCTAssertTrue(applied)
        XCTAssertEqual(admitted.count, 1)
        XCTAssertEqual(
            admitted.first?.conversation,
            ArchiveConversationKey(
                owner: owner,
                jid: "romeo@example.com",
                conversationType: .regular
            )
        )
        XCTAssertEqual(
            admitted.first?.primaryID,
            MessageStorageItem.genPrimary(
                messageId: "message-live",
                owner: owner
            )
        )
        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(realm.object(
            ofType: MessageStorageItem.self,
            forPrimaryKey: MessageStorageItem.genPrimary(
                messageId: "message-live",
                owner: owner
            )
        ))
        XCTAssertEqual(stored.archivedId, "7001")
    }

    func testDuplicateNumericAndNonnumericReceiptsDoNotRepublishLiveAdmission() throws {
        let owner = "owner@example.com"
        try storeSendingMessage(owner: owner, originId: "message-duplicate")
        try storeSendingMessage(owner: owner, originId: "message-nonnumeric")
        var admittedPrimaryIDs: [String] = []
        let admit: (ArchiveConversationKey, String) -> Void = { _, primaryID in
            admittedPrimaryIDs.append(primaryID)
        }
        let numericReceipt = XabberDeliveryReceipt(
            originId: "message-duplicate",
            stanzaId: "7002",
            stamp: Date(timeIntervalSince1970: 101)
        )

        XCTAssertTrue(ReliableMessageDeliveryReceiptProcessor.apply(
            owner: owner,
            receipt: numericReceipt,
            onLiveMessagePersisted: admit,
            onApplied: { _, _ in }
        ))
        XCTAssertTrue(ReliableMessageDeliveryReceiptProcessor.apply(
            owner: owner,
            receipt: numericReceipt,
            onLiveMessagePersisted: admit,
            onApplied: { _, _ in }
        ))
        XCTAssertTrue(ReliableMessageDeliveryReceiptProcessor.apply(
            owner: owner,
            receipt: XabberDeliveryReceipt(
                originId: "message-nonnumeric",
                stanzaId: "legacy-archive-id",
                stamp: Date(timeIntervalSince1970: 102)
            ),
            onLiveMessagePersisted: admit,
            onApplied: { _, _ in }
        ))

        XCTAssertEqual(
            admittedPrimaryIDs,
            [MessageStorageItem.genPrimary(
                messageId: "message-duplicate",
                owner: owner
            )]
        )
    }

    private func makeRequest(
        owner: String,
        opponent: String = "romeo@example.com",
        originId: String,
        createdAt: Date
    ) -> AccountQueuedMessageSendRequest {
        AccountQueuedMessageSendRequest(
            owner: owner,
            conversationJid: opponent,
            conversationType: .regular,
            messagePrimary: MessageStorageItem.genPrimary(messageId: originId, owner: owner),
            originId: originId,
            stanzaXML: """
            <message type='chat' to='\(opponent)' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            createdAt: createdAt,
            replayRequired: false
        )
    }

    private func storeSendingMessage(owner: String, originId: String) throws {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.owner = owner
        message.opponent = "romeo@example.com"
        message.outgoing = true
        message.messageId = originId
        message.primary = MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        message.conversationType = .regular
        message.displayAs = .text
        message.body = "Hello"
        message.legacyBody = "Hello"
        message.state = .sending
        message.date = Date(timeIntervalSince1970: 1)
        message.sentDate = message.date

        try realm.write {
            realm.add(message, update: .modified)
        }
    }
}

final class AccountStreamLifecycleGateTests: XCTestCase {

    func testDuplicateConnectIsSkippedWhileConnecting() {
        let gate = AccountStreamLifecycleGate()

        let first = gate.beginConnect(trigger: .addExistingAccount)
        let second = gate.beginConnect(trigger: .restore)

        guard case .start(let attemptID) = first else {
            XCTFail("Expected first connect to start")
            return
        }

        XCTAssertEqual(second, .skip(phase: .connecting, activeAttemptID: attemptID))
        XCTAssertEqual(gate.snapshot().phase, .connecting)
        XCTAssertEqual(gate.snapshot().activeAttemptID, attemptID)
    }

    func testTimeoutRetryRequiresActiveConnectingAttempt() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        XCTAssertTrue(gate.canRetryTimeout(for: attemptID))
        XCTAssertFalse(gate.canRetryTimeout(for: attemptID + 1))

        gate.markAuthenticating()

        XCTAssertFalse(gate.canRetryTimeout(for: attemptID))
    }

    func testPostAuthSetupBlocksNewPrimaryConnect() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        gate.markAuthenticating()
        gate.markBinding()
        gate.markPostAuthSetup()

        XCTAssertEqual(
            gate.beginConnect(trigger: .statusUpdate),
            .skip(phase: .postAuthSetup, activeAttemptID: attemptID)
        )
    }

    func testOnlineBlocksRestoreUntilExplicitDisconnect() {
        let gate = AccountStreamLifecycleGate()

        guard case .start = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        gate.markAuthenticating()
        gate.markPostAuthSetup()
        gate.markOnline()

        guard case .skip(phase: .online, activeAttemptID: let onlineAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected online stream to skip restore")
            return
        }

        XCTAssertNotNil(onlineAttemptID)

        gate.markDisconnecting()
        gate.markDisconnected()

        guard case .start(let newAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected restore after disconnect to start")
            return
        }

        XCTAssertNotEqual(onlineAttemptID, newAttemptID)
    }

    func testDisconnectedFrameworkStateClearsBlockedConnectGate() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let firstAttemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected initial connect to start")
            return
        }

        XCTAssertEqual(gate.beginConnect(trigger: .restore), .skip(phase: .connecting, activeAttemptID: firstAttemptID))
        XCTAssertEqual(gate.resetIfBlockedByDisconnectedStream(), .connecting)
        XCTAssertEqual(gate.snapshot().phase, .idle)
        XCTAssertNil(gate.snapshot().activeAttemptID)

        guard case .start(let restoreAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected restore to start after disconnected stream reset")
            return
        }

        XCTAssertNotEqual(firstAttemptID, restoreAttemptID)
    }

    func testDeviceReregisterForceCreatesFreshAttempt() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let firstAttemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        let forced = gate.beginConnect(trigger: .deviceReregister, force: true)

        guard case .start(let forcedAttemptID) = forced else {
            XCTFail("Expected forced device re-register connect to start")
            return
        }

        XCTAssertNotEqual(firstAttemptID, forcedAttemptID)
        XCTAssertEqual(gate.snapshot().phase, .connecting)
        XCTAssertEqual(gate.snapshot().activeAttemptID, forcedAttemptID)
    }

    func testUIActionStreamConnectsAreSerializedBySameGate() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .uiActionOpen) else {
            XCTFail("Expected UI action stream to start")
            return
        }

        XCTAssertEqual(
            gate.beginConnect(trigger: .uiActionPerformRequest),
            .skip(phase: .connecting, activeAttemptID: attemptID)
        )

        gate.markAuthenticating()
        gate.markOnline()

        XCTAssertEqual(
            gate.beginConnect(trigger: .uiActionRestore),
            .skip(phase: .online, activeAttemptID: attemptID)
        )
    }
}

private final class ResetTrackingMessageArchiveManager: MessageArchiveManager {
    private(set) var didResetStateCallCount = 0

    override func didResetState() {
        didResetStateCallCount += 1
        super.didResetState()
    }
}

final class AccountXMPPTaskSchedulerTests: XCTestCase {
    override func setUp() {
        super.setUp()
        MessageArchiveRequestFailurePreparationDispatcher.resetForTests()
        MessageArchiveRequestFailureDispatcher.resetForTests()
    }

    override func tearDown() {
        MessageArchiveRequestFailurePreparationDispatcher.resetForTests()
        MessageArchiveRequestFailureDispatcher.resetForTests()
        super.tearDown()
    }

    func testVisibleChatGateAllowsOnlyInteractiveTasksUntilReleased() {
        var scheduler: AccountXMPPTaskScheduler!
        let gate = AccountInteractiveChatOpenGate { _ in
            scheduler?.interactiveChatOpenGateDidChange()
        }
        scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false,
            interactiveChatOpenGate: { gate.isActive }
        )

        let interactiveStarted = expectation(description: "interactive task starts while chat gate is active")
        let foregroundStarted = expectation(description: "foreground task starts only after chat gate release")
        let backgroundStarted = expectation(description: "background task starts only after chat gate release")
        let idleStarted = expectation(description: "idle task starts only after chat gate release")
        let nonInteractiveStartedEarly = expectation(description: "non-interactive work remains queued")
        nonInteractiveStartedEarly.isInverted = true
        let lock = NSLock()
        var isCheckingEarlyStart = true

        func enqueue(
            _ priority: AccountXMPPTaskScheduler.Priority,
            key: String,
            started: XCTestExpectation
        ) {
            scheduler.enqueue(
                priority: priority,
                resource: .other("visible-chat-gate"),
                deduplicationKey: key
            ) { finish in
                lock.lock()
                let startedEarly = isCheckingEarlyStart && priority != .interactive
                lock.unlock()
                if startedEarly {
                    nonInteractiveStartedEarly.fulfill()
                }
                started.fulfill()
                finish()
            }
        }

        let token = gate.acquire()
        enqueue(.idle, key: "idle", started: idleStarted)
        enqueue(.background, key: "background", started: backgroundStarted)
        enqueue(.foreground, key: "foreground", started: foregroundStarted)
        enqueue(.interactive, key: "interactive", started: interactiveStarted)
        scheduler.resume()

        wait(for: [interactiveStarted], timeout: 1)
        wait(for: [nonInteractiveStartedEarly], timeout: 0.1)

        lock.lock()
        isCheckingEarlyStart = false
        lock.unlock()
        XCTAssertTrue(gate.release(token))

        wait(for: [foregroundStarted, backgroundStarted, idleStarted], timeout: 1)
    }

    func testVisibleChatGateFailSafeIsThirtySeconds() {
        XCTAssertEqual(AccountInteractiveChatOpenGate.maximumAllowedDuration, 30)
    }

    func testInitialListSynchronizationGateQueuesAuxiliaryWorkButAllowsInteractiveArchive() {
        let lock = NSLock()
        var initialSyncInProgress = true
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false,
            initialListSynchronizationInProgress: {
                lock.lock()
                defer { lock.unlock() }
                return initialSyncInProgress
            }
        )
        let interactiveStarted = expectation(
            description: "interactive archive starts during initial list sync"
        )
        let backgroundStarted = expectation(
            description: "background work starts after initial list sync"
        )
        let backgroundStartedEarly = expectation(
            description: "background work stays queued during initial list sync"
        )
        backgroundStartedEarly.isInverted = true
        var checkingEarlyStart = true

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "notifications-backfill"
        ) { finish in
            lock.lock()
            let startedEarly = checkingEarlyStart
            lock.unlock()
            if startedEarly {
                backgroundStartedEarly.fulfill()
            }
            backgroundStarted.fulfill()
            finish()
        }
        scheduler.enqueue(
            priority: .interactive,
            resource: .mamArchive,
            deduplicationKey: "visible-chat"
        ) { finish in
            interactiveStarted.fulfill()
            finish()
        }
        scheduler.resume()

        wait(for: [interactiveStarted], timeout: 1)
        wait(for: [backgroundStartedEarly], timeout: 0.1)
        lock.lock()
        checkingEarlyStart = false
        initialSyncInProgress = false
        lock.unlock()
        scheduler.initialListSynchronizationDidChange()
        wait(for: [backgroundStarted], timeout: 1)
    }

    func testRunsQueuedTasksByPriority() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        var events: [String] = []
        let completed = expectation(description: "all tasks completed")
        completed.expectedFulfillmentCount = 4

        scheduler.enqueue(priority: .idle, resource: .other("test"), deduplicationKey: "idle") { finish in
            events.append("idle")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .background, resource: .other("test"), deduplicationKey: "background") { finish in
            events.append("background")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .foreground, resource: .other("test"), deduplicationKey: "foreground") { finish in
            events.append("foreground")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .interactive, resource: .other("test"), deduplicationKey: "interactive") { finish in
            events.append("interactive")
            completed.fulfill()
            finish()
        }

        scheduler.resume()

        wait(for: [completed], timeout: 1)
        XCTAssertEqual(events, ["interactive", "foreground", "background", "idle"])
    }

    func testPromotesPendingConversationArchiveWithoutReplacingItsWork() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        let completed = expectation(description: "both tasks completed")
        completed.expectedFulfillmentCount = 2
        let eventsLock = NSLock()
        var events: [String] = []

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "conversation.archive.shared"
        ) { finish in
            eventsLock.lock()
            events.append("conversation")
            eventsLock.unlock()
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(
            priority: .foreground,
            resource: .mamArchive,
            deduplicationKey: "other.archive"
        ) { finish in
            eventsLock.lock()
            events.append("other")
            eventsLock.unlock()
            completed.fulfill()
            finish()
        }

        scheduler.promotePendingTask(
            deduplicationKey: "conversation.archive.shared",
            to: .interactive
        )
        scheduler.resume()

        wait(for: [completed], timeout: 1)
        eventsLock.lock()
        let completedEvents = events
        eventsLock.unlock()
        XCTAssertEqual(completedEvents, ["conversation", "other"])
    }

    func testAuthenticatedAccountTaskRemainsQueuedUntilStreamBecomesSendReady() {
        let account = Account(
            jid: "scheduler-readiness@example.com",
            queue: DispatchQueue(label: "AccountXMPPTaskSchedulerTests.readiness")
        )
        let scheduler = AccountXMPPTaskScheduler(
            account: account,
            configuration: .test(defaultCooldown: 0)
        )
        let didNotStartBeforeReadiness = expectation(
            description: "authenticated task remains pending before stream readiness"
        )
        didNotStartBeforeReadiness.isInverted = true
        let startedAfterReadiness = expectation(
            description: "authenticated task starts after readiness transition"
        )
        var isCheckingEarlyStart = true

        scheduler.enqueueAccountTask(
            priority: .interactive,
            resource: .mamArchive,
            deduplicationKey: "interactive-chat-readiness"
        ) { _, _, finish in
            if isCheckingEarlyStart {
                didNotStartBeforeReadiness.fulfill()
            }
            startedAfterReadiness.fulfill()
            finish()
        }

        wait(for: [didNotStartBeforeReadiness], timeout: 0.1)
        isCheckingEarlyStart = false

        account.sendReadiness.markStreamManagementEnabled()
        scheduler.streamReadinessDidChange()

        wait(for: [startedAfterReadiness], timeout: 1)
    }

    func testResetReportsUnavailableForPendingAuthenticatedAccountTask() {
        let account = Account(
            jid: "scheduler-reset-unavailable@example.com",
            queue: DispatchQueue(label: "AccountXMPPTaskSchedulerTests.reset-unavailable")
        )
        let scheduler = AccountXMPPTaskScheduler(
            account: account,
            configuration: .test(defaultCooldown: 0)
        )
        let didNotStart = expectation(description: "pending task must not start")
        didNotStart.isInverted = true
        let unavailable = expectation(
            description: "reset terminalizes pending authenticated task"
        )

        scheduler.enqueueAccountTask(
            priority: .interactive,
            resource: .mamArchive,
            deduplicationKey: "interactive-chat-reset",
            unavailable: {
                unavailable.fulfill()
            }
        ) { _, _, finish in
            didNotStart.fulfill()
            finish()
        }

        scheduler.reset()

        wait(for: [unavailable], timeout: 1)
        wait(for: [didNotStart], timeout: 0.1)
    }

    func testMamArchiveTasksAreMutuallyExclusive() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first MAM task started")
        let secondDidNotStartEarly = expectation(description: "second MAM task did not start early")
        secondDidNotStartEarly.isInverted = true
        let secondStarted = expectation(description: "second MAM task started after first completion")
        var finishFirst: (() -> Void)?
        var isCheckingEarlyStart = true

        scheduler.enqueue(priority: .background, resource: .mamArchive, deduplicationKey: "first") { finish in
            finishFirst = finish
            firstStarted.fulfill()
        }
        scheduler.enqueue(priority: .foreground, resource: .mamArchive, deduplicationKey: "second") { finish in
            if isCheckingEarlyStart {
                secondDidNotStartEarly.fulfill()
            }
            secondStarted.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        wait(for: [secondDidNotStartEarly], timeout: 0.1)
        isCheckingEarlyStart = false
        finishFirst?()
        wait(for: [secondStarted], timeout: 1)
    }

    func testBootstrapSearchMediaAndNotificationsShareOneMamLane() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        let bootstrapStarted = expectation(description: "bootstrap started")
        let searchStarted = expectation(description: "search started")
        let mediaStarted = expectation(description: "media started")
        let notificationsStarted = expectation(description: "notifications started")
        let lock = NSLock()
        var runningCount = 0
        var maximumRunningCount = 0
        var order: [String] = []
        var completions: [String: () -> Void] = [:]

        func enqueue(
            _ label: String,
            priority: AccountXMPPTaskScheduler.Priority,
            expectation: XCTestExpectation
        ) {
            scheduler.enqueue(
                priority: priority,
                resource: .mamArchive,
                deduplicationKey: "archive-consumer.\(label)"
            ) { finish in
                lock.lock()
                runningCount += 1
                maximumRunningCount = max(maximumRunningCount, runningCount)
                order.append(label)
                completions[label] = finish
                lock.unlock()
                expectation.fulfill()
            }
        }

        func finish(_ label: String) {
            lock.lock()
            runningCount -= 1
            let completion = completions.removeValue(forKey: label)
            lock.unlock()
            completion?()
        }

        enqueue("notifications", priority: .idle, expectation: notificationsStarted)
        enqueue("media", priority: .background, expectation: mediaStarted)
        enqueue("search", priority: .foreground, expectation: searchStarted)
        enqueue("bootstrap", priority: .interactive, expectation: bootstrapStarted)
        scheduler.resume()

        wait(for: [bootstrapStarted], timeout: 1)
        finish("bootstrap")
        wait(for: [searchStarted], timeout: 1)
        finish("search")
        wait(for: [mediaStarted], timeout: 1)
        finish("media")
        wait(for: [notificationsStarted], timeout: 1)
        finish("notifications")

        XCTAssertEqual(maximumRunningCount, 1)
        XCTAssertEqual(order, ["bootstrap", "search", "media", "notifications"])
    }

    func testCooldownDelaysNextTaskForSameResource() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0, cooldowns: [.vcard: 0.15])
        )
        let firstStarted = expectation(description: "first vCard task started")
        let secondDidNotStartDuringCooldown = expectation(description: "second vCard task waits for cooldown")
        secondDidNotStartDuringCooldown.isInverted = true
        let secondStarted = expectation(description: "second vCard task started after cooldown")
        var finishFirst: (() -> Void)?
        var isCheckingCooldown = true

        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "first") { finish in
            finishFirst = finish
            firstStarted.fulfill()
        }
        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "second") { finish in
            if isCheckingCooldown {
                secondDidNotStartDuringCooldown.fulfill()
            }
            secondStarted.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        finishFirst?()
        wait(for: [secondDidNotStartDuringCooldown], timeout: 0.05)
        isCheckingCooldown = false
        wait(for: [secondStarted], timeout: 1)
    }

    func testResetClearsPendingTasks() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first task started")
        let pendingDidNotStart = expectation(description: "pending task was cancelled")
        pendingDidNotStart.isInverted = true
