    }

    func testLineContainsCoreConnectionFieldsInStableOrder() {
        let error = NSError(
            domain: "kCFStreamErrorDomainNetDB",
            code: -72000,
            userInfo: [NSLocalizedDescriptionKey: "DNS failed"]
        )

        let line = ConnectionDiagnosticsLogger.line(
            event: "connect start",
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 42,
            trigger: .restore,
            phase: .connecting,
