final class SensitiveMediaAnalysisStartupSchedulerTests: XCTestCase {

    func testProductionStartupScanIsAdmittedByOnlineAccountScheduler() {
        var scanCount = 0
        var scheduledTasks: [SensitiveMediaAnalysisStartupTaskDescriptor] = []
        var scheduledWork: (() -> Void)?
        let scheduler = SensitiveMediaAnalysisStartupScheduler(
            scan: {
                scanCount += 1
            },
            accountScanScheduler: { task, work in
                scheduledTasks.append(task)
                scheduledWork = work
            }
        )

        scheduler.prepareForLaunch()
        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scheduledTasks.map(\.owner), ["alice@example.com"])
        XCTAssertEqual(scheduledTasks.map(\.priority), [.idle])
        XCTAssertEqual(
            scheduledTasks.map(\.resource),
            [.other("sensitiveMediaStartup")]
        )
        XCTAssertEqual(scanCount, 0, "The account scheduler must admit the startup Realm scan")

        scheduledWork?()

        XCTAssertEqual(scanCount, 1)
    }

    func testDisabledPolicyCreatesNoStartupSchedulerTask() {
        var scanCount = 0
        var scheduledTaskCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler(
            scan: {
                scanCount += 1
            },
            isAnalysisEnabled: { false },
            accountScanScheduler: { _, _ in
                scheduledTaskCount += 1
            }
        )

        scheduler.prepareForLaunch()
        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scheduledTaskCount, 0)
        XCTAssertEqual(scanCount, 0)
    }

    func testPrepareForLaunchDefersScanUntilAccountOnline() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.prepareForLaunch()

        XCTAssertEqual(scanCount, 0)

        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 1)
    }

    func testRepeatedOnlineEventsRunDeferredScanOnce() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.prepareForLaunch()
        scheduler.accountDidReachOnline(jid: "alice@example.com")
        scheduler.accountDidReachOnline(jid: "bob@example.com")
        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 1)
    }

    func testPrepareRunsScanWhenAccountIsAlreadyOnline() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 0)

        scheduler.prepareForLaunch()

        XCTAssertEqual(scanCount, 1)
    }
}

final class SensitiveMediaAnalysisAccountTaskSchedulerTests: XCTestCase {

    func testInteractiveGateKeepsRemainingReferencesPendingAndAnalysisHoldsLane() {
        let stateLock = NSLock()
        var gateIsActive = false
        var started: [String] = []
        var analysisCompletions: [String: () -> Void] = [:]
        let accountScheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            interactiveChatOpenGate: {
                stateLock.lock()
                defer { stateLock.unlock() }
                return gateIsActive
            }
        )
        let scheduler = SensitiveMediaAnalysisAccountTaskScheduler(
            resolveOwners: { primaryKeys in
                Dictionary(uniqueKeysWithValues: primaryKeys.map {
                    ($0, "alice@example.com")
                })
            },
            enqueue: { task, work in
                accountScheduler.enqueue(
                    priority: task.priority,
                    resource: task.resource,
                    deduplicationKey: task.deduplicationKey,
                    work: work
                )
            }
        )
        let firstStarted = expectation(description: "first analysis admitted")
        let secondStarted = expectation(description: "second analysis admitted")

        let primaryKeys = (1...33).map {
            String(format: "reference-%02d", $0)
        }
        scheduler.schedule(primaryKeys: primaryKeys) {
            primaryKey, completion in
            stateLock.lock()
            started.append(primaryKey)
            analysisCompletions[primaryKey] = completion
            let startedCount = started.count
            stateLock.unlock()
            if startedCount == 1 {
                firstStarted.fulfill()
            } else if startedCount == 2 {
                secondStarted.fulfill()
            }
        }

        wait(for: [firstStarted], timeout: 1)
        stateLock.lock()
        XCTAssertEqual(started, ["reference-01"])
        gateIsActive = true
        let finishFirstAnalysis = analysisCompletions["reference-01"]
        stateLock.unlock()
        accountScheduler.interactiveChatOpenGateDidChange()
        finishFirstAnalysis?()

        let heldLaneObservation = expectation(description: "held lane observation")
        DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + 0.05) {
            heldLaneObservation.fulfill()
        }
        wait(for: [heldLaneObservation], timeout: 1)
        stateLock.lock()
        XCTAssertEqual(
            started,
            ["reference-01"],
            "Only the already-running analysis may finish while the interactive gate is active"
        )
        gateIsActive = false
        stateLock.unlock()
        accountScheduler.interactiveChatOpenGateDidChange()

        wait(for: [secondStarted], timeout: 1)
        stateLock.lock()
        XCTAssertEqual(started, ["reference-01", "reference-02"])
        gateIsActive = true
        let finishSecondAnalysis = analysisCompletions["reference-02"]
        stateLock.unlock()
        accountScheduler.interactiveChatOpenGateDidChange()
        finishSecondAnalysis?()
        accountScheduler.reset()
    }

    func testDescriptorsAreIdlePerAccountAndDeduplicateOwnerPlusPrimary() {
        var captured: [SensitiveMediaAnalysisAccountTaskDescriptor] = []
        let scheduler = SensitiveMediaAnalysisAccountTaskScheduler(
            resolveOwners: { _ in
                [
                    "reference-1": "alice@example.com",
                    "reference-2": "bob@example.com",
                ]
            },
            enqueue: { task, _ in
                captured.append(task)
            }
        )

        scheduler.schedule(primaryKeys: ["reference-2", "reference-1", "reference-1"]) {
            _, _ in
            XCTFail("Captured work must not execute until its account scheduler admits it")
        }

        XCTAssertEqual(captured.map(\.priority), [.idle, .idle])
        XCTAssertEqual(
            captured.map(\.resource),
            [.other("sensitiveMedia"), .other("sensitiveMedia")]
        )
        XCTAssertEqual(
            captured.map(\.deduplicationKey),
            [
                "sensitiveMedia.alice@example.com.reference-1",
                "sensitiveMedia.bob@example.com.reference-2",
            ]
        )
    }
}

final class PushNotificationHardeningTests: XCTestCase {

    private enum StandardOutputCaptureError: Error {
        case couldNotDuplicateDescriptor
        case couldNotRedirectDescriptor
    }

    private final class PushCapturingXMPPStream: XMPPStream {
        private(set) var sentElements: [DDXMLElement] = []

        override func send(_ element: DDXMLElement) {
            sentElements.append(element)
        }
    }

    private func captureStandardOutput(_ operation: () throws -> Void) throws -> String {
        Darwin.fflush(Darwin.stdout)
        let originalDescriptor = Darwin.dup(STDOUT_FILENO)
        guard originalDescriptor >= 0 else {
            throw StandardOutputCaptureError.couldNotDuplicateDescriptor
        }

        let pipe = Pipe()
        guard Darwin.dup2(pipe.fileHandleForWriting.fileDescriptor, STDOUT_FILENO) >= 0 else {
            Darwin.close(originalDescriptor)
            throw StandardOutputCaptureError.couldNotRedirectDescriptor
        }

        var operationError: Error?
        do {
            try operation()
        } catch {
            operationError = error
        }

        Darwin.fflush(Darwin.stdout)
        _ = Darwin.dup2(originalDescriptor, STDOUT_FILENO)
        Darwin.close(originalDescriptor)
        pipe.fileHandleForWriting.closeFile()

        let output = pipe.fileHandleForReading.readDataToEndOfFile()
        if let operationError {
            throw operationError
        }
        return String(decoding: output, as: UTF8.self)
    }

    private func captureStandardError(_ operation: () throws -> Void) throws -> String {
        Darwin.fflush(Darwin.stderr)
        let originalDescriptor = Darwin.dup(STDERR_FILENO)
        guard originalDescriptor >= 0 else {
            throw StandardOutputCaptureError.couldNotDuplicateDescriptor
        }

        let pipe = Pipe()
        guard Darwin.dup2(pipe.fileHandleForWriting.fileDescriptor, STDERR_FILENO) >= 0 else {
            Darwin.close(originalDescriptor)
            throw StandardOutputCaptureError.couldNotRedirectDescriptor
        }

        var operationError: Error?
        do {
            try operation()
        } catch {
            operationError = error
        }

        Darwin.fflush(Darwin.stderr)
        _ = Darwin.dup2(originalDescriptor, STDERR_FILENO)
        Darwin.close(originalDescriptor)
        pipe.fileHandleForWriting.closeFile()

        let output = pipe.fileHandleForReading.readDataToEndOfFile()
        if let operationError {
            throw operationError
        }
        return String(decoding: output, as: UTF8.self)
    }

    private func makeSensitiveDiagnosticSentinel() -> String {
        "push-sensitive-\(UUID().uuidString)-\(UUID().uuidString)"
    }

    private func makeIQ(xml: String) throws -> XMPPIQ {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        return XMPPIQ(from: try XCTUnwrap(document.rootElement()))
    }

    func testAPNSPayloadDecoderParsesPlainJSONBody() throws {
        let body = """
        {"action":"regjid","result":"success","jid":"romeo@example.com/resource","node":"node-1","service":"push.example.com"}
        """

        let decoded = try APNSManager.decodeNodeData(from: body)

        XCTAssertEqual(decoded.action, "regjid")
        XCTAssertEqual(decoded.node, "node-1")
        XCTAssertEqual(decoded.service, "push.example.com")
    }

    func testAPNSPayloadDecoderParsesBase64JSONBody() throws {
        let json = """
        {"action":"displayed","encrypted":"payload"}
        """
        let encoded = Data(json.utf8).base64EncodedString()

        let decoded = try APNSManager.decodeNodeData(from: encoded)

        XCTAssertEqual(decoded.action, "displayed")
        XCTAssertEqual(decoded.encrypted, "payload")
    }

    func testAPNSPayloadDecoderRejectsMalformedBody() {
        XCTAssertThrowsError(try APNSManager.decodeNodeData(from: "not-json"))
    }

    func testAPNSRegistrationEligibilityUsesChannelSpecificTokens() {
        let manager = APNSManager.shared
        let previousDeviceToken = manager.deviceToken
        let previousVoIPToken = manager.voipToken

        manager.deviceToken = "device-token"
        manager.voipToken = nil
        XCTAssertTrue(manager.canSendRegistrationRequest(voip: false))
        XCTAssertFalse(manager.canSendRegistrationRequest(voip: true))

        manager.deviceToken = nil
        manager.voipToken = "voip-token"
        XCTAssertFalse(manager.canSendRegistrationRequest(voip: false))
        XCTAssertTrue(manager.canSendRegistrationRequest(voip: true))

        manager.deviceToken = previousDeviceToken
        manager.voipToken = previousVoIPToken
    }

    func testRemoteNotificationProcessingCompletesOnSuccessOnce() {
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, completion in
                completion?()
                completion?()
                return .displayed
            },
            cleanupHandler: {},
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertEqual(outcome, .push(.displayed))
        XCTAssertEqual(completionResults, [.newData])
    }

    func testRemoteNotificationProcessingCompletesOnInvalidPayload() {
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, _ in throw APNSManager.APNSError.invalidPayload },
            cleanupHandler: {},
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertEqual(outcome, .noData)
        XCTAssertEqual(completionResults, [.noData])
    }

    func testRemoteNotificationProcessingCleansUpUnknownUserAndCompletes() {
        var didCleanup = false
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, _ in throw APNSManager.APNSError.userNotExist },
            cleanupHandler: { didCleanup = true },
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertTrue(didCleanup)
        XCTAssertEqual(outcome, .noData)
        XCTAssertEqual(completionResults, [.noData])
    }

    func testPushConfigureDoesNotWritePersistedSecretToStandardOutput() throws {
        let node = "push-node-\(UUID().uuidString)"
        let owner = "privacy@example.invalid"
        let sentinel = makeSensitiveDiagnosticSentinel()
        let defaults = try XCTUnwrap(
            UserDefaults(suiteName: CredentialsManager.uniqueAccessGroup())
        )
        defaults.set(
            [
                "secret": sentinel,
                "username": "privacy-user"
            ],
            forKey: node
        )
        defer {
            PushNotificationsManager.removeDefaultsForPush(target: node, jid: owner)
        }

        let manager = PushNotificationsManager(withOwner: owner)
        let output = try captureStandardOutput {
            manager.configure(node: node, service: "push.example.invalid")
        }

        XCTAssertEqual(manager.node, node)
        XCTAssertEqual(manager.service, "push.example.invalid")
        XCTAssertFalse(
            output.contains(sentinel),
            "Push configure diagnostics must not expose a persisted secret"
        )
        XCTAssertFalse(
            output.contains("PUSH DEFAULTS"),
            "Push configure diagnostics must not expose the defaults dictionary"
        )
    }

    func testPushEnablePreservesEncryptionKeyWithoutWritingGeneratedSecretToStandardOutput() throws {
        let owner = "privacy@example.invalid"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "push.example.invalid"

        let stream = PushCapturingXMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")
        var callbackResults: [Bool] = []
        defer {
            CredentialsManager.shared.removePushCredentials(for: node)
            PushNotificationsManager.removeDefaultsForPush(target: node, jid: owner)
        }

        let output = try captureStandardOutput {
            manager.enable(xmppStream: stream) { callbackResults.append($0) }
        }

        let credentials = try CredentialsManager.shared.getPushCredentials(for: node)
        let sentIQ = try XCTUnwrap(stream.sentElements.first)
        let sentKey = try XCTUnwrap(
            sentIQ.element(forName: "enable")?
                .element(forName: "security")?
                .element(forName: "encryption-key")?
                .stringValue
        )

        XCTAssertEqual(sentKey, credentials.secret.toBase64())
        XCTAssertEqual(
            PushNotificationsManager.getDefaultsForPush(for: node)["secret"],
            credentials.secret
        )
        XCTAssertEqual(manager.enableState, .pending(queryId: try XCTUnwrap(manager.queryIds.first)))
        XCTAssertTrue(callbackResults.isEmpty)
        XCTAssertFalse(
            output.contains(credentials.secret),
            "Push enable diagnostics must not expose the generated secret"
        )
        XCTAssertFalse(
            output.contains(credentials.secret.toBase64()),
            "Push enable diagnostics must not expose the encoded encryption key"
        )
        XCTAssertFalse(
            output.contains("secret key:") || output.contains("set user defaults for secret"),
            "Push enable diagnostics must not expose secret-bearing labels"
        )
    }

    func testPushSecretDefaultsUpdatePersistsValueWithoutWritingItToStandardOutput() throws {
        let node = "push-node-\(UUID().uuidString)"
        let owner = "privacy@example.invalid"
        let sentinel = makeSensitiveDiagnosticSentinel()
        defer {
            PushNotificationsManager.removeDefaultsForPush(target: node, jid: owner)
        }

        let output = try captureStandardOutput {
            PushNotificationsManager.updateDefaultsForPush(
                node,
                key: "secret",
                value: sentinel
            )
        }

        XCTAssertEqual(
            PushNotificationsManager.getDefaultsForPush(for: node)["secret"],
            sentinel
        )
        XCTAssertFalse(
            output.contains(sentinel),
            "Push defaults diagnostics must not expose the stored secret"
        )
        XCTAssertFalse(
            output.contains("dict") || output.contains("set user defaults for secret"),
            "Push defaults diagnostics must not expose a complete dictionary or secret field"
        )
    }

    func testPushCredentialStoreRoundTripsWithoutWritingRawIdentityToStandardError() throws {
        let node = "push-node-\(UUID().uuidString)-\(UUID().uuidString)"
        let username = "push-user-\(UUID().uuidString)"
        let jid = "\(username)@identity.example.invalid"
        let host = "push-host-\(UUID().uuidString).example.invalid"
        let secret = makeSensitiveDiagnosticSentinel()
        let service = "https://push-\(UUID().uuidString).example.invalid"
        let jwt = "push-jwt-\(UUID().uuidString)-\(UUID().uuidString)"
        defer {
            CredentialsManager.shared.removePushCredentials(for: node)
        }

        let output = try captureStandardError {
            try CredentialsManager.shared.storePushCredentials(
                node: node,
                jid: jid,
                host: host,
                secret: secret,
                service: service,
                jwt: jwt
            )
        }

        let stored = try CredentialsManager.shared.getPushCredentials(for: node)
        XCTAssertTrue(stored.jid == jid, "Stored push JID must round-trip")
        XCTAssertTrue(stored.host == host, "Stored push host must round-trip")
        XCTAssertTrue(stored.secret == secret, "Stored push secret must round-trip")
        XCTAssertTrue(stored.service == service, "Stored push service must round-trip")
        XCTAssertTrue(stored.jwt == jwt, "Stored push JWT must round-trip")

        XCTAssertFalse(
            output.contains(node) || output.contains(Data(node.utf8).base64EncodedString()),
            "Push credential diagnostics must not expose the node identity"
        )
        XCTAssertFalse(
            output.contains(username)
                || output.contains(jid)
                || output.contains(Data(jid.utf8).base64EncodedString()),
            "Push credential diagnostics must not expose the account identity"
        )
        XCTAssertFalse(
            [host, secret, service, jwt].contains(where: output.contains),
            "Push credential diagnostics must not expose stored credential fields"
        )
    }

    func testPushEnableStaysPendingUntilIQResultArrives() {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        XCTAssertEqual(manager.enableState, .pending(queryId: queryId))
        XCTAssertTrue(callbackResults.isEmpty)

        CredentialsManager.shared.removePushCredentials(for: node)
    }

    func testPushEnableBecomesEnabledAfterSuccessfulIQResult() throws {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <x xmlns='jabber:x:data'>
            <field var='url'><value>https://push.example.com</value></field>
            <field var='jwt'><value>jwt-token</value></field>
          </x>
        </iq>
        """)

        XCTAssertTrue(manager.read(withIQ: iq))
        XCTAssertEqual(manager.enableState, .enabled)
        XCTAssertEqual(callbackResults, [true])
        XCTAssertFalse(manager.queryIds.contains(queryId))

        let credentials = try CredentialsManager.shared.getPushCredentials(for: node)
        XCTAssertEqual(credentials.service, "https://push.example.com")
        XCTAssertEqual(credentials.jwt, "jwt-token")

        CredentialsManager.shared.removePushCredentials(for: node)
    }

    func testPushEnableResetsToDisabledAfterIncompleteIQResult() throws {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <x xmlns='jabber:x:data'>
            <field var='url'><value>https://push.example.com</value></field>
          </x>
        </iq>
        """)

        XCTAssertTrue(manager.read(withIQ: iq))
        XCTAssertEqual(manager.enableState, .disabled)
        XCTAssertEqual(callbackResults, [false])
        XCTAssertFalse(manager.queryIds.contains(queryId))

        CredentialsManager.shared.removePushCredentials(for: node)
    }
}

final class NotificationsFeatureTests: XCTestCase {

    private let owner = "igor.boldin@xmppdev01.xabber.com"
    private let notificationsNode = "notifications.xmppdev01.xabber.com"
    private let groupchatJid = "trio@example.com"
    private let groupchatAuthorJid = "romeo@xmppdev01.xabber.com"
    private let currentMemberId = "me-1"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "NotificationsFeatureTests-\(name)")
        AccountManager.shared.users.removeAll { $0.jid == owner }
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        AccountManager.shared.users.removeAll { $0.jid == owner }
        super.tearDown()
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "NotificationsFeatureTests", code: 1)
        }
        return XMPPMessage(from: root)
    }

    private func makeIQ(xml: String) throws -> XMPPIQ {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "NotificationsFeatureTests", code: 2)
        }
        return XMPPIQ(from: root)
    }

    private func makeAccount() -> Account {
        AccountManager.shared.users.removeAll { $0.jid == owner }
        let account = Account(jid: owner, queue: .main)
        account.sendReadiness.markStreamManagementEnabled()
        AccountManager.shared.users.append(account)
        return account
    }

    private func upsertNotificationManagerStorage(
        node: String,
        archiveSyncCompleted: Bool = false,
        lastSyncedNotificationId: String? = nil,
        lastItemId: String? = nil,
        unread: Int = 0,
        unreadAfterId: String? = nil
    ) throws {
        let realm = try WRealm.safe()
        let storage = XMPPNotificationsManagerStorageItem()
        storage.owner = owner
        storage.primary = XMPPNotificationsManagerStorageItem.genPrimary(owner: owner)
        storage.node = node
        storage.archiveSyncCompleted = archiveSyncCompleted
        storage.lastSyncedNotificationId = lastSyncedNotificationId
        storage.lastItemId = lastItemId
        storage.unread = unread
        storage.unreadAfterId = unreadAfterId

        try realm.write {
            realm.add(storage, update: .modified)
        }
    }

    @discardableResult
    private func insertNotification(
        jid: String = "security@xmppdev01.xabber.com",
        uniqueId: String,
        stanzaId: String?,
        date: String
    ) throws -> NotificationStorageItem {
        let realm = try WRealm.safe()
        let notification = NotificationStorageItem()
        notification.primary = NotificationStorageItem.genPrimary(owner: owner, jid: jid, uniqueId: uniqueId)
        notification.owner = owner
        notification.jid = jid
        notification.uniqueId = uniqueId
        notification.messageId = uniqueId
        notification.stanzaId = stanzaId ?? ""
        notification.category = .info
        notification.shouldShow = true
        notification.date = ISO8601DateFormatter().date(from: date)!

        try realm.write {
            realm.add(notification, update: .modified)
        }

        return notification
    }

    private func queuedNotificationRequest(on account: Account) -> MessageArchiveManager.CallbackQueueItem? {
        account.mam.firstCallbackQueueItem {
            $0.task.conversationType == .notifications
        }
    }

    private func waitForQueuedNotificationRequest(
        on account: Account,
        timeout: TimeInterval = 3.0,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws -> MessageArchiveManager.CallbackQueueItem {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if let queued = queuedNotificationRequest(on: account) {
                return queued
            }
            RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.01))
        }

        return try XCTUnwrap(
            queuedNotificationRequest(on: account),
            "Expected queued notification archive request",
            file: file,
            line: line
        )
    }

    private func sendArchiveFin(
        on account: Account,
        queryId: String,
        complete: Bool,
        count: Int,
        deliveredCount: Int? = nil,
        first: String,
        last: String
    ) throws {
        // RSM <count> describes the whole server result set. Record the
        // independently supplied page delivery count so exhaustion is derived
        // from transport evidence, just as it is in production.
        for index in 0..<(deliveredCount ?? count) {
            let result = try makeMessage(xml: """
            <message>
              <result xmlns='urn:xmpp:mam:2' queryid='\(queryId)' id='fixture-result-\(index)'/>
            </message>
            """)
            XCTAssertTrue(account.mam.recordDeferredArchiveResultDelivery(result))
            XCTAssertTrue(account.mam.recordDeferredArchiveControlConsumption(result))
        }

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <fin xmlns='urn:xmpp:mam:2' complete='\(complete ? "true" : "false")' queryid='\(queryId)'>
            <set xmlns='http://jabber.org/protocol/rsm'>
              <count>\(count)</count>
              <first>\(first)</first>
              <last>\(last)</last>
            </set>
          </fin>
        </iq>
        """)

        XCTAssertTrue(account.mam.read(account.xmppStream, withIQ: iq))
    }

    private func sendArchiveError(on account: Account, queryId: String) throws {
        let iq = try makeIQ(xml: """
        <iq type='error' id='\(queryId)'>
          <error type='cancel'>
            <service-unavailable xmlns='urn:ietf:params:xml:ns:xmpp-stanzas'/>
          </error>
        </iq>
        """)

        XCTAssertTrue(account.mam.read(account.xmppStream, withIQ: iq))
    }

    private func managerStorage() throws -> XMPPNotificationsManagerStorageItem? {
        try WRealm.safe().object(ofType: XMPPNotificationsManagerStorageItem.self, forPrimaryKey: XMPPNotificationsManagerStorageItem.genPrimary(owner: owner))
    }

    private func waitUntil(
        timeout: TimeInterval = 2,
        pollInterval: TimeInterval = 0.02,
        condition: @escaping () -> Bool
    ) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if condition() {
                return true
            }
            RunLoop.current.run(until: Date().addingTimeInterval(pollInterval))
        }
        return condition()
    }

    private func waitForNotificationPersistence(_ manager: XMPPNotificationsManager) {
        let persisted = expectation(description: "Notification persistence drained")
        manager.flushPendingNotificationPersistenceForTests { didPersist in
            XCTAssertTrue(didPersist)
            persisted.fulfill()
        }
        wait(for: [persisted], timeout: 2)
        _ = try? WRealm.safe().refresh()
    }

