    }

    func testMessageCallbackFiresOnlyForMatchingQuery() throws {
        let manager = MessageArchiveManager(withOwner: owner)
        let stream = XMPPStream()
        var received: [String] = []
        let callbackExpectation = expectation(description: "matching message callback")

        let matchingQuery = "engine-search-matching"
        manager.requestArchive(
            stream,
            jid: "romeo@example.com",
            isContinues: false,
            conversationType: .regular,
            purpose: .engineSearchPage,
            queryId: matchingQuery,
            searchText: "hello",
            flipPage: false,
            max: 20,
            requestCallbacks: .init(
                onMessage: { item, _ in
                    received.append(item.archivedId)
                    callbackExpectation.fulfill()
                },
                onEndPage: nil
            )
        )
        manager.requestArchive(
            stream,
            jid: "romeo@example.com",
            isContinues: false,
            conversationType: .regular,
            purpose: .engineSearchPage,
            queryId: "engine-search-nonmatching",
            searchText: "hello",
            flipPage: false,
            max: 20,
            requestCallbacks: .init(
                onMessage: { item, _ in
                    received.append("unexpected-\(item.archivedId)")
                },
                onEndPage: nil
            )
        )

        let message = try makeMessage(xml: """
        <message to='\(owner)' from='\(owner)'>
          <result xmlns='urn:xmpp:mam:2' queryid='\(matchingQuery)'>
            <forwarded xmlns='urn:xmpp:forward:0'>
              <message xmlns='jabber:client' to='\(owner)' from='romeo@example.com' type='chat' id='message-1'>
                <archived xmlns='urn:xmpp:mam:tmp' by='\(owner)' id='archived-1'/>
                <stanza-id xmlns='urn:xmpp:sid:0' by='\(owner)' id='archived-1'/>
                <time xmlns='https://xabber.com/protocol/delivery' by='\(owner)' stamp='2026-03-31T10:00:00Z'/>
                <origin-id xmlns='urn:xmpp:sid:0' id='message-1'/>
                <body>Hello</body>
              </message>
              <delay xmlns='urn:xmpp:delay' from='example.com' stamp='2026-03-31T10:00:00Z'/>
            </forwarded>
          </result>
        </message>
        """)

        XCTAssertTrue(manager.readMessage(message))
        wait(for: [callbackExpectation], timeout: 1.0)
        XCTAssertEqual(received, ["archived-1"])
    }

}

final class MessageArchiveCallbackQueueThreadSafetyTests: XCTestCase {

    private func makeQueueItem(index: Int, queryId: String) -> MessageArchiveManager.CallbackQueueItem {
        let task = MessageArchiveManager.MAMRequestItem(
            jid: "romeo@example.com",
            messageId: nil,
            conversationType: .regular,
            isContinues: false,
            searchText: nil,
            queryId: queryId,
            afterId: nil,
            nextPage: nil,
            prevPage: nil,
            max: 50,
            tags: [],
            start: nil,
            end: nil,
            purpose: .pageOlder,
            retainsSealedTransportProofUntilBarrier: false
        )

        return MessageArchiveManager.CallbackQueueItem(
            jid: "romeo@example.com",
            elementId: queryId,
            task: task,
            callback: nil,
            requestCallbacks: .none
        )
    }

    func testConcurrentCallbackQueueRegistrationLookupAndRemovalDoesNotRaceSetStorage() {
        let manager = MessageArchiveManager(withOwner: "owner@example.com")
        let queue = DispatchQueue(label: "MessageArchiveCallbackQueueThreadSafetyTests", attributes: .concurrent)
        let group = DispatchGroup()

        for index in 0..<500 {
            group.enter()
            queue.async {
                let queryId = "MAM page older: thread-safe-\(index % 64)"
                let item = self.makeQueueItem(index: index, queryId: queryId)

                manager.upsertCallbackQueueItem(item)
                _ = manager.callbackQueueContains { $0.elementId == queryId }
                if let existing = manager.firstCallbackQueueItem(where: { $0.elementId == queryId }) {
                    manager.removeCallbackQueueItem(existing)
                }

                group.leave()
            }
        }

        XCTAssertEqual(group.wait(timeout: .now() + 5), .success)
        XCTAssertLessThanOrEqual(manager.callbackQueueItems(where: { _ in true }).count, 64)
    }
}

final class LastChatUnreadCounterTests: XCTestCase {

    private let owner = "owner@example.com"
    private let jid = "romeo@example.com"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "LastChatUnreadCounterTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    @discardableResult
    private func insertChat() throws -> LastChatsStorageItem {
        let realm = try WRealm.safe()
        let chat = LastChatsStorageItem()
        chat.owner = owner
        chat.jid = jid
        chat.conversationType = .regular
        chat.primary = LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: .regular)
        chat.messageDate = Date(timeIntervalSince1970: 1_711_283_200)

        try realm.write {
            realm.add(chat, update: .modified)
        }

        return try XCTUnwrap(realm.object(ofType: LastChatsStorageItem.self, forPrimaryKey: chat.primary))
    }

    private func makeMessage(
        primary: String,
        archivedId: String,
        date: TimeInterval,
        outgoing: Bool = false,
        isRead: Bool = false,
        countsAsRuntimeUnread: Bool = false
    ) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = primary
        message.owner = owner
        message.opponent = jid
        message.conversationType = .regular
        message.body = "hello"
        message.legacyBody = "hello"
        message.displayAs = .text
        message.messageId = primary
        message.archivedId = archivedId
        message.date = Date(timeIntervalSince1970: date)
        message.sentDate = message.date
        message.outgoing = outgoing
        message.isRead = isRead
        message.state = outgoing ? .sended : .deliver
        message.countsAsRuntimeUnread = countsAsRuntimeUnread
        return message
    }

    private func chat() throws -> LastChatsStorageItem {
        try XCTUnwrap(
            try WRealm.safe().object(
                ofType: LastChatsStorageItem.self,
                forPrimaryKey: LastChatsStorageItem.genPrimary(jid: jid, owner: owner, conversationType: .regular)
            )
        )
    }

    private func seedSavedVisiblePosition(on chat: LastChatsStorageItem) {
        chat.lastVisibleMessagePrimary = "saved-primary"
        chat.lastVisibleMessageArchivedId = "saved-archived"
        chat.lastVisibleMessageId = "saved-message"
        chat.lastVisibleMessageDate = Date(timeIntervalSince1970: 1_711_283_100)
        chat.lastVisiblePositionSavedAtLastMessageId = chat.lastMessageId
        chat.lastVisiblePositionSavedAtSnapshotLastArchiveId = chat.syncSnapshotLastArchiveId
        chat.lastVisiblePositionUpdatedAt = Date(timeIntervalSince1970: 1_711_283_101)
    }

    private func assertSavedVisiblePositionCleared(
        _ chat: LastChatsStorageItem,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertNil(chat.lastVisibleMessagePrimary, file: file, line: line)
        XCTAssertNil(chat.lastVisibleMessageArchivedId, file: file, line: line)
        XCTAssertNil(chat.lastVisibleMessageId, file: file, line: line)
        XCTAssertNil(chat.lastVisibleMessageDate, file: file, line: line)
    }

    private func assertSavedVisiblePositionPreserved(
        _ chat: LastChatsStorageItem,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(chat.lastVisibleMessagePrimary, "saved-primary", file: file, line: line)
        XCTAssertEqual(chat.lastVisibleMessageArchivedId, "saved-archived", file: file, line: line)
        XCTAssertEqual(chat.lastVisibleMessageId, "saved-message", file: file, line: line)
        XCTAssertEqual(chat.lastVisibleMessageDate, Date(timeIntervalSince1970: 1_711_283_100), file: file, line: line)
    }

    func testSnapshotUnreadCountDoesNotRecountLocalMessages() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let localOne = makeMessage(primary: "local-1", archivedId: "501", date: 1_711_283_201)
        let localTwo = makeMessage(primary: "local-2", archivedId: "502", date: 1_711_283_202)

        try realm.write {
            realm.add([localOne, localTwo], update: .modified)
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
        }

        XCTAssertEqual(chat.syncUnreadCount, 102)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 102)
        XCTAssertEqual(chat.syncUnreadAfterId, "100")
        XCTAssertEqual(chat.lastReadId, "100")
    }

    func testLiveIncomingAfterSnapshotIncrementsRuntimeTotal() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let message = makeMessage(primary: "live-1", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            _ = message.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        XCTAssertEqual(chat.syncUnreadCount, 102)
        XCTAssertEqual(chat.runtimeUnreadCount, 1)
        XCTAssertEqual(chat.unread, 103)
        XCTAssertEqual(message.unreadCounterBucket, .runtime)
    }

    func testArchiveReplayDoesNotIncrementRuntimeUnread() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let message = makeMessage(primary: "archive-1", archivedId: "600", date: 1_711_283_203, isRead: true)

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            _ = message.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 102)
        XCTAssertEqual(message.unreadCounterBucket, .none)
    }

    func testIncomingNewestMessageClearsSavedVisiblePosition() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let incoming = makeMessage(primary: "incoming-newest", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)

        try realm.write {
            seedSavedVisiblePosition(on: chat)
            _ = incoming.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        assertSavedVisiblePositionCleared(chat)
    }

    func testOutgoingNewestMessageClearsSavedVisiblePositionAndUnreadCounters() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let live = makeMessage(primary: "live-1", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)
        let outgoing = makeMessage(primary: "outgoing-newest", archivedId: "601", date: 1_711_283_204, outgoing: true, isRead: true)

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 2,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            seedSavedVisiblePosition(on: chat)
            _ = live.applyMessagePersistence(in: realm, silentNotifications: true)
            seedSavedVisiblePosition(on: chat)
            _ = outgoing.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        assertSavedVisiblePositionCleared(chat)
        XCTAssertEqual(chat.syncUnreadCount, 0)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 0)
        XCTAssertEqual(live.unreadCounterBucket, .none)
    }

    func testOlderReplayMessageDoesNotClearSavedVisiblePosition() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let newest = makeMessage(primary: "newest", archivedId: "700", date: 1_711_283_300)
        let olderReplay = makeMessage(primary: "older-replay", archivedId: "600", date: 1_711_283_203, isRead: true)

        try realm.write {
            realm.add(newest, update: .modified)
            chat.lastMessage = newest
            chat.lastMessageId = newest.messageId
            chat.messageDate = newest.sentDate
            seedSavedVisiblePosition(on: chat)
            _ = olderReplay.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        assertSavedVisiblePositionPreserved(chat)
    }

    func testDuplicateLiveAndArchiveReplayDoNotDoubleCount() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let live = makeMessage(primary: "dup-1", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)
        let duplicateLive = makeMessage(primary: "dup-1", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)
        let archiveReplay = makeMessage(primary: "dup-1", archivedId: "600", date: 1_711_283_203, isRead: true)

        try realm.write {
            _ = live.applyMessagePersistence(in: realm, silentNotifications: true)
            _ = duplicateLive.applyMessagePersistence(in: realm, silentNotifications: true)
            _ = archiveReplay.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        XCTAssertEqual(chat.runtimeUnreadCount, 1)
        XCTAssertEqual(chat.unread, 1)
        XCTAssertEqual(try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: "dup-1")).unreadCounterBucket, .runtime)
    }

    func testOutgoingMessageClearsSnapshotAndRuntimeCounters() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let live = makeMessage(primary: "live-1", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)
        let outgoing = makeMessage(primary: "outgoing-1", archivedId: "601", date: 1_711_283_204, outgoing: true, isRead: true)

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            _ = live.applyMessagePersistence(in: realm, silentNotifications: true)
            _ = outgoing.applyMessagePersistence(in: realm, silentNotifications: true)
        }

        XCTAssertEqual(chat.syncUnreadCount, 0)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 0)
        XCTAssertEqual(live.unreadCounterBucket, .none)
    }

    func testReadMarkerDoesNotRecountLocalGapMessages() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let localGapMessage = makeMessage(primary: "gap-local", archivedId: "250", date: 1_711_283_203)

        try realm.write {
            realm.add(localGapMessage, update: .modified)
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            LastChatUnreadCounter.markRead(through: localGapMessage, in: chat, clearWholeDialog: false, realm: realm)
        }

        XCTAssertEqual(chat.syncUnreadCount, 102)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 102)
    }

    func testExplicitReadMarkerClearsWithoutLocalRecount() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let lastMessage = makeMessage(primary: "last", archivedId: "600", date: 1_711_283_204)

        try realm.write {
            realm.add(lastMessage, update: .modified)
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 102,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            LastChatUnreadCounter.markRead(through: lastMessage, in: chat, clearWholeDialog: true, realm: realm)
        }

        XCTAssertEqual(chat.syncUnreadCount, 0)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 0)
        XCTAssertEqual(chat.lastReadId, "600")
    }

    func testUnresolvedSiblingDisplayedMarkerLeavesCountersUnchanged() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 4,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            LastChatUnreadCounter.ignoreUnresolvedDisplayedMarker(on: chat)
        }

        XCTAssertEqual(chat.syncUnreadCount, 4)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 4)
        XCTAssertEqual(chat.lastReadId, "100")
    }

    func testDeletingRuntimeUnreadMessageDecrementsOnce() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let message = makeMessage(primary: "delete-runtime", archivedId: "600", date: 1_711_283_203, countsAsRuntimeUnread: true)

        try realm.write {
            _ = message.applyMessagePersistence(in: realm, silentNotifications: true)
            LastChatUnreadCounter.removeUnreadContribution(for: message, from: chat)
            LastChatUnreadCounter.removeUnreadContribution(for: message, from: chat)
        }

        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 0)
        XCTAssertEqual(message.unreadCounterBucket, .none)
    }

    func testDeletingReadOrArchiveReplayMessageDoesNotDecrement() throws {
        let chat = try insertChat()
        let realm = try WRealm.safe()
        let archiveMessage = makeMessage(primary: "archive-read", archivedId: "600", date: 1_711_283_203, isRead: true)

        try realm.write {
            LastChatUnreadCounter.applySynchronizationSnapshot(
                to: chat,
                count: 5,
                afterId: "100",
                snapshotLastArchiveId: "500",
                in: realm
            )
            _ = archiveMessage.applyMessagePersistence(in: realm, silentNotifications: true)
            LastChatUnreadCounter.removeUnreadContribution(for: archiveMessage, from: chat)
        }

        XCTAssertEqual(chat.syncUnreadCount, 5)
        XCTAssertEqual(chat.runtimeUnreadCount, 0)
        XCTAssertEqual(chat.unread, 5)
    }
}

