final class ChatLocalHistoryPageProviderTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!
    private let owner = "owner@example.com"
    private let jid = "romeo@example.com"

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "ChatLocalHistoryPageProviderTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    private func provider() throws -> ChatLocalHistoryPageProvider {
        ChatLocalHistoryPageProvider(
            realm: try WRealm.safe(),
            owner: owner,
            jid: jid,
            conversationType: .regular
        )
    }

    private func insertMessages(_ specs: [(primary: String, archivedId: String, timestamp: TimeInterval)]) throws {
        let realm = try WRealm.safe()
        try realm.write {
            specs.forEach { spec in
                let message = MessageStorageItem()
                message.primary = spec.primary
                message.owner = owner
                message.opponent = jid
                message.conversationType = .regular
                message.archivedId = spec.archivedId
                message.messageId = "message-\(spec.primary)"
                message.date = Date(timeIntervalSince1970: spec.timestamp)
                message.sentDate = message.date
                message.body = spec.primary
                realm.add(message, update: .modified)
            }
        }
    }

    func testLatestReturnsBoundedNewestPageInChronologicalOrder() throws {
        try insertMessages((0..<10).map {
            (primary: "p\($0)", archivedId: "\($0)", timestamp: TimeInterval($0))
        })

        let items = try provider().latest(limit: 3)

        XCTAssertEqual(items.map(\.primary), ["p7", "p8", "p9"])
    }

    func testOlderBeforeBoundaryUsesDateAndPrimaryCursor() throws {
        try insertMessages([
            (primary: "p1", archivedId: "1", timestamp: 100),
            (primary: "p2", archivedId: "2", timestamp: 200),
            (primary: "p3", archivedId: "3", timestamp: 200),
            (primary: "p4", archivedId: "4", timestamp: 300)
        ])
        let boundary = ChatTimelineBoundary(
            primary: "p3",
            archivedId: "3",
            messageId: "message-p3",
            date: Date(timeIntervalSince1970: 200)
        )

        let items = try provider().older(before: boundary, limit: 10)

        XCTAssertEqual(items.map(\.primary), ["p1", "p2"])
    }

    func testNewerAfterBoundaryUsesDateAndPrimaryCursor() throws {
        try insertMessages([
            (primary: "p1", archivedId: "1", timestamp: 100),
            (primary: "p2", archivedId: "2", timestamp: 200),
            (primary: "p3", archivedId: "3", timestamp: 200),
            (primary: "p4", archivedId: "4", timestamp: 300)
        ])
        let boundary = ChatTimelineBoundary(
            primary: "p2",
            archivedId: "2",
            messageId: "message-p2",
            date: Date(timeIntervalSince1970: 200)
        )

        let items = try provider().newer(after: boundary, limit: 10)

        XCTAssertEqual(items.map(\.primary), ["p3", "p4"])
    }

    func testAroundAnchorReturnsBoundedContextWithAnchor() throws {
        try insertMessages((0..<10).map {
            (primary: "p\($0)", archivedId: "\($0)", timestamp: TimeInterval($0))
        })
        let realm = try WRealm.safe()
        let anchor = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: "p5"))

        let items = try provider().around(anchor: anchor, before: 2, after: 2)

        XCTAssertEqual(items.map(\.primary), ["p3", "p4", "p5", "p6", "p7"])
    }

    func testMessageLookupResolvesScopedAnchorWithoutObserverMap() throws {
        try insertMessages([
            (primary: "p1", archivedId: "a1", timestamp: 100),
            (primary: "p2", archivedId: "a2", timestamp: 200)
        ])

        XCTAssertEqual(
            try provider().message(primary: nil, archivedId: "a2", messageId: nil)?.primary,
            "p2"
        )
        XCTAssertEqual(
            try provider().message(primary: nil, archivedId: nil, messageId: "message-p1")?.primary,
            "p1"
        )
    }

    func testResolvedMessageUsesCompoundCursorForAdjacentPages() throws {
        try insertMessages([
            (primary: "p1", archivedId: "1", timestamp: 100),
            (primary: "p2", archivedId: "2", timestamp: 200),
            (primary: "p3", archivedId: "3", timestamp: 200),
            (primary: "p4", archivedId: "4", timestamp: 300)
        ])
        let message = try XCTUnwrap(try provider().message(primary: "p3", archivedId: nil, messageId: nil))

        let provider = try provider()
        let boundary = ChatTimelineBoundary(message: message)

        XCTAssertEqual(provider.older(before: boundary, limit: 2).map(\.primary), ["p1", "p2"])
        XCTAssertEqual(provider.newer(after: boundary, limit: 2).map(\.primary), ["p4"])
    }
}

final class ChatBoundedTimelineWindowPolicyTests: XCTestCase {
    func testOlderTrimDropsNewestItemsPastHardLimit() {
        let items = Array(0..<700)

        XCTAssertEqual(
            ChatBoundedTimelineWindowPolicy.trimmedItems(
                items,
                direction: .older,
                pageSize: 100
            ),
            Array(0..<600)
        )
    }

    func testNewerTrimDropsOldestItemsPastHardLimit() {
        let items = Array(0..<700)

        XCTAssertEqual(
            ChatBoundedTimelineWindowPolicy.trimmedItems(
                items,
                direction: .newer,
                pageSize: 100
            ),
            Array(100..<700)
        )
    }

    func testInitialTrimKeepsNewestTargetWindow() {
        let items = Array(0..<700)

        XCTAssertEqual(
            ChatBoundedTimelineWindowPolicy.trimmedItems(
                items,
                direction: nil,
                pageSize: 100
            ),
            Array(200..<700)
        )
    }

    func testMillionItemTrimKeepsOutputBounded() {
        let items = Array(0..<1_000_000)
        let trimmed = ChatBoundedTimelineWindowPolicy.trimmedItems(
            items,
            direction: .newer,
            pageSize: 100
        )

        XCTAssertEqual(trimmed.count, 600)
        XCTAssertEqual(trimmed.first, 999_400)
        XCTAssertEqual(trimmed.last, 999_999)
    }
}

final class ChatInitialPositionPolicyTests: XCTestCase {

    private let owner = "owner@example.com"
    private let jid = "romeo@example.com"
    private let sourceDate = Date(timeIntervalSince1970: 1_711_283_200)

    private func makeExplicitRequest(
        source: ChatOpenMessageRequestSource = .pushNotification
    ) -> ChatOpenMessageRequest {
        ChatOpenMessageRequest(
            chatJid: jid,
            owner: owner,
            conversationType: .regular,
            anchor: ChatMessageAnchorRef(
                messagePrimary: "explicit-primary",
                archivedId: "explicit-archived",
                messageId: "explicit-message",
                authorId: nil,
                bodyFingerprint: nil,
                sourceDate: sourceDate
            ),
            highlight: true,
            markReadOnVisible: true,
            source: source
        )
    }

    private func makeState(
        unread: Int = 0,
        syncUnreadCount: Int = 0,
        syncUnreadAfterId: String? = nil,
        lastReadId: String? = nil,
        lastMessageId: String = "last-message",
        syncSnapshotLastArchiveId: String? = "snapshot-last",
        savedPosition: ChatSavedVisiblePosition? = nil,
        savedAtLastMessageId: String? = nil,
        savedAtSnapshotLastArchiveId: String? = nil
    ) -> ChatInitialPositionPolicy.ChatState {
        ChatInitialPositionPolicy.ChatState(
            owner: owner,
            jid: jid,
            conversationType: .regular,
            unread: unread,
            syncUnreadCount: syncUnreadCount,
            syncUnreadAfterId: syncUnreadAfterId,
            lastReadId: lastReadId,
            lastMessageId: lastMessageId,
            syncSnapshotLastArchiveId: syncSnapshotLastArchiveId,
            messageDate: sourceDate,
            savedPosition: savedPosition,
            savedAtLastMessageId: savedAtLastMessageId,
            savedAtSnapshotLastArchiveId: savedAtSnapshotLastArchiveId
        )
    }

    func testLegacyNonAnchorRequestOpensBottomWhenMessageAnchorsAreDisabled() {
        let explicit = makeExplicitRequest(source: .voicePlayer)
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 3,
            syncUnreadAfterId: "1711283295000000",
            savedPosition: saved,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(for: state, explicitRequest: explicit),
            .bottom
        )
    }

    func testSearchAndNotificationExplicitRequestsOverrideDefaultLatestOpen() {
        let search = makeExplicitRequest(source: .search)
        let push = makeExplicitRequest(source: .pushNotification)
        let mention = makeExplicitRequest(source: .mentionNotification)
        let unreadState = makeState(
            unread: 3,
            syncUnreadCount: 2,
            syncUnreadAfterId: "1711283295000000"
        )
        let zeroUnreadState = makeState()

        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(for: unreadState, explicitRequest: search),
            .open(search)
        )
        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(for: zeroUnreadState, explicitRequest: push),
            .open(push)
        )
        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(for: zeroUnreadState, explicitRequest: mention),
            .open(mention)
        )
    }

    func testDirectOpenAtMessageRequestIsHonoredForLocalFirstFrameResolution() throws {
        let request = try XCTUnwrap(
            ChatOpenMessageRequest.openAtMessage(
                jid: jid,
                owner: owner,
                conversationType: .regular,
                stanzaId: "1711283295000000",
                sourceDate: sourceDate
            )
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: makeState(), explicitRequest: request), .open(request))
    }

    func testAutomaticUnreadAndSavedPositionUsesServerUnreadBoundary() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 2,
            syncUnreadCount: 2,
            syncUnreadAfterId: "1711283295000000",
            savedPosition: saved,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        let decision = ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected initial unread boundary request, got \(decision)")
        }

        XCTAssertEqual(request.source, .initialUnreadBoundary)
        XCTAssertEqual(request.anchor.archivedId, "1711283295000000")
        XCTAssertEqual(request.targetResolution, .firstIncomingAfterBoundary("1711283295000000"))
        XCTAssertFalse(request.highlight)
        XCTAssertFalse(request.markReadOnVisible)
    }

    func testAutomaticSavedPositionIsRestoredWhenChatEdgesMatch() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 0,
            savedPosition: saved,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        let decision = ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected saved first-frame request, got \(decision)")
        }
        XCTAssertEqual(request.source, .savedVisiblePosition)
        XCTAssertEqual(request.anchor.messagePrimary, "saved-primary")
        XCTAssertEqual(request.anchor.archivedId, "saved-archived")
    }

    func testZeroUnreadWithUnreadAfterIdAndNoSavedPositionOpensBottom() {
        let state = makeState(
            unread: 0,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283295000000"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testZeroUnreadWithUnreadAfterIdAndSavedPositionRestoresSavedAnchor() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 0,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283295000000",
            savedPosition: saved,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        let decision = ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected saved first-frame request, got \(decision)")
        }
        XCTAssertEqual(request.source, .savedVisiblePosition)
        XCTAssertEqual(request.anchor.messagePrimary, "saved-primary")
    }

    func testSavedPositionIsIgnoredWhenLastMessageEdgeChanged() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 0,
            lastMessageId: "new-last-message",
            savedPosition: saved,
            savedAtLastMessageId: "old-last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testSavedPositionIsIgnoredWhenSnapshotEdgeChanged() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "saved-archived",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 0,
            syncSnapshotLastArchiveId: "new-snapshot",
            savedPosition: saved,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "old-snapshot"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testAutomaticUnreadBoundaryUsesSyncUnreadAfterWithoutLastReadFallback() {
        let syncState = makeState(
            unread: 1,
            syncUnreadCount: 1,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283294000000"
        )
        let fallbackState = makeState(
            unread: 1,
            syncUnreadCount: 1,
            syncUnreadAfterId: nil,
            lastReadId: "1711283294000000"
        )

        let decision = ChatInitialPositionPolicy.decision(for: syncState, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected initial unread boundary request, got \(decision)")
        }
        XCTAssertEqual(request.anchor.archivedId, "1711283295000000")
        XCTAssertEqual(request.targetResolution, .firstIncomingAfterBoundary("1711283295000000"))
        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: fallbackState, explicitRequest: nil), .bottom)
    }

    func testRuntimeOnlyUnreadWithSyncUnreadAfterIdOpensBottom() {
        let state = makeState(
            unread: 3,
            syncUnreadCount: 0,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283294000000"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testInvalidSyncUnreadAfterIdWithPositiveSyncUnreadCountOpensBottom() {
        let state = makeState(
            unread: 3,
            syncUnreadCount: 3,
            syncUnreadAfterId: "not-a-server-archive-id",
            lastReadId: "1711283294000000"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testBlankSyncUnreadAfterIdOpensBottomWithoutLastReadFallback() {
        for blankBoundary in ["", " ", "\n\t"] {
            let state = makeState(
                unread: 3,
                syncUnreadCount: 3,
                syncUnreadAfterId: blankBoundary,
                lastReadId: "1711283294000000"
            )

            XCTAssertEqual(
                ChatInitialPositionPolicy.decision(
                    for: state,
                    explicitRequest: nil
                ),
                .bottom,
                "blank sync unread boundary must not fall back to lastReadId"
            )
        }
    }

    func testUnreadBoundaryWithoutAnchorOpensBottom() {
        let state = makeState(unread: 1, syncUnreadCount: 1, syncUnreadAfterId: nil, lastReadId: nil)

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testClearedSavedPositionWithUnchangedEdgesOpensBottom() {
        let clearedSavedPosition = ChatSavedVisiblePosition(
            messagePrimary: nil,
            archivedId: nil,
            messageId: nil,
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 0,
            savedPosition: clearedSavedPosition,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testAutomaticUnreadWithClearedSavedPositionUsesServerUnreadBoundary() {
        let clearedSavedPosition = ChatSavedVisiblePosition(
            messagePrimary: nil,
            archivedId: nil,
            messageId: nil,
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 1,
            syncUnreadCount: 1,
            syncUnreadAfterId: "1711283295000000",
            savedPosition: clearedSavedPosition,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        let decision = ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected initial unread boundary request, got \(decision)")
        }
        XCTAssertEqual(request.source, .initialUnreadBoundary)
        XCTAssertEqual(request.targetResolution, .firstIncomingAfterBoundary("1711283295000000"))
    }

    func testDeterministicOpeningMatrixKeepsTargetSelectionAndReadSideEffectsSeparated() {
        let saved = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "1711283293000000",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let zeroServerUnreadStates = [
            makeState(unread: 0, syncUnreadCount: 0, syncUnreadAfterId: nil),
            makeState(unread: 0, syncUnreadCount: 0, syncUnreadAfterId: "1711283295000000"),
            makeState(unread: 3, syncUnreadCount: 0, syncUnreadAfterId: "1711283295000000")
        ]

        zeroServerUnreadStates.forEach { state in
            XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
        }

        let savedDecision = ChatInitialPositionPolicy.decision(
            for: makeState(
                unread: 0,
                syncUnreadCount: 0,
                syncUnreadAfterId: "1711283295000000",
                savedPosition: saved,
                savedAtLastMessageId: "last-message",
                savedAtSnapshotLastArchiveId: "snapshot-last"
            ),
            explicitRequest: nil
        )
        guard case .open(let savedRequest) = savedDecision else {
            return XCTFail("Expected saved first-frame request, got \(savedDecision)")
        }
        XCTAssertEqual(savedRequest.source, .savedVisiblePosition)

        let unreadDecision = ChatInitialPositionPolicy.decision(
            for: makeState(
                unread: 4,
                syncUnreadCount: 2,
                syncUnreadAfterId: "1711283295000000",
                savedPosition: saved,
                savedAtLastMessageId: "last-message",
                savedAtSnapshotLastArchiveId: "snapshot-last"
            ),
            explicitRequest: nil
        )
        guard case .open(let unreadRequest) = unreadDecision else {
            return XCTFail("Expected server unread boundary request, got \(unreadDecision)")
        }
        XCTAssertEqual(unreadRequest.source, .initialUnreadBoundary)
        XCTAssertEqual(unreadRequest.anchor.archivedId, "1711283295000000")
        XCTAssertEqual(unreadRequest.targetResolution, .firstIncomingAfterBoundary("1711283295000000"))
        XCTAssertFalse(unreadRequest.markReadOnVisible)

        let searchRequest = makeExplicitRequest(source: .search)
        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(
                for: makeState(unread: 4, syncUnreadCount: 2, syncUnreadAfterId: "1711283295000000"),
                explicitRequest: searchRequest
            ),
            .open(searchRequest)
        )
        XCTAssertTrue(ChatOpenMessageRequestHandlingPolicy.shouldHonorMessageAnchorRequest(source: .search))
        XCTAssertTrue(ChatOpenMessageRequestHandlingPolicy.shouldHonorMessageAnchorRequest(source: .initialUnreadBoundary))
        XCTAssertFalse(ChatOpenReadMarkingPolicy.shouldReadLastMessageOnOpen(isSynced: true, unread: 0))
        XCTAssertFalse(ChatOpenReadMarkingPolicy.shouldReadLastMessageOnOpen(isSynced: true, unread: 4))
    }
}

final class ChatInitialOpenTargetPolicyTests: XCTestCase {

    private let owner = "owner@example.com"
    private let jid = "romeo@example.com"
    private let sourceDate = Date(timeIntervalSince1970: 1_711_283_200)

    private func makeState(
        unread: Int = 0,
        syncUnreadCount: Int = 0,
        syncUnreadAfterId: String? = nil,
        lastReadId: String? = nil,
        savedPosition: ChatSavedVisiblePosition? = nil,
        savedAtLastMessageId: String? = nil,
        savedAtSnapshotLastArchiveId: String? = nil
    ) -> ChatInitialPositionPolicy.ChatState {
        ChatInitialPositionPolicy.ChatState(
            owner: owner,
            jid: jid,
            conversationType: .regular,
            unread: unread,
            syncUnreadCount: syncUnreadCount,
            syncUnreadAfterId: syncUnreadAfterId,
            lastReadId: lastReadId,
            lastMessageId: "last-message",
            syncSnapshotLastArchiveId: "snapshot-last",
            messageDate: sourceDate,
            savedPosition: savedPosition,
            savedAtLastMessageId: savedAtLastMessageId,
            savedAtSnapshotLastArchiveId: savedAtSnapshotLastArchiveId
        )
    }

    private func makeSearchRequest() -> ChatOpenMessageRequest {
        ChatOpenMessageRequest(
            chatJid: jid,
            owner: owner,
            conversationType: .regular,
            anchor: ChatMessageAnchorRef(
                messagePrimary: nil,
                archivedId: "1711283300000000",
                messageId: nil,
                authorId: nil,
                bodyFingerprint: nil,
                sourceDate: sourceDate
            ),
            highlight: true,
            markReadOnVisible: false,
            source: .search
        )
    }

    func testZeroSyncUnreadIgnoresUnreadAfterAndSavedPositionForLatestOpen() {
        let savedPosition = ChatSavedVisiblePosition(
            messagePrimary: "saved-primary",
            archivedId: "1711283294000000",
            messageId: "saved-message",
            sourceDate: sourceDate
        )
        let state = makeState(
            unread: 3,
            syncUnreadCount: 0,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283294000000",
            savedPosition: savedPosition,
            savedAtLastMessageId: "last-message",
            savedAtSnapshotLastArchiveId: "snapshot-last"
        )

        XCTAssertEqual(ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil), .bottom)
    }

    func testPositiveSyncUnreadUsesUnreadAfterBoundaryWithoutReadSideEffect() {
        let state = makeState(
            unread: 5,
            syncUnreadCount: 2,
            syncUnreadAfterId: "1711283295000000",
            lastReadId: "1711283294000000"
        )

        let decision = ChatInitialPositionPolicy.decision(for: state, explicitRequest: nil)
        guard case .open(let request) = decision else {
            return XCTFail("Expected initial unread boundary request, got \(decision)")
        }

        XCTAssertEqual(request.source, .initialUnreadBoundary)
        XCTAssertEqual(request.anchor.archivedId, "1711283295000000")
        XCTAssertEqual(request.targetResolution, .firstIncomingAfterBoundary("1711283295000000"))
        XCTAssertFalse(request.markReadOnVisible)
        XCTAssertFalse(ChatOpenReadMarkingPolicy.shouldReadLastMessageOnOpen(isSynced: true, unread: state.unread))
    }

    func testSearchRequestOverridesUnreadBoundaryAndKeepsAnchorContract() {
        let state = makeState(
            unread: 5,
            syncUnreadCount: 2,
            syncUnreadAfterId: "1711283295000000"
        )
        let searchRequest = makeSearchRequest()

        XCTAssertEqual(
            ChatInitialPositionPolicy.decision(for: state, explicitRequest: searchRequest),
            .open(searchRequest)
        )
        XCTAssertTrue(ChatOpenMessageRequestHandlingPolicy.shouldHonorMessageAnchorRequest(source: .search))
        XCTAssertFalse(ChatOpenReadMarkingPolicy.shouldReadLastMessageOnOpen(isSynced: false, unread: state.unread))
    }
}

final class ChatOpenAtMessageRequestBuilderTests: XCTestCase {
    func testBuilderStoresStanzaIdAsArchivedId() throws {
        let sourceDate = Date(timeIntervalSince1970: 1_711_283_200)

        let request = try XCTUnwrap(
