    ) -> ChatViewController.Datasource {
        ChatViewController.Datasource(
            primary: primary,
            jid: "group@xabber.example",
            owner: "owner@example.com",
            outgoing: false,
            sender: Sender(id: "sender@example.com", displayName: "Sender"),
            messageId: messageId,
            sentDate: Date(timeIntervalSince1970: 1_700_000_000),
            editDate: nil,
            kind: kind,
            withAuthor: false,
            withAvatar: false,
            error: false,
            errorType: "",
            canPinMessage: true,
            canEditMessage: false,
            canDeleteMessage: true,
            forwards: [],
            isOutgoing: false,
            isEdited: false,
            groupchatAuthorRole: "",
            groupchatAuthorId: "",
            groupchatAuthorNickname: "",
            groupchatAuthorBadge: "",
            isHasAttachedMessages: false,
            isDownloaded: true,
            state: .read,
            searchString: nil,
            errorMetadata: nil,
            burnDate: -1,
            afterburnInterval: -1,
            archivedId: archivedId,
            queryIds: nil,
            isRead: true,
            selectedSearchResultId: nil,
            isHadHistoryGap: false,
            tailed: false,
            isFakeMessage: isFakeMessage,
            images: [],
            videos: [],
            files: [],
            audios: [],
            timeMarkerText: NSAttributedString(string: "12:00"),
            indicator: .read,
            avatarUrl: nil,
            attributedAuthor: nil
        )
    }

    private func makeStoredMessage(
        primary: String,
        archivedId: String,
        owner: String = "owner@example.com",
        jid: String = "group@xabber.example",
        conversationType: ClientSynchronizationManager.ConversationType = .regular,
        timestamp: TimeInterval = 1_700_000_000
    ) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = primary
        message.owner = owner
        message.opponent = jid
        message.conversationType = conversationType
        message.archivedId = archivedId
        message.messageId = "message-id-\(primary)"
        message.messageType = MessageStorageItem.MessageDisplayType.text.rawValue
        message.displayAs = .text
        message.body = primary
        message.date = Date(timeIntervalSince1970: timestamp)
        message.sentDate = message.date
        message.outgoing = false
        message.isRead = true
        message.state = .read
        return message
    }

    private func makeAnchor(
        messagePrimary: String? = nil,
        archivedId: String? = nil,
        messageId: String? = nil
    ) -> ChatMessageAnchorRef {
        ChatMessageAnchorRef(
            messagePrimary: messagePrimary,
            archivedId: archivedId,
            messageId: messageId,
            authorId: nil,
            bodyFingerprint: nil,
            sourceDate: Date(timeIntervalSince1970: 1_700_000_000)
        )
    }

    private func makeRequest(
        archivedId: String? = "archived-42",
        messageId: String? = "message-42",
        sourceDate: Date = Date(timeIntervalSince1970: 1_700_000_000),
        source: ChatOpenMessageRequestSource = .mentionNotification
    ) -> ChatOpenMessageRequest {
        ChatOpenMessageRequest(
            chatJid: "group@xabber.example",
            owner: "owner@example.com",
            conversationType: .group,
            anchor: ChatMessageAnchorRef(
                messagePrimary: nil,
                archivedId: archivedId,
                messageId: messageId,
                authorId: "author-1",
                bodyFingerprint: "hello @you",
                sourceDate: sourceDate
            ),
            highlight: false,
            markReadOnVisible: false,
            source: source
        )
    }

    private func makeSearchOpenRequest(
        controller: ChatViewController,
        archivedId: String,
        sourceDate: Date = Date(timeIntervalSince1970: 1_700_000_000)
    ) -> ChatOpenMessageRequest {
        ChatOpenMessageRequest(
            chatJid: controller.jid,
            owner: controller.owner,
            conversationType: controller.conversationType,
            anchor: ChatMessageAnchorRef(
                messagePrimary: nil,
                archivedId: archivedId,
                messageId: nil,
                authorId: nil,
                bodyFingerprint: nil,
                sourceDate: sourceDate
            ),
            highlight: true,
            markReadOnVisible: false,
            source: .search
        )
    }

    @MainActor
    private func makeLoadedSearchController() -> ChatViewController {
        let controller = ChatViewController()
        controller.owner = "owner@example.com"
        controller.jid = "group@xabber.example"
        controller.conversationType = .group
        controller.loadViewIfNeeded()
        // Loading the view installs the production timeline and may leave an
        // empty first-frame preparation active. This fixture represents an
        // already committed displayed chat, so retire that unrelated work
        // before publishing its loaded anchor row.
        controller.cancelStackedNavigationPresentationPreparation()
        controller.isStackedNavigationPresentationPreparationCancelled = false
        controller.datasource = [
            makeDatasource(primary: "loaded", archivedId: "archived-loaded", messageId: "message-loaded")
        ]
        controller.datasourceSnapshot = ChatDatasourceCoordinator.makeSnapshot(
            items: controller.datasource
        )
        controller.showSkeletonObserver.accept(false)
        controller.loadDatasourceObserver.accept(true)
        controller.syncCurrentPage(
            with: ChatDatasetWindow(
                minIndex: 0,
                maxIndex: controller.datasource.count
            )
        )
        controller.messagesCollectionView.reloadData()
        controller.messagesCollectionView.layoutIfNeeded()
        return controller
    }

    private func visibleCandidate(
        primary: String,
        archivedId: String? = nil,
        messageId: String? = nil,
        rowKind: ChatVisiblePositionPolicy.RowKind = .message,
        isFakeMessage: Bool = false,
        frame: CGRect
    ) -> ChatVisiblePositionPolicy.Candidate {
        ChatVisiblePositionPolicy.Candidate(
            primary: primary,
            archivedId: archivedId,
            messageId: messageId,
            sentDate: Date(timeIntervalSince1970: 1_700_000_000),
            rowKind: rowKind,
            isFakeMessage: isFakeMessage,
            frame: frame
        )
    }

    func testUnreadBoundaryTargetPrefersFirstIncomingMessageAfterBoundary() {
        let boundary = ChatUnreadBoundaryTargetPolicy.Candidate(
            primary: "boundary",
            archivedId: "1711283295000000",
            messageId: "boundary-id",
            sourceDate: Date(timeIntervalSince1970: 1_711_283_295),
            isOutgoing: false
        )
        let outgoingAfterBoundary = ChatUnreadBoundaryTargetPolicy.Candidate(
            primary: "outgoing-after",
            archivedId: "1711283295000001",
            messageId: "outgoing-id",
            sourceDate: Date(timeIntervalSince1970: 1_711_283_296),
            isOutgoing: true
        )
        let incomingAfterBoundary = ChatUnreadBoundaryTargetPolicy.Candidate(
            primary: "incoming-after",
            archivedId: "1711283295000002",
            messageId: "incoming-id",
            sourceDate: Date(timeIntervalSince1970: 1_711_283_297),
            isOutgoing: false
        )

        let target = ChatUnreadBoundaryTargetPolicy.target(
            boundaryArchivedId: "1711283295000000",
            fallback: boundary,
            loadedMessages: [incomingAfterBoundary, outgoingAfterBoundary, boundary]
        )

        XCTAssertEqual(target, incomingAfterBoundary)
    }

    func testUnreadBoundaryTargetChoosesEarliestIncomingArchiveAfterBoundary() {
        let boundary = ChatUnreadBoundaryTargetPolicy.Candidate(
            primary: "boundary",
