        XCTAssertEqual(target, earlierIncoming)
    }

    func testUnreadBoundaryTargetUsesBoundaryWhenFirstIncomingUnreadIsNotLoaded() {
        let boundary = ChatUnreadBoundaryTargetPolicy.Candidate(
            primary: "boundary",
