        XCTAssertEqual(actions, [.submitArchiveTarget])
        XCTAssertEqual(failures, 1)
        XCTAssertNil(controller.pendingOpenMessageRequest)
        XCTAssertNil(controller.activeAnchorExecutionState)
    }



