    private func assertNoVisibleTopHairline(
        in cell: SpecialMessageTableViewCell,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        let maxHairlineHeight = (1.0 / UIScreen.main.scale) + 0.5
        let visibleTopHairlines = cell.contentView.subviews.filter { view in
            guard view !== cell.contentStack,
                  view !== cell.avatarStackContainer,
                  !view.isHidden,
                  view.alpha > 0,
                  view.backgroundColor != nil else {
                return false
            }

            return abs(view.frame.minY) <= 0.5
                && view.frame.height > 0
                && view.frame.height <= maxHairlineHeight
        }

        XCTAssertTrue(visibleTopHairlines.isEmpty, file: file, line: line)
    }

    private func assertNoSelectionOutline(
        in cell: UITableViewCell,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertNil(cell.backgroundConfiguration?.visualEffect, file: file, line: line)
        XCTAssertTrue(
            cell.backgroundConfiguration?.strokeColor == nil
                || cell.backgroundConfiguration?.strokeColor == .clear,
            file: file,
            line: line
        )
        XCTAssertEqual(cell.backgroundConfiguration?.strokeWidth ?? 0, 0, file: file, line: line)
        XCTAssertEqual(cell.backgroundConfiguration?.strokeOutset ?? 0, 0, file: file, line: line)
        XCTAssertNil(cell.backgroundView, file: file, line: line)
        XCTAssertNil(cell.selectedBackgroundView, file: file, line: line)
        XCTAssertNil(cell.multipleSelectionBackgroundView, file: file, line: line)
        XCTAssertEqual(cell.focusStyle, .custom, file: file, line: line)
        XCTAssertEqual(cell.layer.borderWidth, 0, file: file, line: line)
        XCTAssertEqual(cell.layer.shadowOpacity, 0, file: file, line: line)
        XCTAssertEqual(cell.contentView.layer.borderWidth, 0, file: file, line: line)
        XCTAssertEqual(cell.contentView.layer.shadowOpacity, 0, file: file, line: line)
    }

    private func chatCellLayoutFrames(_ cell: ChatListTableViewCell) -> [String: CGRect] {
        [
            "account": cell.accountIndicator.convert(cell.accountIndicator.bounds, to: cell),
            "avatarContainer": cell.userImageView.convert(cell.userImageView.bounds, to: cell),
            "avatar": cell.avatarView.convert(cell.avatarView.bounds, to: cell),
            "status": cell.statusIndicator.convert(cell.statusIndicator.bounds, to: cell),
            "info": cell.infoStack.convert(cell.infoStack.bounds, to: cell)
        ]
    }

    private func assertChatCellLayoutFrames(
        _ actual: [String: CGRect],
        equalTo expected: [String: CGRect],
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        expected.forEach { key, expectedFrame in
            guard let actualFrame = actual[key] else {
                XCTFail("Missing frame for \(key)", file: file, line: line)
                return
            }
            XCTAssertEqual(actualFrame.minX, expectedFrame.minX, accuracy: 0.001, file: file, line: line)
            XCTAssertEqual(actualFrame.minY, expectedFrame.minY, accuracy: 0.001, file: file, line: line)
            XCTAssertEqual(actualFrame.width, expectedFrame.width, accuracy: 0.001, file: file, line: line)
            XCTAssertEqual(actualFrame.height, expectedFrame.height, accuracy: 0.001, file: file, line: line)
        }
    }

    private func registerAccountColor(owner: String, colorKey: String) {
        AccountColorManager.shared.accounts.insert(
            AccountColorManager.ColorForJid(
                jid: owner,
                color: AccountColorManager.shared.colorForKey(colorKey)
            )
        )
    }

    private func activateBottomSearch(
        _ bottomSearchHostView: BottomSearchHostView,
        updater: ChatSearchResultsController,
        query: String = "romeo"
    ) {
        bottomSearchHostView.setExpanded(true, animated: false)
        bottomSearchHostView.setQuery(query, notify: false)
        updater.updateSearchResults(with: query)
    }

    private func searchHostScenarios() -> [SearchHostScenario] {
        [
            SearchHostScenario(name: "LastChats chats") {
                self.makeLastChatsSearchHost(filter: .chats)
            },
            SearchHostScenario(name: "LastChats archived") {
                self.makeLastChatsSearchHost(filter: .archived)
            },
            SearchHostScenario(name: "LastChats saved") {
                self.makeLastChatsSearchHost(filter: .saved)
            },
            SearchHostScenario(name: "Contacts normal") {
                self.makeContactsSearchHost(isGroup: false)
            },
            SearchHostScenario(name: "Contacts group") {
                self.makeContactsSearchHost(isGroup: true)
            },
            SearchHostScenario(name: "LastCalls") {
                self.makeLastCallsSearchHost()
            }
        ]
    }

    private func lastChatsSearchHostScenarios() -> [SearchHostScenario] {
        [
            SearchHostScenario(name: "LastChats chats") {
                self.makeLastChatsSearchHost(filter: .chats)
            },
            SearchHostScenario(name: "LastChats archived") {
                self.makeLastChatsSearchHost(filter: .archived)
            },
            SearchHostScenario(name: "LastChats saved") {
                self.makeLastChatsSearchHost(filter: .saved)
            }
        ]
    }

    private func makeLastChatsSearchHost(filter: LastChatsViewController.Filter) -> SearchHost {
        let viewController = LastChatsViewController()
        viewController.filter.accept(filter)
        return SearchHost(
            viewController: viewController,
            searchController: viewController.searchController,
            bottomSearchHostView: viewController.bottomSearchHostView,
            updater: viewController.chatSearchResultsController,
            configureSearchBar: { viewController.configureSearchBar() },
            activateSearch: {
                self.activateBottomSearch(
                    viewController.bottomSearchHostView,
                    updater: viewController.chatSearchResultsController
                )
            },
            viewWillAppear: {
                viewController.beginAppearanceTransition(true, animated: false)
                viewController.endAppearanceTransition()
            },
            openSearchResult: { viewController.openSearchResult($0) }
        )
    }

    private func makeContactsSearchHost(isGroup: Bool) -> SearchHost {
        let viewController = ContactsViewController()
        viewController.isGroup = isGroup
        return SearchHost(
            viewController: viewController,
            searchController: viewController.searchController,
            bottomSearchHostView: viewController.bottomSearchHostView,
            updater: nil,
            configureSearchBar: { viewController.configureSearchBar() },
            activateSearch: {
                viewController.bottomSearchHostView.setExpanded(true, animated: false)
                viewController.bottomSearchHostView.setQuery("romeo", notify: false)
            },
            viewWillAppear: {
                viewController.beginAppearanceTransition(true, animated: false)
                viewController.endAppearanceTransition()
            },
            openSearchResult: nil
        )
    }

    private func makeLastCallsSearchHost() -> SearchHost {
