@MainActor
final class ChatViewControllerCorrectnessTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "ChatViewControllerCorrectnessTests-\(name)-\(UUID().uuidString)"
        )
        AccountManager.shared.users.removeAll()
        AccountManager.shared.activeUsers.accept(Set<String>())
        AccountManager.shared.connectingUsers.accept(Set<String>())
        AccountManager.shared.authenticatedUsers.accept(Set<String>())
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        AccountManager.shared.users.removeAll()
        AccountManager.shared.activeUsers.accept(Set<String>())
        AccountManager.shared.connectingUsers.accept(Set<String>())
        AccountManager.shared.authenticatedUsers.accept(Set<String>())
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testAddAndRemoveObserversAreIdempotent() {
        let controller = makeController()

        XCTAssertFalse(controller.chatObserversRegistered)

        controller.addObservers()
        controller.addObservers()

        XCTAssertTrue(controller.chatObserversRegistered)

        controller.removeObservers()
        controller.removeObservers()

        XCTAssertFalse(controller.chatObserversRegistered)
    }

    func testBackgroundCleanupUsesCurrentLastChatsKey() throws {
        let controller = makeController(owner: "owner@example.com", jid: "romeo@example.com")
        try insertLastChat(owner: controller.owner, jid: controller.jid, isPrereaded: true)

        controller.handleApplicationDidEnterBackground()

        let realm = try WRealm.safe()
        let chat = try XCTUnwrap(realm.object(
            ofType: LastChatsStorageItem.self,
            forPrimaryKey: LastChatsStorageItem.genPrimary(
                jid: controller.jid,
                owner: controller.owner,
                conversationType: controller.conversationType
            )
        ))
        XCTAssertFalse(chat.isPrereaded)
        XCTAssertNil(realm.object(
            ofType: LastChatsStorageItem.self,
            forPrimaryKey: LastChatsStorageItem.genPrimary(
                jid: controller.owner,
                owner: controller.jid,
                conversationType: controller.conversationType
            )
        ))
    }

    func testMessageForStaleDatasourceIndexPathReturnsFakeMessage() {
        let controller = makeController()

        let message = controller.messageForItem(
            at: IndexPath(item: 0, section: 0),
            in: controller.messagesCollectionView
        )

        guard let item = message as? ChatViewController.Datasource else {
            XCTFail("Expected datasource fallback")
            return
        }
        XCTAssertEqual(item.primary, ChatViewController.staleDatasourceFallbackPrimary)
        XCTAssertTrue(item.isFakeMessage)
    }

    func testNavigationDisappearanceDoesNotReadWholeDialog() throws {
        let owner = "owner@example.com"
        let jid = "romeo@example.com"
        let accountQueue = DispatchQueue(label: "ChatViewControllerCorrectnessTests.account")
        let account = Account(jid: owner, queue: accountQueue)
        AccountManager.shared.users.append(account)
        let controller = makeController(owner: owner, jid: jid)
        try insertLastChat(
            owner: owner,
            jid: jid,
            unread: 2,
            syncUnreadCount: 2,
            lastMessageId: "archive-2"
        )

        controller.runNavigationDisappearanceCleanupIfNeeded()
        accountQueue.sync {}

        let realm = try WRealm.safe()
        let chat = try XCTUnwrap(realm.object(
            ofType: LastChatsStorageItem.self,
            forPrimaryKey: LastChatsStorageItem.genPrimary(
                jid: jid,
                owner: owner,
                conversationType: .regular
            )
        ))
        XCTAssertEqual(chat.unread, 2)
        XCTAssertEqual(chat.syncUnreadCount, 2)
        XCTAssertEqual(chat.syncUnreadAfterId, nil)
    }

    private func makeController(
        owner: String = "owner@example.com",
        jid: String = "romeo@example.com"
    ) -> ChatViewController {
        let controller = ChatViewController()
        controller.owner = owner
        controller.jid = jid
        controller.conversationType = .regular
        controller.ownerSender = Sender(id: owner, displayName: owner)
        controller.opponentSender = Sender(id: jid, displayName: jid)
        return controller
    }

    @discardableResult
    private func insertLastChat(
        owner: String,
        jid: String,
        conversationType: ClientSynchronizationManager.ConversationType = .regular,
        isPrereaded: Bool = false,
        unread: Int = 0,
        syncUnreadCount: Int = 0,
        lastMessageId: String = ""
    ) throws -> LastChatsStorageItem {
        let realm = try WRealm.safe()
        let chat = LastChatsStorageItem()
        chat.owner = owner
        chat.jid = jid
        chat.conversationType = conversationType
        chat.primary = LastChatsStorageItem.genPrimary(
            jid: jid,
            owner: owner,
            conversationType: conversationType
        )
        chat.isPrereaded = isPrereaded
        chat.unread = unread
        chat.syncUnreadCount = syncUnreadCount
        chat.runtimeUnreadCount = max(0, unread - syncUnreadCount)
        chat.lastMessageId = lastMessageId
        try realm.write {
            realm.add(chat, update: .modified)
        }
        return chat
    }
}

final class MessageDeleteManagerRegressionTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "MessageDeleteManagerRegressionTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write { realm.deleteAll() }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    private func makeElement(xml: String) throws -> DDXMLElement {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "MessageDeleteManagerRegressionTests", code: 1)
        }
        return root
    }

    private func makeIQ(xml: String) throws -> XMPPIQ {
        XMPPIQ(from: try makeElement(xml: xml))
    }

    func testSuccessfulDeleteReadClearsQueryTracking() throws {
        let manager = MessageDeleteManager(withOwner: "owner@example.com")
        let elementId = "RRR: success"

        manager.queryIds.insert(elementId)
        manager.itemsQuery.insert(
            MessageDeleteManager.Item(
                "",
                kind: .retract,
                messageId: "message-1",
                iqId: elementId,
                callback: nil
            )
        )

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(elementId)'/>
        """)

        XCTAssertTrue(manager.read(withIQ: iq))
        XCTAssertEqual(manager.queryIds.count, 0)
        XCTAssertEqual(manager.itemsQuery.count, 0)
    }

    func testRewriteNotificationPersistsNewMediaIndexRow() throws {
        let owner = "owner@example.com"
        let opponent = "romeo@example.com"
        let archivedID = "rewrite-media-archive-1"
        let messagePrimary = MessageStorageItem.genPrimary(
            messageId: "rewrite-media-message-1",
            owner: owner
        )
        let realm = try WRealm.safe()
        let stored = MessageStorageItem()
        stored.primary = messagePrimary
        stored.owner = owner
        stored.opponent = opponent
        stored.messageId = "rewrite-media-message-1"
        stored.archivedId = archivedID
        stored.body = "before edit"
        stored.legacyBody = "before edit"
        stored.date = Date(timeIntervalSince1970: 10)
        stored.sentDate = stored.date
        stored.conversationType = .regular
        try realm.write {
            realm.add(stored, update: .modified)
        }

        let sourceURL = "https://files.example.com/rewrite-photo.jpg"
        let rewrite = try XMPPMessage(from: makeElement(xml: """
        <message type='headline' from='example.com' to='\(owner)'>
          <replace xmlns='https://xabber.com/protocol/rewrite#notify'
                   conversation='\(opponent)'
                   type='regular'
                   id='\(archivedID)'
                   version='2'>
            <message xmlns='jabber:client'
                     from='\(opponent)'
                     to='\(owner)'
                     type='chat'
                     id='rewrite-media-message-1'>
              <replaced xmlns='urn:xmpp:message-correct:0'
                        stamp='2026-06-04T10:01:00Z'/>
              <body>\(sourceURL)</body>
              <reference xmlns='https://xabber.com/protocol/references'
                         begin='0'
                         end='\(sourceURL.unicodeScalars.count)'
                         type='mutable'>
                <file-sharing xmlns='https://xabber.com/protocol/files'>
                  <file>
                    <name>rewrite-photo.jpg</name>
                    <media-type>image/jpeg</media-type>
                    <size>42</size>
                  </file>
                  <sources><uri>\(sourceURL)</uri></sources>
                </file-sharing>
              </reference>
            </message>
          </replace>
        </message>
        """))

        XCTAssertTrue(
            MessageDeleteManager(withOwner: owner).readRewriteNotify(rewrite)
        )

        realm.refresh()
        let edited = try XCTUnwrap(
            realm.object(
                ofType: MessageStorageItem.self,
                forPrimaryKey: messagePrimary
            )
        )
        let mediaReference = try XCTUnwrap(
            edited.references.first(where: { $0.kind == .media })
        )
        let attachmentPrimary = MessageMediaAttachmentStorageItem.genPrimary(
            jid: opponent,
            owner: owner,
            url: sourceURL,
            messagePrimary: messagePrimary
        )
        XCTAssertEqual(mediaReference.url, sourceURL)
        XCTAssertNotNil(
            realm.object(
                ofType: MessageMediaAttachmentStorageItem.self,
                forPrimaryKey: attachmentPrimary
            ),
            "A rewrite must commit the new reference and media index row together"
        )
    }
}

final class GroupchatNicknamePresentationRegressionTests: XCTestCase {

    private func makeElement(xml: String) throws -> DDXMLElement {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "GroupchatNicknamePresentationRegressionTests", code: 1)
        }
        return root
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        XMPPMessage(from: try makeElement(xml: xml))
    }

    func testGroupchatUserElementSupportsDirectV3User() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='user-1'>
              <nickname>Ivan</nickname>
            </user>
          </x>
          <body>Ivan:
        hello</body>
        </message>
        """)

        let user = try XCTUnwrap(groupchatUserElement(from: message))
        XCTAssertEqual(user.attributeStringValue(forName: "id"), "user-1")
        XCTAssertEqual(user.element(forName: "nickname")?.stringValue, "Ivan")
    }

    func testGroupchatUserElementRejectsWrappedLegacyUserReference() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <reference xmlns='https://xabber.com/protocol/references' type='mutable' begin='0' end='6'>
              <user xmlns='https://xabber.com/protocol/groups' id='user-1'>
                <nickname>Ivan</nickname>
              </user>
            </reference>
          </x>
          <body>Ivan:
        hello</body>
        </message>
        """)

        XCTAssertNil(groupchatUserElement(from: message))
    }

    func testConfigureIncomingMessageStripsDirectUserFallbackPrefix() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='user-1'>
              <nickname>Ivan</nickname>
            </user>
          </x>
          <body>Ivan:
        hello</body>
        </message>
        """)
        let item = MessageStorageItem()

        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "group@example.com",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )

        XCTAssertEqual(item.body, "hello")
        XCTAssertEqual(item.legacyBody, "Ivan:\nhello")
        XCTAssertEqual(item.groupchatAuthorNickname, "Ivan")
    }

    func testConfigureIncomingMessageKeepsBodyWhenPrefixDoesNotMatchResolvedNickname() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='user-1'>
              <nickname>Ivan</nickname>
            </user>
          </x>
          <body>Petr:
        hello</body>
        </message>
        """)
        let item = MessageStorageItem()

        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "group@example.com",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )

        XCTAssertEqual(item.body, "Petr:\nhello")
        XCTAssertEqual(item.legacyBody, "Petr:\nhello")
        XCTAssertEqual(item.groupchatAuthorNickname, "Ivan")
    }

    func testConfigureIncomingMessageDoesNotTrimBeforeExactNicknamePrefixCheck() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='user-1'>
              <nickname>Ivan</nickname>
            </user>
          </x>
          <body>&#32;Ivan:
        body&#32;</body>
        </message>
        """)
        let item = MessageStorageItem()

        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "group@example.com",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )

        XCTAssertEqual(item.body, " Ivan:\nbody ")
    }

    func testMessageAuthorSnapshotIsSelfContainedAndImmutable() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='snapshot-id'>
              <nickname>Snapshot nickname</nickname>
              <role>member</role>
              <badge>snapshot-badge</badge>
            </user>
          </x>
          <body>Snapshot nickname:
        hello</body>
        </message>
        """)
        let item = MessageStorageItem()
        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "group@example.com",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )
        XCTAssertEqual(item.groupchatAuthorId, "snapshot-id")
        XCTAssertEqual(item.groupchatAuthorNickname, "Snapshot nickname")
        XCTAssertEqual(item.groupchatAuthorBadge, "snapshot-badge")

        var mutableMember = GroupMember(id: "snapshot-id")
        mutableMember.nickname = "Changed later"
        mutableMember.badge = "changed-later"

        XCTAssertEqual(mutableMember.nickname, "Changed later")
        XCTAssertEqual(mutableMember.badge, "changed-later")
        XCTAssertEqual(item.groupchatAuthorNickname, "Snapshot nickname")
        XCTAssertEqual(item.groupchatAuthorBadge, "snapshot-badge")
    }

    func testConfigureIncomingMessageElidesAnonymousMutableFallbackRangeAndShiftsMentionOffsets() throws {
        let message = try makeMessage(xml: """
        <message xmlns='jabber:client' lang='en' to='public-group@seed.xabber.org' from='public-group@seed.xabber.org' type='chat' id='be6ea1705b4a6ecf'>
          <reference xmlns='https://xabber.com/protocol/references' end='7' begin='0' type='mutable'/>
          <x xmlns='https://xabber.com/protocol/groups'>
            <user id='3crotuldccvzsrif'>
              <role>member</role>
              <nickname>Heidi</nickname>
              <badge/>
              <jid>heidi@seed.xabber.org</jid>
            </user>
          </x>
          <reference xmlns='https://xabber.com/protocol/references' end='24' begin='7' type='decoration'>
            <link xmlns='https://xabber.com/protocol/markup'>xmpp:public-group@seed.xabber.org?members;id=0oud1rprz9ayy4kd</link>
          </reference>
          <markable xmlns='urn:xmpp:chat-markers:0'/>
          <origin-id xmlns='urn:xmpp:sid:0' id='be6ea1705b4a6ecf'/>
          <body>Heidi:
        alice@seed.xabber.org mention #2287</body>
        </message>
        """)
        let item = MessageStorageItem()

        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "public-group@seed.xabber.org",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )

        XCTAssertEqual(item.body, "alice@seed.xabber.org mention #2287")
        XCTAssertEqual(item.legacyBody, "Heidi:\nalice@seed.xabber.org mention #2287")
        XCTAssertEqual(item.groupchatAuthorNickname, "Heidi")

        let mention = try XCTUnwrap(item.references.first(where: { $0.kind == .mention }))
        XCTAssertEqual(mention.begin, 0)
        XCTAssertEqual(mention.end, 17)
    }

    func testParseReferencesIgnoresInvalidAnonymousMutableRanges() throws {
        let message = try makeMessage(xml: """
        <message type='chat' from='group@example.com/Group' to='owner@example.com'>
          <reference xmlns='https://xabber.com/protocol/references' type='mutable' begin='20' end='40'/>
          <reference xmlns='https://xabber.com/protocol/references' type='decoration' begin='0' end='5'>
            <link xmlns='https://xabber.com/protocol/markup'>xmpp:group@example.com?members;id=user-1</link>
          </reference>
          <body>hello</body>
        </message>
        """)
        let references = parseReferences(
            message,
            primary: "test-primary",
            jid: "group@example.com",
            owner: "owner@example.com"
        )

        let mention = try XCTUnwrap(references.first(where: { $0.kind == .mention }))
        XCTAssertEqual(mention.begin, 0)
        XCTAssertEqual(mention.end, 5)

        let item = MessageStorageItem()
        item.configureIncomingMessage(
            message,
            owner: "owner@example.com",
            opponent: "group@example.com",
            outgoing: false,
            isRead: false,
            date: Date(timeIntervalSince1970: 10)
        )

        XCTAssertEqual(item.body, "hello")
    }
}

