    private func firstForwardedPayload(
        in stanza: XMPPMessage,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws -> XMPPMessage {
        let reference = try XCTUnwrap(stanza.element(forName: "reference"), file: file, line: line)
        XCTAssertEqual(reference.xmlns(), "https://xabber.com/protocol/references", file: file, line: line)
        let forwarded = try XCTUnwrap(reference.element(forName: "forwarded", xmlns: "urn:xmpp:forward:0"), file: file, line: line)
        let payload = try XCTUnwrap(forwarded.element(forName: "message"), file: file, line: line)
        return XMPPMessage(from: payload)
    }

    func testFavoritesDiscoRequiresArchiveIdentityAndFeature() throws {
        let validQuery = try makeElement(xml: """
        <query xmlns='http://jabber.org/protocol/disco#info'>
          <identity category='component' type='archive' name='Saved messages'/>
          <feature var='urn:xabber:favorites:0'/>
        </query>
        """)

        let missingFeatureQuery = try makeElement(xml: """
        <query xmlns='http://jabber.org/protocol/disco#info'>
          <identity category='component' type='archive' name='Saved messages'/>
        </query>
        """)

        XCTAssertTrue(XMPPFavoritesManager.supportsService(validQuery))
        XCTAssertFalse(XMPPFavoritesManager.supportsService(missingFeatureQuery))
    }

    func testIgnoredServiceJidsIncludeFavoritesNode() throws {
        let realm = try WRealm.safe()
        try realm.write {
            let abuse = XMPPAbuseConfigStorageItem()
            abuse.primary = "abuse"
            abuse.owner = owner
            abuse.abuseAddress = "abuse.xmppdev01.xabber.com"
            realm.add(abuse)
        }

        let ignored = XMPPServiceJidsSupport.ignoredServiceJids(
            in: realm,
            accountJids: [owner],
            serviceNodes: ["favorites.xmppdev01.xabber.com", "notifications.xmppdev01.xabber.com"]
        )

        XCTAssertTrue(ignored.contains(owner))
        XCTAssertTrue(ignored.contains("favorites.xmppdev01.xabber.com"))
        XCTAssertTrue(ignored.contains("notifications.xmppdev01.xabber.com"))
        XCTAssertTrue(ignored.contains("abuse.xmppdev01.xabber.com"))
    }

    func testFavoritesStorageCreationIsIdempotentForRepeatedDisco() throws {
        let manager = XMPPFavoritesManager(withOwner: owner)
        manager.node = "favorites.xmppdev01.xabber.com"

        try manager.createXMPPFavoritesManagerStorageItem()
        manager.node = "favorites2.xmppdev01.xabber.com"
        try manager.createXMPPFavoritesManagerStorageItem()

        let realm = try WRealm.safe()
        let rows = realm.objects(XMPPFavoritesManagerStorageItem.self)
        XCTAssertEqual(rows.count, 1)
        let row = try XCTUnwrap(
            realm.object(
                ofType: XMPPFavoritesManagerStorageItem.self,
                forPrimaryKey: XMPPFavoritesManagerStorageItem.genPrimary(owner: owner)
            )
        )
        XCTAssertEqual(row.owner, owner)
        XCTAssertEqual(row.node, "favorites2.xmppdev01.xabber.com")
    }

