        XCTAssertTrue(display.isSavedForward)
        XCTAssertEqual(display.displayAuthorJid, owner)
        XCTAssertTrue(state.showsDeliveryIndicator)
        XCTAssertEqual(state.effectiveState, .read)
    }

    func testSavedForwardedFromOtherShowsNoDeliveryIndicator() throws {
        let message = try makeForwardedSavedMessage(id: "saved-state-other-forward-1")
        let mam = try makeMamResult(message: message, archiveId: "archive-state-other-forward-1", queryId: "saved-state-other-forward")
        let stored = try receiveSaved(XMPPMessage(from: mam))

        let display = SavedMessageDisplayPolicy.presentation(for: stored, currentUserJid: owner, currentUserName: "Igor Boldin")
        let state = SavedMessageStatePolicy.presentation(
            for: stored,
            displayAuthorJid: display.displayAuthorJid,
            isSavedForward: display.isSavedForward,
            isDirectSavedNote: display.isDirectSavedNote,
            currentUserJid: owner
        )

        XCTAssertTrue(display.isSavedForward)
        XCTAssertEqual(display.displayAuthorJid, contactJid)
        XCTAssertFalse(state.showsDeliveryIndicator)
        XCTAssertEqual(state.effectiveState, .none)
    }

    func testSavedPendingMessageShowsSendingUntilServerProof() throws {
        configureFavorites()
        let manager = MessageManager(withOwner: owner, activeStream: false)
        let originId = manager.sendSimpleMessage(
            "Pending saved note",
            to: favoritesJid,
            forwarded: [],
            conversationType: .saved
        )

        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(
            realm.object(
                ofType: MessageStorageItem.self,
                forPrimaryKey: MessageStorageItem.genPrimary(messageId: originId, owner: owner)
            )
        )
        let display = SavedMessageDisplayPolicy.presentation(for: stored, currentUserJid: owner, currentUserName: "Igor Boldin")
        let state = SavedMessageStatePolicy.presentation(
            for: stored,
            displayAuthorJid: display.displayAuthorJid,
            isSavedForward: display.isSavedForward,
            isDirectSavedNote: display.isDirectSavedNote,
            currentUserJid: owner
        )

        XCTAssertEqual(stored.archivedId, "")
        XCTAssertTrue(state.showsDeliveryIndicator)
        XCTAssertEqual(state.effectiveState, .sending)
    }

    func testSavedReadLogicDoesNotSendDisplayMarkerForForwardedOtherAuthor() throws {
        let stored = try receiveSaved(try makeForwardedSavedMessage(id: "saved-state-read-marker-1"))
        let display = SavedMessageDisplayPolicy.presentation(for: stored, currentUserJid: owner, currentUserName: "Igor Boldin")
        let state = SavedMessageStatePolicy.presentation(
            for: stored,
            displayAuthorJid: display.displayAuthorJid,
            isSavedForward: display.isSavedForward,
            isDirectSavedNote: display.isDirectSavedNote,
            currentUserJid: owner
        )

        XCTAssertFalse(state.shouldSendDisplayedMarker)
        XCTAssertFalse(SavedMessageStatePolicy.shouldSendDisplayedMarker(conversationType: .saved))
        XCTAssertFalse(SavedMessageStatePolicy.shouldSendDisplayedMarker(for: stored))
    }

    func testSavedStatePolicyDoesNotAffectRegularChatMessages() {
        let message = MessageStorageItem()
        message.owner = owner
        message.opponent = contactJid
        message.conversationType = .regular
        message.outgoing = true
        message.state = .deliver

        let state = SavedMessageStatePolicy.presentation(
            for: message,
            displayAuthorJid: owner,
            isSavedForward: false,
            isDirectSavedNote: false,
            currentUserJid: owner
        )

        XCTAssertTrue(state.showsDeliveryIndicator)
        XCTAssertEqual(state.effectiveState, .deliver)
        XCTAssertTrue(state.shouldSendDisplayedMarker)
        XCTAssertTrue(SavedMessageStatePolicy.shouldSendDisplayedMarker(conversationType: .regular))
    }

    func testSavedMamResultRoutesToSavedConversation() throws {
        let direct = try makeDirectSavedMessage(id: "saved-mam-1")
        let result = try makeMamResult(message: direct, archiveId: "archive-saved-1", queryId: "saved-query-1")

        let stored = try receiveSaved(try extractMamForwardedMessage(from: result))

        assertStoredAsSavedServiceConversation(stored)
        XCTAssertEqual(result.element(forName: "result")?.attributeStringValue(forName: "id"), "archive-saved-1")
    }

    func testSavedSentCarbonRoutesToSavedConversation() throws {
        let carbon = try makeCarbonSent(message: try makeDirectSavedMessage(id: "saved-carbon-sent-1"))

        let stored = try receiveSaved(try extractForwardedMessage(from: carbon, childName: "sent"))

        assertStoredAsSavedServiceConversation(stored)
        XCTAssertEqual(stored.messageId, "saved-carbon-sent-1")
    }

    func testSavedReceivedCarbonDoesNotCreateWrongConversation() throws {
        let receivedMessage = try makeDirectSavedMessage(
            from: favoritesJid,
            to: ownerResource,
            body: "Saved service echo",
            id: "saved-carbon-received-1"
        )
        let carbon = try makeCarbonReceived(message: receivedMessage)

        let stored = try receiveSaved(try extractForwardedMessage(from: carbon, childName: "received"))

        assertStoredAsSavedServiceConversation(stored)
        XCTAssertEqual(try WRealm.safe().objects(MessageStorageItem.self).filter("opponent != %@", favoritesJid).count, 0)
    }

    func testSavedMamAndCarbonGeolocPayloadsParseSameReference() throws {
        let body = "geo:56.838011,60.597465"
        let live = try makeDirectSavedMessage(
            body: body,
            id: "saved-geoloc-live-1",
            children: geolocReferenceXML(body: body)
        )
        let mam = try extractMamForwardedMessage(
            from: try makeMamResult(message: live, archiveId: "archive-geoloc-1", queryId: "saved-geoloc")
        )
        let carbon = try extractForwardedMessage(
            from: try makeCarbonReceived(message: live),
            childName: "received"
        )

        let liveReference = try XCTUnwrap(parseReferences(live, primary: "live", jid: favoritesJid, owner: owner).first)
        let mamReference = try XCTUnwrap(parseReferences(mam, primary: "mam", jid: favoritesJid, owner: owner).first)
        let carbonReference = try XCTUnwrap(parseReferences(carbon, primary: "carbon", jid: favoritesJid, owner: owner).first)

        XCTAssertEqual(liveReference.kind, .geoloc)
        XCTAssertEqual(mamReference.kind, .geoloc)
        XCTAssertEqual(carbonReference.kind, .geoloc)
        XCTAssertEqual(liveReference.url, body)
        XCTAssertEqual(mamReference.url, body)
        XCTAssertEqual(carbonReference.url, body)
    }

    func testSavedSyncLastMessageUsesFavoritesServiceJidAndSavedType() throws {
        let direct = try makeDirectSavedMessage(id: "saved-sync-last-1")
        let sync = try makeSyncConversation(
            jid: favoritesJid,
            type: savedConversationType,
            lastMessage: direct
        )

        XCTAssertEqual(sync.attributeStringValue(forName: "jid"), favoritesJid)
        XCTAssertEqual(sync.attributeStringValue(forName: "type"), savedConversationType)
        XCTAssertNotNil(sync.element(forName: "last-message")?.element(forName: "message"))
    }
}

final class ComposerMentionsTests: XCTestCase {

    private final class MessagesPanelDelegateSpy: ChatViewMessagesPanelDelegate {
        private(set) var closeCount = 0
        private(set) var indicatorTouchCount = 0

        func messagesPanelOnClose() {
            closeCount += 1
        }

        func messagesPanelOnIndicatorTouch() {
            indicatorTouchCount += 1
        }
    }

    private enum SelectionPanelAction: Equatable {
        case delete
        case share
        case copy
        case reply
        case forward
        case close
        case edit
    }

    private final class SelectionPanelActionDelegateSpy: MessagesSelectionPanelActionDelegate {
        private(set) var actions: [SelectionPanelAction] = []

        func selectionPanel(onClose panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.close)
        }

        func selectionPanel(onDelete panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.delete)
        }

        func selectionPanel(onCopy panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.copy)
        }

        func selectionPanel(onShare panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.share)
        }

        func selectionPanel(onReply panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.reply)
        }

        func selectionPanel(onForward panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.forward)
        }

        func selectionPanel(onEdit panel: ModernXabberInputView.SelectionPanel) {
            actions.append(.edit)
        }
    }

    private func baseAttributes() -> [NSAttributedString.Key: Any] {
        [
            .font: UIFont.systemFont(ofSize: 14, weight: .regular),
            .foregroundColor: UIColor.label
        ]
    }

    private func mentionAttributes(for entity: ComposerMentionEntity) -> [NSAttributedString.Key: Any] {
        var attributes = baseAttributes()
        attributes[.composerMention] = entity
        attributes[.foregroundColor] = UIColor.systemBlue
        return attributes
    }

    func testMentionTriggerDetectionFindsActiveQuery() {
        let text = NSAttributedString(string: "Hello @Sha", attributes: baseAttributes())

        let query = ComposerMentionQueryDetector.activeQuery(
            in: text,
            selectedRange: NSRange(location: text.length, length: 0)
        )

        XCTAssertEqual(query?.query, "Sha")
        XCTAssertEqual(query?.triggerRange, NSRange(location: 6, length: 1))
        XCTAssertEqual(query?.replacementRange, NSRange(location: 6, length: 4))
    }

    func testMentionTriggerDetectionSupportsBareAtSymbol() {
        let text = NSAttributedString(string: "@", attributes: baseAttributes())

        let query = ComposerMentionQueryDetector.activeQuery(
            in: text,
            selectedRange: NSRange(location: text.length, length: 0)
        )

        XCTAssertEqual(query?.query, "")
        XCTAssertEqual(query?.triggerRange, NSRange(location: 0, length: 1))
        XCTAssertEqual(query?.replacementRange, NSRange(location: 0, length: 1))
    }

    func testInsertMentionAddsDecoratedTokenAndTrailingSpace() {
        let text = NSAttributedString(string: "Hello @sh", attributes: baseAttributes())
        let entity = ComposerMentionEntity(
            memberId: "123333",
            nickname: "Shadow_of_my_moon",
            uri: "xmpp:trio@example.com?members;id=123333",
            node: "https://xabber.com/protocol/groupchat",
            jid: "shadow@example.com"
        )

        let result = ComposerMentionEditor.insertMention(
            in: text,
            replacementRange: NSRange(location: 6, length: 3),
            entity: entity,
            baseAttributes: baseAttributes(),
            mentionAttributes: mentionAttributes(for: entity)
        )

        XCTAssertEqual(result.attributedText.string, "Hello Shadow_of_my_moon ")
        XCTAssertEqual(result.selectedRange.location, result.attributedText.length)
        XCTAssertEqual(ComposerMentionEditor.mentionRanges(in: result.attributedText), [NSRange(location: 6, length: 17)])
    }

    func testEditingInsideMentionRemovesWholeMentionEntity() {
        let entity = ComposerMentionEntity(
            memberId: "123333",
            nickname: "Shadow",
            uri: "xmpp:trio@example.com?members;id=123333",
            node: "https://xabber.com/protocol/groupchat",
            jid: "shadow@example.com"
        )
        let attributed = NSMutableAttributedString(string: "Hello ", attributes: baseAttributes())
        attributed.append(NSAttributedString(string: "Shadow", attributes: mentionAttributes(for: entity)))
        attributed.append(NSAttributedString(string: " world", attributes: baseAttributes()))

        let mutation = ComposerMentionEditor.mutationForEditing(
            attributedText: attributed,
            range: NSRange(location: 8, length: 1),
            replacementText: "",
            baseAttributes: baseAttributes()
        )

        XCTAssertEqual(mutation?.attributedText.string, "Hello  world")
        XCTAssertTrue(ComposerMentionEditor.mentionRanges(in: mutation?.attributedText ?? NSAttributedString()).isEmpty)
    }

    func testMentionPayloadUsesEscapedOffsets() {
        let entity = ComposerMentionEntity(
            memberId: "123333",
            nickname: "Shadow",
            uri: "xmpp:trio@example.com?members;id=123333",
            node: "https://xabber.com/protocol/groupchat",
            jid: "shadow@example.com"
        )
        let attributed = NSMutableAttributedString(string: "A & B ", attributes: baseAttributes())
        attributed.append(NSAttributedString(string: "Shadow", attributes: mentionAttributes(for: entity)))

        let payload = ComposerMentionSerializer.payload(from: attributed)

        XCTAssertEqual(payload.body, "A & B Shadow")
        XCTAssertEqual(payload.references.count, 1)
        XCTAssertEqual(payload.references.first?.begin, 10)
        XCTAssertEqual(payload.references.first?.end, 16)
        XCTAssertEqual(payload.references.first?.kind, .mention)
        XCTAssertEqual(payload.references.first?.metadata?["uri"] as? String, "xmpp:trio@example.com?members;id=123333")
    }

    func testChatBubbleMentionRenderingUsesTintedLinkWithoutFilledBackground() {
        let reference = MessageReferenceStorageItem()
        reference.kind = .mention
        reference.begin = 6
        reference.end = 13
        reference.metadata = [
            "uri": "xmpp:trio@example.com?members;id=123333",
            "node": "https://xabber.com/protocol/groupchat",
            "memberId": "123333",
            "nickname": "@Shadow"
        ]

        let item = MessageStorageItem()
        item.body = "Hello @Shadow"
        item.owner = "owner@example.com"
        item.references.append(reference)

        let attributed = item.createRefBody(baseAttributes())
        let mentionRange = NSRange(location: 6, length: 7)

        XCTAssertEqual(
            attributed.attribute(.link, at: mentionRange.location, effectiveRange: nil) as? String,
            "xmpp:trio@example.com?members;id=123333"
        )
        XCTAssertNotNil(attributed.attribute(.foregroundColor, at: mentionRange.location, effectiveRange: nil))
        XCTAssertNil(attributed.attribute(.backgroundColor, at: mentionRange.location, effectiveRange: nil))
    }

    func testCreateReferencesBuildsWebGroupMentionDecorationXml() {
        let reference = MessageReferenceStorageItem()
        reference.kind = .mention
        reference.begin = 6
        reference.end = 13
        reference.metadata = [
            "uri": "xmpp:trio@example.com?members;id=123333",
            "node": "https://xabber.com/protocol/groupchat",
            "memberId": "123333",
            "nickname": "@Shadow"
        ]

        let item = MessageStorageItem()
        item.body = "Hello @Shadow"
        item.owner = "owner@example.com"
        item.references.append(reference)

        let xml = item.createReferences()

        XCTAssertEqual(xml.count, 1)
        XCTAssertEqual(xml.first?.attributeStringValue(forName: "type"), "decoration")
        XCTAssertNil(xml.first?.element(forName: "mention", xmlns: "https://xabber.com/protocol/markup"))
        XCTAssertEqual(xml.first?.element(forName: "link", xmlns: "https://xabber.com/protocol/markup")?.stringValue, "xmpp:trio@example.com?members;id=123333")
    }

    func testCreateMentionsElementBuildsWebGroupMentionsXml() {
        let firstReference = MessageReferenceStorageItem()
        firstReference.kind = .mention
        firstReference.metadata = [
            "uri": "xmpp:trio@example.com?members;id=123333",
            "memberId": "123333"
        ]

        let duplicateReference = MessageReferenceStorageItem()
        duplicateReference.kind = .mention
        duplicateReference.metadata = [
            "uri": "xmpp:trio@example.com?members;id=123333"
        ]

        let item = MessageStorageItem()
        item.references.append(firstReference)
        item.references.append(duplicateReference)

        let mentions = item.createMentionsElement()

        XCTAssertEqual(mentions?.name, "mentions")
        XCTAssertEqual(mentions?.xmlns(), "https://xabber.com/protocol/groups")
        XCTAssertEqual(mentions?.elements(forName: "user").count, 1)
        XCTAssertEqual(mentions?.element(forName: "user")?.attributeStringValue(forName: "id"), "123333")
    }

    func testParseReferencesSupportsCanonicalMentionElement() throws {
        let xml = """
        <message type='groupchat' from='trio@example.com' to='owner@example.com'>
          <body>Hello @Shadow</body>
          <reference xmlns='https://xabber.com/protocol/references' type='decoration' begin='6' end='13'>
            <mention xmlns='https://xabber.com/protocol/markup' node='https://xabber.com/protocol/groupchat'>xmpp:trio@example.com?id=123333</mention>
          </reference>
        </message>
        """
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        let root = try XCTUnwrap(document.rootElement())
        let message = XMPPMessage(from: root)

        let references = parseReferences(message, primary: "test-primary", jid: "trio@example.com", owner: "owner@example.com")
        let first = try XCTUnwrap(references.first)

        XCTAssertEqual(references.count, 1)
        XCTAssertEqual(first.kind, .mention)
        XCTAssertEqual(first.begin, 6)
        XCTAssertEqual(first.end, 13)
        XCTAssertEqual(first.metadata?["uri"] as? String, "xmpp:trio@example.com?id=123333")
        XCTAssertEqual(first.metadata?["node"] as? String, "https://xabber.com/protocol/groupchat")
        XCTAssertEqual(first.metadata?["nickname"] as? String, "@Shadow")
    }

    func testParseReferencesSupportsWebClientGroupMentionStanza() throws {
        let xml = """
        <message id='7c47df87-42f4-438d-8fde-636a084afbfd' to='ios-mentions-group-test-01@redsolution.com' type='chat' xmlns='jabber:client'>
