final class EncryptedChatSendAvailabilityPolicyTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "EncryptedChatSendAvailabilityPolicyTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        super.tearDown()
    }

    func testOwnUntrustedDeviceBlocksInput() {
        let availability = OmemoSendAvailabilityPolicy.evaluate(
            conversationType: .omemo,
            ownDeviceStates: [.trusted, .unknown],
            contactDeviceStates: [.trusted]
        )

        XCTAssertEqual(availability, .blockedByOwnUntrustedDevices)
        XCTAssertFalse(availability.canSend)
    }

    func testMixedContactDevicesAllowSendingWithWarning() {
        let availability = OmemoSendAvailabilityPolicy.evaluate(
            conversationType: .omemo,
            ownDeviceStates: [.trusted],
            contactDeviceStates: [.trusted, .unknown, .distrusted]
        )

        XCTAssertEqual(availability, .canSendWithUntrustedContactDeviceWarning)
        XCTAssertTrue(availability.canSend)
        XCTAssertTrue(availability.requiresUntrustedContactDeviceWarning)
    }

    func testContactDevicesWithZeroTrustedDevicesBlockInput() {
        let availability = OmemoSendAvailabilityPolicy.evaluate(
            conversationType: .omemo,
            ownDeviceStates: [.trusted],
            contactDeviceStates: [.unknown, .distrusted]
        )

        XCTAssertEqual(availability, .blockedByNoTrustedContactDevices)
        XCTAssertFalse(availability.canSend)
    }

    func testFullyTrustedDeviceStateAllowsSendingWithoutWarning() {
        let availability = OmemoSendAvailabilityPolicy.evaluate(
            conversationType: .omemo,
            ownDeviceStates: [.trusted],
            contactDeviceStates: [.trusted, .trusted]
        )

        XCTAssertEqual(availability, .canSend)
        XCTAssertTrue(availability.canSend)
        XCTAssertFalse(availability.requiresUntrustedContactDeviceWarning)
    }

    func testWarningMetadataPersistsAndResolvesText() throws {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.configureOutgoingMessage(
            "encrypted",
            legacy: "encrypted",
            messageId: "warning-message",
            owner: "alice@example.org",
            opponent: "bob@example.org",
            references: [],
            inlineForwards: []
        )

        try realm.write {
            message.markOmemoUntrustedContactDevicesWarning()
            realm.add(message, update: .modified)
        }

        let stored = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: message.primary))
        XCTAssertEqual(stored.messageWarningText, MessageStorageItem.omemoUntrustedContactDevicesWarningText)
    }
}

final class OmemoSessionLifecycleTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!
    private var owners: [String] = []

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "OmemoSessionLifecycleTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        owners.forEach { OmemoManager.remove(for: $0, commitTransaction: true) }
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        owners.removeAll()
        super.tearDown()
    }

    func testExistingSessionIsReusedForSecondOutgoingMessage() throws {
        let owner = uniqueJid("alice")
        let recipient = uniqueJid("bob")
        let recipientDeviceId = 2201
        let manager = try makeManager(owner: owner, deviceId: 1101)
        try addRemoteBundle(
            to: manager,
            jid: recipient,
            deviceId: recipientDeviceId,
            trustState: .trusted
        )

        let first = try XCTUnwrap(try manager.encryptMessage(message: envelope("one"), to: recipient))
        try deleteCachedBundle(owner: owner, jid: recipient, deviceId: recipientDeviceId)
        let second = try XCTUnwrap(try manager.encryptMessage(message: envelope("two"), to: recipient))

        XCTAssertEqual(keyExchangeFlag(in: first, jid: recipient, deviceId: recipientDeviceId), true)
        XCTAssertNotNil(keyExchangeFlag(in: second, jid: recipient, deviceId: recipientDeviceId))
        XCTAssertEqual(try storedSessionCount(owner: owner, jid: recipient), 1)
    }

    func testUnknownRecipientDevicesAreNotEncryptedTo() throws {
        let owner = uniqueJid("alice")
        let recipient = uniqueJid("bob")
        let manager = try makeManager(owner: owner, deviceId: 1102)
        try addRemoteBundle(
            to: manager,
            jid: recipient,
            deviceId: 2202,
            trustState: .unknown
        )

        XCTAssertThrowsError(try manager.encryptMessage(message: envelope("blocked"), to: recipient)) { error in
            XCTAssertEqual(error as? OmemoManagerError, .noTrustedRecipientDevices)
        }
        XCTAssertEqual(try storedSessionCount(owner: owner, jid: recipient), 0)
    }

    func testMixedRecipientDevicesOnlyEncryptsToTrustedDevices() throws {
        let owner = uniqueJid("alice")
        let recipient = uniqueJid("bob")
        let trustedDeviceId = 2205
        let untrustedDeviceId = 2206
        let manager = try makeManager(owner: owner, deviceId: 1105)
        try addRemoteBundle(
            to: manager,
            jid: recipient,
            deviceId: trustedDeviceId,
            trustState: .trusted
        )
        try addRemoteBundle(
            to: manager,
            jid: recipient,
            deviceId: untrustedDeviceId,
            trustState: .unknown
        )

        let encrypted = try XCTUnwrap(try manager.encryptMessage(message: envelope("mixed"), to: recipient))

        XCTAssertNotNil(keyExchangeFlag(in: encrypted, jid: recipient, deviceId: trustedDeviceId))
        XCTAssertNil(keyExchangeFlag(in: encrypted, jid: recipient, deviceId: untrustedDeviceId))
    }

    func testIdentityChangeMarksDeviceAndDeletesSession() throws {
        let owner = uniqueJid("alice")
        let recipient = uniqueJid("bob")
        let deviceId: Int32 = 2203
        let store = XabberAxolotlStorage(withOwner: owner)
        let oldIdentity = Data([1, 2, 3, 4])
        let newIdentity = Data([4, 3, 2, 1])
        let address = SignalAddress(name: recipient, deviceId: deviceId)
        let realm = try WRealm.safe()

        try realm.write {
            let device = SignalDeviceStorageItem()
            device.owner = owner
            device.jid = recipient
            device.deviceId = Int(deviceId)
            device.primary = SignalDeviceStorageItem.genPrimary(owner: owner, jid: recipient, deviceId: Int(deviceId))
            device.state = .trusted
            device.isTrustedByCertificate = true
            device.trustedByDeviceId = "manual"
            realm.add(device, update: .modified)

            let session = SessionRecordStorageItem()
            session.owner = owner
            session.jid = recipient
            session.deviceId = Int(deviceId)
            session.primary = SessionRecordStorageItem.genPrimary(owner, for: address)
            session.record = Data([9, 9, 9])
            realm.add(session, update: .modified)

            let trusted = SignalTrustedIdentityStoreageItem()
            trusted.owner = owner
            trusted.jid = recipient
            trusted.deviceId = Int(deviceId)
            trusted.primary = SignalTrustedIdentityStoreageItem.genPrimary(owner, for: address)
            trusted.identity = oldIdentity
            realm.add(trusted, update: .modified)
        }

        XCTAssertFalse(store.isTrustedIdentity(address, identityKey: newIdentity))

        let updatedDevice = try XCTUnwrap(realm.object(
            ofType: SignalDeviceStorageItem.self,
            forPrimaryKey: SignalDeviceStorageItem.genPrimary(owner: owner, jid: recipient, deviceId: Int(deviceId))
        ))
        XCTAssertEqual(updatedDevice.state, .fingerprintChanged)
        XCTAssertFalse(updatedDevice.isTrustedByCertificate)
        XCTAssertNil(updatedDevice.trustedByDeviceId)
        XCTAssertEqual(updatedDevice.fingerprint, newIdentity.formattedFingerprint())
        XCTAssertNil(realm.object(ofType: SessionRecordStorageItem.self, forPrimaryKey: SessionRecordStorageItem.genPrimary(owner, for: address)))
        XCTAssertNil(realm.object(ofType: SignalTrustedIdentityStoreageItem.self, forPrimaryKey: SignalTrustedIdentityStoreageItem.genPrimary(owner, for: address)))
    }

    func testDecryptMissingRecipientKeyThrowsWithoutCrash() throws {
        let owner = uniqueJid("alice")
        let sender = uniqueJid("bob")
        let manager = try makeManager(owner: owner, deviceId: 1104)
        let message = try makeMessage(xml: """
        <message from='\(sender)/ios' to='\(owner)' id='missing-key'>
          <encrypted xmlns='urn:xmpp:omemo:2'>
            <header sid='2204'>
              <keys jid='\(owner)'/>
            </header>
            <payload>AA==</payload>
          </encrypted>
        </message>
        """)

        XCTAssertThrowsError(try manager.decryptMessage(message)) { error in
            XCTAssertEqual(error as? OmemoManagerError, .missingRecipientKey)
        }
    }

    private func uniqueJid(_ prefix: String) -> String {
        let jid = "\(prefix)-\(UUID().uuidString.lowercased())@example.com"
        owners.append(jid)
        return jid
    }

    private func makeManager(owner: String, deviceId: Int) throws -> OmemoManager {
        let manager = OmemoManager(withOwner: owner)
        try manager.localStore.create(for: deviceId, context: manager.signalContext)
        return manager
    }

    private func addRemoteBundle(
        to manager: OmemoManager,
        jid: String,
        deviceId: Int,
        trustState: SignalDeviceStorageItem.TrustState
    ) throws {
        let keyHelper = try XCTUnwrap(SignalKeyHelper(context: manager.signalContext))
        let identity = try XCTUnwrap(keyHelper.generateIdentityKeyPair())
        let signedPreKey = try XCTUnwrap(keyHelper.generateSignedPreKey(withIdentity: identity, signedPreKeyId: UInt32(deviceId + 100)))
        let preKeys = keyHelper.generatePreKeys(withStartingPreKeyId: UInt(deviceId + 1), count: 3)
        let realm = try WRealm.safe()

        try realm.write {
            let identityItem = SignalIdentityStorageItem()
            identityItem.owner = manager.owner
            identityItem.jid = jid
            identityItem.deviceId = deviceId
            identityItem.primary = SignalIdentityStorageItem.genRpimary(owner: manager.owner, jid: jid, deviceId: deviceId)
            identityItem.identityKey = identity.publicKey.base64EncodedString()
            identityItem.signedPreKey = signedPreKey.keyPair!.publicKey.base64EncodedString()
            identityItem.signedPreKeySignature = signedPreKey.signature.base64EncodedString()
            identityItem.signedPreKeyId = Int(signedPreKey.preKeyId)
            realm.add(identityItem, update: .modified)

            let device = SignalDeviceStorageItem()
            device.owner = manager.owner
            device.jid = jid
            device.deviceId = deviceId
            device.primary = SignalDeviceStorageItem.genPrimary(owner: manager.owner, jid: jid, deviceId: deviceId)
            device.state = trustState
            device.fingerprint = identity.publicKey.formattedFingerprint()
            realm.add(device, update: .modified)

            preKeys.forEach { preKey in
                let preKeyItem = SignalPreKeysStorageItem()
                preKeyItem.owner = manager.owner
                preKeyItem.jid = jid
                preKeyItem.deviceId = deviceId
                preKeyItem.pkId = Int(preKey.preKeyId)
                preKeyItem.preKey = preKey.keyPair!.publicKey.base64EncodedString()
                preKeyItem.keyUUID = UUID().uuidString
                preKeyItem.primary = SignalPreKeysStorageItem.genPrimary(keyUUID: preKeyItem.keyUUID)
                realm.add(preKeyItem, update: .modified)
            }
        }
    }

    private func envelope(_ body: String) -> String {
        """
        <envelope xmlns='urn:xmpp:sce:1'>
          <content>
            <body xmlns='jabber:client'>\(body)</body>
          </content>
          <rpad>padding</rpad>
        </envelope>
        """
    }

    private func keyExchangeFlag(in encrypted: DDXMLElement, jid: String, deviceId: Int) -> Bool? {
        encrypted
            .element(forName: "header")?
            .elements(forName: "keys")
            .first(where: { $0.attributeStringValue(forName: "jid") == jid })?
            .elements(forName: "key")
            .first(where: { $0.attributeIntegerValue(forName: "rid") == deviceId })?
            .attributeBoolValue(forName: "kex")
    }

    private func deleteCachedBundle(owner: String, jid: String, deviceId: Int) throws {
        let realm = try WRealm.safe()
        let identityPrimary = SignalIdentityStorageItem.genRpimary(owner: owner, jid: jid, deviceId: deviceId)
        let preKeys = realm
            .objects(SignalPreKeysStorageItem.self)
            .filter("owner == %@ AND jid == %@ AND deviceId == %@", owner, jid, deviceId)
        try realm.write {
            if let identity = realm.object(ofType: SignalIdentityStorageItem.self, forPrimaryKey: identityPrimary) {
                realm.delete(identity)
            }
            realm.delete(preKeys)
        }
    }

    private func storedSessionCount(owner: String, jid: String) throws -> Int {
        try WRealm.safe()
            .objects(SessionRecordStorageItem.self)
            .filter("owner == %@ AND jid == %@", owner, jid)
            .count
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        return XMPPMessage(from: document.rootElement()!)
    }
}

final class XEPTrustProtocolTests: XCTestCase {

    func testRequestBuilderAndParserPreserveTargetDevice() {
        let trust = XEPTrustEnvelope.makeTrustElement(
            sid: "sid-1",
            expires: 4_102_444_800,
            timestamp: 1_709_270_416,
            kind: .request(deviceId: 1001, targetDeviceId: 2002)
        )
        let message = XMPPMessage(type: "chat", to: XMPPJID(string: "romeo@example.org/phone"))
        message.addChild(trust)

        XCTAssertEqual(trust.xmlns(), XEPTrustEnvelope.xmlns)
        XCTAssertEqual(trust.attributeStringValue(forName: "sid"), "sid-1")
        XCTAssertEqual(trust.element(forName: "request")?.attributeStringValue(forName: "device-id"), "1001")
        XCTAssertEqual(trust.element(forName: "request")?.attributeStringValue(forName: "target-device-id"), "2002")

        guard let envelope = XEPTrustEnvelope.parse(from: message) else {
            return XCTFail("Expected XEP-TRUST request to parse")
        }
        XCTAssertEqual(envelope.sid, "sid-1")
        XCTAssertEqual(envelope.timestamp, 1_709_270_416)
        XCTAssertEqual(envelope.expires, 4_102_444_800)
        if case let .request(deviceId, targetDeviceId) = envelope.kind {
            XCTAssertEqual(deviceId, 1001)
            XCTAssertEqual(targetDeviceId, 2002)
        } else {
            XCTFail("Expected request envelope")
        }
    }

    func testCryptoPayloadStanzasRoundTripBase64Fields() {
        let message = XMPPMessage(type: "chat", to: XMPPJID(string: "romeo@example.org/phone"))
        message.addChild(XEPTrustEnvelope.makeTrustElement(
            sid: "sid-2",
            expires: 4_102_444_800,
            timestamp: 1_709_270_417,
            kind: .response(deviceId: 3003, ciphertext: "Y2lwaGVy", iv: "aXY=", hmac: "aG1hYw==")
        ))

        guard let envelope = XEPTrustEnvelope.parse(from: message) else {
            return XCTFail("Expected XEP-TRUST response to parse")
        }
        if case let .response(deviceId, ciphertext, iv, hmac) = envelope.kind {
            XCTAssertEqual(deviceId, 3003)
            XCTAssertEqual(ciphertext, "Y2lwaGVy")
            XCTAssertEqual(iv, "aXY=")
            XCTAssertEqual(hmac, "aG1hYw==")
        } else {
            XCTFail("Expected response envelope")
        }
    }

    func testAbortBuilderSupportsTimeoutReason() {
        let message = XMPPMessage(type: "chat", to: XMPPJID(string: "romeo@example.org/phone"))
        message.addChild(XEPTrustEnvelope.makeTrustElement(
            sid: "sid-timeout",
            expires: 4_102_444_800,
            timestamp: 1_709_270_418,
            kind: .abort(reason: .timeout)
        ))

        guard let envelope = XEPTrustEnvelope.parse(from: message) else {
            return XCTFail("Expected XEP-TRUST abort to parse")
        }
        if case let .abort(reason) = envelope.kind {
            XCTAssertEqual(reason, .timeout)
        } else {
            XCTFail("Expected abort envelope")
        }
    }

    func testXENForwardedTrustMessageExtractsInnerMessageAndValidatesOriginalFrom() throws {
        let outer = try makeMessage(xml: """
        <message from='relay.example.org' to='juliet@example.org/phone'>
          <notification xmlns='urn:xabber:xen:0'>
            <forwarded xmlns='urn:xmpp:forward:0'>
              <message from='romeo@example.org/watch' to='juliet@example.org/phone'>
                <trust xmlns='urn:xmpp:trust:0' sid='sid-xen' timestamp='1709270416' expires='4102444800'>
                  <request device-id='42'/>
                </trust>
              </message>
            </forwarded>
          </notification>
          <addresses xmlns='http://jabber.org/protocol/address'>
            <address type='ofrom' jid='romeo@example.org/watch'/>
          </addresses>
        </message>
        """)

        let extracted = XEPTrustForwardedExtractor.trustMessage(from: outer)

        guard let extracted else {
            return XCTFail("Expected XEN forwarded trust message to extract")
        }
        XCTAssertEqual(extracted.from?.full, "romeo@example.org/watch")
        XCTAssertEqual(XEPTrustEnvelope.parse(from: extracted)?.sid, "sid-xen")
    }

    func testXENForwardedTrustMessageRejectsMismatchedOriginalFrom() throws {
        let outer = try makeMessage(xml: """
        <message from='relay.example.org' to='juliet@example.org/phone'>
          <notification xmlns='urn:xabber:xen:0'>
            <forwarded xmlns='urn:xmpp:forward:0'>
              <message from='romeo@example.org/watch' to='juliet@example.org/phone'>
                <trust xmlns='urn:xmpp:trust:0' sid='sid-xen' timestamp='1709270416' expires='4102444800'>
                  <request device-id='42'/>
                </trust>
              </message>
            </forwarded>
          </notification>
          <addresses xmlns='http://jabber.org/protocol/address'>
            <address type='ofrom' jid='mallory@example.org/watch'/>
          </addresses>
        </message>
        """)

        XCTAssertNil(XEPTrustForwardedExtractor.trustMessage(from: outer))
    }

    func testTrustSharingCanonicalStringSortsContainersAndTypedEntriesDescending() {
        let older = DDXMLElement(name: "trusted-items")
        older.addAttribute(withName: "timestamp", stringValue: "1709270416")
        older.addChild(entry(name: "trust", timestamp: 1709270116, value: "ADASDAXCZX"))

        let newer = DDXMLElement(name: "trusted-items")
        newer.addAttribute(withName: "timestamp", stringValue: "1709270516")
        newer.addChild(entry(name: "distrust", timestamp: 1709270517, value: "REVOKED="))
        newer.addChild(entry(name: "trust", timestamp: 1709270518, value: "TRUSTED="))

        XCTAssertEqual(
            TrustSharingSignature.canonicalString(for: [older, newer]),
            "1709270516<trust:1709270518/TRUSTED=<distrust:1709270517/REVOKED=1709270416<trust:1709270116/ADASDAXCZX"
        )
    }

    func testTrustSharingCanonicalStringRejectsMissingTimestamps() {
        let trustedItems = DDXMLElement(name: "trusted-items")
        trustedItems.addChild(entry(name: "trust", timestamp: 1709270116, value: "ADASDAXCZX"))

        XCTAssertNil(TrustSharingSignature.canonicalString(for: [trustedItems]))
    }

    func testExpiredSessionCleanupPredicateDoesNotCrashAndMarksTimeout() throws {
        let previousConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "XEPTrustProtocolTests-\(name)")
        defer {
            Realm.Configuration.defaultConfiguration = previousConfiguration
        }

        let owner = "alice@example.org"
        let sid = "expired-sid"
        let realm = try WRealm.safe()
        try realm.write {
            let expired = VerificationSessionStorageItem()
            expired.owner = owner
            expired.ownerJid = owner
            expired.sid = sid
            expired.primary = VerificationSessionStorageItem.genPrimary(owner: owner, sid: sid)
            expired.jid = "bob@example.org"
            expired.peerBareJid = "bob@example.org"
            expired.state = .receivedRequest
            expired.role = .responder
            expired.expires = Date().timeIntervalSince1970 - 1
            realm.add(expired, update: .modified)

            let terminal = VerificationSessionStorageItem()
            terminal.owner = owner
            terminal.ownerJid = owner
            terminal.sid = "trusted-sid"
            terminal.primary = VerificationSessionStorageItem.genPrimary(owner: owner, sid: terminal.sid)
            terminal.state = .trusted
            terminal.expires = Date().timeIntervalSince1970 - 1
            realm.add(terminal, update: .modified)
        }

        AuthenticatedKeyExchangeManager.checkVerificationSessionsTTL()

        XCTAssertEqual(
            realm.object(ofType: VerificationSessionStorageItem.self, forPrimaryKey: VerificationSessionStorageItem.genPrimary(owner: owner, sid: sid))?.state,
            .timeout
        )
        XCTAssertEqual(
            realm.object(ofType: VerificationSessionStorageItem.self, forPrimaryKey: VerificationSessionStorageItem.genPrimary(owner: owner, sid: "trusted-sid"))?.state,
            .trusted
        )

        AuthenticatedKeyExchangeManager.checkVerificationSessionsTTL()
        XCTAssertEqual(
            realm.object(ofType: VerificationSessionStorageItem.self, forPrimaryKey: VerificationSessionStorageItem.genPrimary(owner: owner, sid: sid))?.state,
            .timeout
        )

        let deletedSid = "deleted-sid"
        try realm.write {
            let deleted = VerificationSessionStorageItem()
            deleted.owner = owner
            deleted.ownerJid = owner
            deleted.sid = deletedSid
            deleted.primary = VerificationSessionStorageItem.genPrimary(owner: owner, sid: deletedSid)
            deleted.jid = "bob@example.org"
            deleted.state = .receivedRequest
            deleted.expires = Date().timeIntervalSince1970 - 1
            realm.add(deleted, update: .modified)
            realm.delete(deleted)
        }

        AuthenticatedKeyExchangeManager.checkVerificationSessionsTTL()
        XCTAssertNil(realm.object(ofType: VerificationSessionStorageItem.self, forPrimaryKey: VerificationSessionStorageItem.genPrimary(owner: owner, sid: deletedSid)))
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        return XMPPMessage(from: document.rootElement()!)
    }

    private func entry(name: String, timestamp: Int64, value: String) -> DDXMLElement {
        let element = DDXMLElement(name: name, stringValue: value)
        element.addAttribute(withName: "timestamp", stringValue: String(timestamp))
        return element
    }
}

final class ModerationReportTests: XCTestCase {
    private func makeMessage(
        owner: String = "alice@test.xabber.org",
        opponent: String = "bob@example.org",
        conversationType: ClientSynchronizationManager.ConversationType = .regular
    ) -> MessageStorageItem {
        let message = MessageStorageItem()
        message.primary = "message-primary-\(UUID().uuidString)"
        message.owner = owner
        message.opponent = opponent
        message.messageId = "message-id"
        message.archivedId = "stanza-id"
        message.body = "Selected message text"
        message.date = Date(timeIntervalSince1970: 1_774_800_000)
        message.conversationType = conversationType
        return message
    }

    func testMessageReportWithoutExcerptDoesNotIncludeBody() {
        let message = makeMessage()

        let report = ModerationReportFactory.messageReport(
            message: message,
            reason: .harassmentOrBullying,
            comment: nil,
            includeMessageExcerpt: false
        )

        XCTAssertEqual(report.reportTargetType, .message)
        XCTAssertEqual(report.messageId, "message-id")
        XCTAssertEqual(report.forwardedAttachmentId, message.primary)
        XCTAssertEqual(report.forwardedAttachmentIds, [message.primary])
        XCTAssertFalse(report.includeMessageExcerpt)
        XCTAssertNil(report.messageExcerpt)
        XCTAssertFalse(report.abuseMessageBody.contains("Selected message text"))
        XCTAssertTrue(report.abuseMessageBody.contains("Forwarded attachment ID: \(message.primary)"))
    }

    func testMessageReportWithExcerptIncludesOnlySelectedMessageBody() {
        let message = makeMessage()

        let report = ModerationReportFactory.messageReport(
            message: message,
            reason: .hateSpeech,
            comment: "extra context",
            includeMessageExcerpt: true
        )

        XCTAssertTrue(report.includeMessageExcerpt)
        XCTAssertEqual(report.messageExcerpt, "Selected message text")
        XCTAssertEqual(report.comment, "extra context")
        XCTAssertTrue(report.abuseMessageBody.contains("Message excerpt:\nSelected message text"))
        XCTAssertTrue(report.abuseMessageBody.contains("Reporter comment:\nextra context"))
    }

    func testUserAndRoomReportsContainTargetJids() {
        let userReport = ModerationReportFactory.userReport(
            owner: "alice@test.xabber.org",
            reportedUserJid: "bob@example.org",
            roomJid: "room@muc.example.org",
            conversationId: "room@muc.example.org",
            reason: .impersonation,
            comment: nil
        )
        let roomReport = ModerationReportFactory.roomReport(
            owner: "alice@test.xabber.org",
            roomJid: "room@muc.example.org",
            reason: .spamScamOrPhishing,
            comment: nil
        )

        XCTAssertEqual(userReport.reportTargetType, .user)
        XCTAssertEqual(userReport.reportedUserJid, "bob@example.org")
        XCTAssertEqual(userReport.roomJid, "room@muc.example.org")
        XCTAssertEqual(roomReport.reportTargetType, .room)
        XCTAssertEqual(roomReport.roomJid, "room@muc.example.org")
    }

    func testUserReportBodyIsHumanReadableInsteadOfJSON() {
        let report = ModerationReportFactory.userReport(
            owner: "alice@test.xabber.org",
            reportedUserJid: "bob@example.org",
            roomJid: nil,
            conversationId: "bob@example.org",
            reason: .hateSpeech,
            comment: nil
        )
        let body = report.abuseMessageBody

        XCTAssertTrue(body.contains("Moderation report\n\n"))
        XCTAssertTrue(body.contains("Target type: User"))
        XCTAssertTrue(body.contains("Reported user JID: bob@example.org"))
        XCTAssertTrue(body.contains("Reporter account JID: alice@test.xabber.org"))
        XCTAssertTrue(body.contains("Conversation ID: bob@example.org"))
        XCTAssertTrue(body.contains("Server domain: example.org"))
        XCTAssertTrue(body.contains("Reason: Hate speech"))
        XCTAssertTrue(body.contains("Created at:"))
        XCTAssertTrue(body.contains("Platform: iOS"))
        XCTAssertTrue(body.contains("App version:"))
        XCTAssertTrue(body.contains("Report ID:"))
        XCTAssertFalse(body.contains("{"))
        XCTAssertFalse(body.contains("}"))
        XCTAssertFalse(body.contains("\"reportTargetType\""))
        XCTAssertTrue(report.jsonString.contains("\"reportTargetType\""))
    }

    func testRoomMessageAndMediaReportBodiesIncludeTargetMetadata() {
        let roomReport = ModerationReportFactory.roomReport(
            owner: "alice@test.xabber.org",
            roomJid: "room@muc.example.org",
            reason: .spamScamOrPhishing,
            comment: nil
        )
        XCTAssertTrue(roomReport.abuseMessageBody.contains("Target type: Room"))
        XCTAssertTrue(roomReport.abuseMessageBody.contains("Room JID: room@muc.example.org"))

        let message = makeMessage()
        let messageReport = ModerationReportFactory.messageReport(
            message: message,
            reason: .harassmentOrBullying,
            comment: nil,
            includeMessageExcerpt: false
        )
        XCTAssertTrue(messageReport.abuseMessageBody.contains("Target type: Message"))
        XCTAssertTrue(messageReport.abuseMessageBody.contains("Message ID: message-id"))
        XCTAssertTrue(messageReport.abuseMessageBody.contains("Forwarded attachment ID: \(message.primary)"))
        XCTAssertTrue(messageReport.abuseMessageBody.contains("Stanza ID: stanza-id"))
        XCTAssertTrue(messageReport.abuseMessageBody.contains("Message timestamp:"))

        let reference = MessageReferenceStorageItem()
        reference.primary = "reference-primary"
        reference.messageId = message.primary
        reference.owner = message.owner
        reference.jid = message.opponent
        reference.kind = .media
        reference.mimeType = MimeIconTypes.image.rawValue
        reference.url = "https://example.org/media/image.png"
        let mediaReport = ModerationReportFactory.mediaReport(
            message: message,
            reference: reference,
            attachment: nil,
            owner: message.owner,
            conversationJid: message.opponent,
            conversationType: .regular,
            reason: .sexualContentOrNudity,
            comment: nil,
            includeMessageExcerpt: false
        )
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("Target type: Media"))
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("Attachment ID: reference-primary"))
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("Media type: media"))
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("MIME type: image"))
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("Media URL: https://example.org/media/image.png"))
        XCTAssertTrue(mediaReport.abuseMessageBody.contains("Media identifier:"))
        XCTAssertTrue(mediaReport.forwardedAttachmentIds.isEmpty)
    }

    func testMediaReportIncludesAttachmentMetadataWithoutFileUpload() {
        let message = makeMessage()
        let reference = MessageReferenceStorageItem()
        reference.primary = "reference-primary"
        reference.messageId = message.primary
        reference.owner = message.owner
        reference.jid = message.opponent
        reference.kind = .media
        reference.mimeType = MimeIconTypes.image.rawValue
        reference.url = "https://example.org/media/image.png"

        let report = ModerationReportFactory.mediaReport(
            message: message,
            reference: reference,
            attachment: nil,
            owner: message.owner,
            conversationJid: message.opponent,
            conversationType: .regular,
            reason: .sexualContentOrNudity,
            comment: nil,
            includeMessageExcerpt: false
        )

        XCTAssertEqual(report.reportTargetType, .media)
        XCTAssertEqual(report.attachmentId, "reference-primary")
        XCTAssertEqual(report.mediaType, MessageReferenceStorageItem.Kind.media.rawValue)
        XCTAssertEqual(report.mimeType, MimeIconTypes.image.rawValue)
        XCTAssertEqual(report.mediaUrl, "https://example.org/media/image.png")
        XCTAssertNotNil(report.mediaUrlHashOrIdentifier)
        XCTAssertTrue(report.abuseMessageBody.contains("Media URL: https://example.org/media/image.png"))
        XCTAssertNil(report.messageExcerpt)
    }

    func testLocalHideMarksMessageWithoutDeletingBody() throws {
        let previousConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "ModerationReportTests-\(name)")
        defer {
            Realm.Configuration.defaultConfiguration = previousConfiguration
        }

        let realm = try WRealm.safe()
        let message = makeMessage()
        try realm.write {
            realm.add(message)
        }

        let report = ModerationReportFactory.messageReport(
            message: message,
            reason: .violenceOrThreats,
            comment: nil,
            includeMessageExcerpt: false
        )

        ModerationReportLocalStateWriter.record(report: report, state: .submitted, hideLocally: true)

        let stored = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: message.primary))
        XCTAssertTrue(stored.isLocallyHiddenByReport)
        XCTAssertEqual(stored.localReportState, ModerationLocalReportState.submitted.rawValue)
        XCTAssertEqual(stored.body, "Selected message text")
        XCTAssertFalse(stored.isDeleted)
    }
}

final class VoiceMessagePlaybackCoordinatorTests: XCTestCase {
    private var downloader: FakeVoiceMessageDownloader!
    private var player: FakeVoiceMessagePlayer!
    private var coordinator: VoiceMessagePlaybackCoordinator!
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "VoiceMessagePlaybackCoordinatorTests-\(name)")
        downloader = FakeVoiceMessageDownloader()
        player = FakeVoiceMessagePlayer()
        coordinator = VoiceMessagePlaybackCoordinator(downloader: downloader, player: player)
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        coordinator = nil
        player = nil
        downloader = nil
        super.tearDown()
    }

    func testNotDownloadedTapStartsDownload() {
        let descriptor = makeDescriptor(primary: "voice-1", downloaded: false)

        coordinator.handleTap(descriptor)

        XCTAssertEqual(downloader.startedPrimaries, ["voice-1"])
        XCTAssertEqual(coordinator.state(for: descriptor), .downloading(progress: 0))
    }

    func testVisibleDownloadsRunNewestToOldestOneAtATime() {
        let old = makeDescriptor(primary: "old", sentDate: Date(timeIntervalSince1970: 1))
        let new = makeDescriptor(primary: "new", sentDate: Date(timeIntervalSince1970: 2))

        coordinator.setVisibleVoiceMessages([old, new])

        XCTAssertEqual(downloader.startedPrimaries, ["new"])
        XCTAssertEqual(coordinator.state(for: old), .queued)
        downloader.completeSuccess(primary: "new")
        drainMainQueue()

        XCTAssertEqual(downloader.startedPrimaries, ["new", "old"])
        XCTAssertEqual(coordinator.state(for: old), .downloading(progress: 0))
    }

    func testLeavingVisibilityRemovesQueuedDownloadBeforeStart() {
        let old = makeDescriptor(primary: "old", sentDate: Date(timeIntervalSince1970: 1))
        let new = makeDescriptor(primary: "new", sentDate: Date(timeIntervalSince1970: 2))

        coordinator.setVisibleVoiceMessages([old, new])
        coordinator.setVisibleVoiceMessages([new])
        downloader.completeSuccess(primary: "new")
        drainMainQueue()

        XCTAssertEqual(downloader.startedPrimaries, ["new"])
        XCTAssertEqual(coordinator.state(for: old), .notDownloaded)
    }

    func testActiveCancelStopsDownloadAndReturnsToNotDownloaded() {
        let descriptor = makeDescriptor(primary: "voice-1")

        coordinator.handleTap(descriptor)
        coordinator.handleTap(descriptor)

        XCTAssertTrue(downloader.tasks["voice-1"]?.cancelCalled ?? false)
        XCTAssertEqual(coordinator.state(for: descriptor), .notDownloaded)
    }

    func testFailedRetryStartsFreshDownload() {
        let descriptor = makeDescriptor(primary: "voice-1")

        coordinator.handleTap(descriptor)
        downloader.completeFailure(primary: "voice-1")
        drainMainQueue()
        coordinator.handleTap(descriptor)

        XCTAssertEqual(downloader.startedPrimaries, ["voice-1", "voice-1"])
        XCTAssertEqual(coordinator.state(for: descriptor), .downloading(progress: 0))
    }

    func testDownloadedPlayPauseResumeUsesSharedPlayer() {
        let descriptor = makeDescriptor(primary: "voice-1", downloaded: true)

        coordinator.handleTap(descriptor)
        XCTAssertEqual(player.startedPrimaries, ["voice-1"])
        XCTAssertEqual(coordinator.state(for: descriptor), .playing(currentTime: 0, duration: 12))

        player.currentTime = 3
        coordinator.handleTap(descriptor)
        XCTAssertEqual(player.pauseCount, 1)
        XCTAssertEqual(coordinator.state(for: descriptor), .paused(currentTime: 3, duration: 12))

        coordinator.handleTap(descriptor)
        XCTAssertEqual(player.resumeCount, 1)
        XCTAssertEqual(coordinator.state(for: descriptor), .playing(currentTime: 3, duration: 12))
    }

    func testPlayingAnotherVoicePausesPreviousGlobalPlayback() {
        let first = makeDescriptor(primary: "first", downloaded: true)
        let second = makeDescriptor(primary: "second", downloaded: true)

        coordinator.handleTap(first)
        player.currentTime = 4
        coordinator.handleTap(second)

        XCTAssertEqual(player.stopCount, 1)
        XCTAssertEqual(player.startedPrimaries, ["first", "second"])
        XCTAssertEqual(coordinator.state(for: first), .paused(currentTime: 4, duration: 12))
        XCTAssertEqual(coordinator.state(for: second), .playing(currentTime: 0, duration: 12))
    }

    func testPlaybackPositionIsStoredByReferencePrimary() {
        let descriptor = makeDescriptor(primary: "voice-1", downloaded: true)

        coordinator.handleTap(descriptor)
        player.currentTime = 5
        coordinator.tickPlaybackProgress()
        coordinator.handleTap(descriptor)

        XCTAssertEqual(coordinator.state(for: descriptor), .paused(currentTime: 5, duration: 12))
    }

    func testPlaybackFinishAutoAdvancesToClosestNewerVisibleDownloadedVoice() {
        let old = makeDescriptor(primary: "old", sentDate: Date(timeIntervalSince1970: 1), downloaded: true)
        let current = makeDescriptor(primary: "current", sentDate: Date(timeIntervalSince1970: 2), downloaded: true)
        let next = makeDescriptor(primary: "next", sentDate: Date(timeIntervalSince1970: 3), downloaded: true)
        let newest = makeDescriptor(primary: "newest", sentDate: Date(timeIntervalSince1970: 4), downloaded: true)
        var observedPlayingPrimaries: [String] = []
        _ = coordinator.addObserver { change in
            if case .playing = change.state {
                observedPlayingPrimaries.append(change.referencePrimary)
            }
        }

        coordinator.setVisibleVoiceMessages([old, current, next, newest])
        coordinator.handleTap(current)
        player.onFinish?()
        drainMainQueue()

        XCTAssertEqual(player.startedPrimaries, ["current", "next"])
        XCTAssertEqual(coordinator.state(for: current), .downloaded)
        XCTAssertEqual(coordinator.state(for: next), .playing(currentTime: 0, duration: 12))
        XCTAssertEqual(coordinator.currentPlaybackSnapshot?.referencePrimary, "next")
        XCTAssertEqual(observedPlayingPrimaries, ["current", "next"])
    }

    func testCurrentPlaybackSnapshotExposesStorageRouteForActiveVoice() throws {
        try insertVoiceRoute(
            referencePrimary: "voice-route",
            messagePrimary: "message-route",
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular,
            archivedId: "archived-route",
            date: Date(timeIntervalSince1970: 1_711_500_000)
        )
        let descriptor = makeDescriptor(primary: "voice-route", downloaded: true)

        coordinator.handleTap(descriptor)

        let route = try XCTUnwrap(coordinator.currentPlaybackSnapshot?.route)
        XCTAssertEqual(route.owner, "alice@example.com")
        XCTAssertEqual(route.jid, "bob@example.com")
        XCTAssertEqual(route.conversationType, .regular)
        XCTAssertEqual(route.messagePrimary, "message-route")
        XCTAssertEqual(route.archivedId, "archived-route")
        XCTAssertEqual(route.sourceDate, Date(timeIntervalSince1970: 1_711_500_000))
    }

    func testPlaybackFinishAutoAdvanceUpdatesSnapshotRouteToNextVoice() throws {
        try insertVoiceRoute(
            referencePrimary: "current-route",
            messagePrimary: "message-current-route",
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular,
            archivedId: "archived-current-route",
            date: Date(timeIntervalSince1970: 10)
        )
        try insertVoiceRoute(
            referencePrimary: "next-route",
            messagePrimary: "message-next-route",
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular,
            archivedId: "archived-next-route",
            date: Date(timeIntervalSince1970: 20)
        )
        let current = makeDescriptor(primary: "current-route", sentDate: Date(timeIntervalSince1970: 10), downloaded: true)
        let next = makeDescriptor(primary: "next-route", sentDate: Date(timeIntervalSince1970: 20), downloaded: true)

        coordinator.setVisibleVoiceMessages([current, next])
        coordinator.handleTap(current)
        player.onFinish?()
        drainMainQueue()

        XCTAssertEqual(coordinator.currentPlaybackSnapshot?.referencePrimary, "next-route")
        XCTAssertEqual(coordinator.currentPlaybackSnapshot?.route?.messagePrimary, "message-next-route")
        XCTAssertEqual(coordinator.currentPlaybackSnapshot?.route?.archivedId, "archived-next-route")
    }

    func testToggleCurrentPlaybackPausesAndResumesSharedPlayer() {
        let descriptor = makeDescriptor(primary: "voice-toggle", downloaded: true)

        coordinator.handleTap(descriptor)
        player.currentTime = 4
        coordinator.toggleCurrentPlayback()
        XCTAssertEqual(player.pauseCount, 1)
        XCTAssertEqual(coordinator.state(for: descriptor), .paused(currentTime: 4, duration: 12))

        coordinator.toggleCurrentPlayback()
        XCTAssertEqual(player.resumeCount, 1)
        XCTAssertEqual(coordinator.state(for: descriptor), .playing(currentTime: 4, duration: 12))
    }

    func testSeekCurrentPlaybackUpdatesSharedPosition() {
        let descriptor = makeDescriptor(primary: "voice-seek", downloaded: true)

        coordinator.handleTap(descriptor)
        let position = coordinator.seekCurrentPlayback(percentage: 0.5)

        XCTAssertEqual(position, 6, accuracy: 0.001)
        XCTAssertEqual(player.currentTime, 6, accuracy: 0.001)
        XCTAssertEqual(coordinator.state(for: descriptor), .playing(currentTime: 6, duration: 12))
    }

    func testPlaybackFinishDoesNotAutoAdvanceToOlderVisibleVoice() {
        let older = makeDescriptor(primary: "older", sentDate: Date(timeIntervalSince1970: 1), downloaded: true)
        let current = makeDescriptor(primary: "current", sentDate: Date(timeIntervalSince1970: 2), downloaded: true)

        coordinator.setVisibleVoiceMessages([older, current])
        coordinator.handleTap(current)
        player.onFinish?()
        drainMainQueue()

        XCTAssertEqual(player.startedPrimaries, ["current"])
        XCTAssertEqual(coordinator.state(for: current), .downloaded)
        XCTAssertNil(coordinator.currentPlaybackSnapshot)
    }

    func testPlaybackFinishDoesNotAutoAdvanceToOffscreenNewerVoice() {
        let current = makeDescriptor(primary: "current", sentDate: Date(timeIntervalSince1970: 1), downloaded: true)
        let offscreenNewer = makeDescriptor(primary: "offscreen-newer", sentDate: Date(timeIntervalSince1970: 2), downloaded: true)

        coordinator.setVisibleVoiceMessages([current])
        _ = coordinator.state(for: offscreenNewer)
        coordinator.handleTap(current)
        player.onFinish?()
        drainMainQueue()

        XCTAssertEqual(player.startedPrimaries, ["current"])
        XCTAssertEqual(coordinator.state(for: current), .downloaded)
        XCTAssertEqual(coordinator.state(for: offscreenNewer), .downloaded)
        XCTAssertNil(coordinator.currentPlaybackSnapshot)
    }

    func testPlaybackFinishStopsWhenClosestNewerVisibleVoiceIsNotDownloaded() {
        let current = makeDescriptor(primary: "current", sentDate: Date(timeIntervalSince1970: 1), downloaded: true)
        let notDownloadedNewer = makeDescriptor(primary: "not-downloaded-newer", sentDate: Date(timeIntervalSince1970: 2), downloaded: false)

        coordinator.setVisibleVoiceMessages([current, notDownloadedNewer])
        coordinator.handleTap(current)
        player.onFinish?()
        drainMainQueue()

        XCTAssertEqual(player.startedPrimaries, ["current"])
        XCTAssertEqual(coordinator.state(for: current), .downloaded)
        XCTAssertNil(coordinator.currentPlaybackSnapshot)
    }

    private func makeDescriptor(
        primary: String,
        sentDate: Date = Date(timeIntervalSince1970: 1),
        downloaded: Bool = false
    ) -> VoiceMessageDescriptor {
        VoiceMessageDescriptor(
            referencePrimary: primary,
            containerMessagePrimary: "message-\(primary)",
            remoteURL: URL(string: "https://example.org/\(primary).ogg"),
            decodedURL: downloaded ? URL(fileURLWithPath: "/tmp/\(primary).m4a") : nil,
            duration: 12,
            downloaded: downloaded,
            pcm: [0.1, 0.5],
            sentDate: sentDate
        )
    }

    private func insertVoiceRoute(
        referencePrimary: String,
        messagePrimary: String,
        owner: String,
        jid: String,
        conversationType: ClientSynchronizationManager.ConversationType,
        archivedId: String,
        date: Date
    ) throws {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.primary = messagePrimary
        message.owner = owner
        message.opponent = jid
        message.conversationType = conversationType
        message.archivedId = archivedId
        message.date = date
        message.sentDate = date
        message.messageId = "message-id-\(messagePrimary)"

        let reference = MessageReferenceStorageItem()
        reference.primary = referencePrimary
        reference.messageId = messagePrimary
        reference.owner = owner
        reference.jid = jid
        reference.conversationType = conversationType
        reference.kind = .voice
        reference.sentDate = date
        reference.isDownloaded = true
        reference.decodedUrl = URL(fileURLWithPath: "/tmp/\(referencePrimary).m4a")

        try realm.write {
            realm.add(message, update: .modified)
            realm.add(reference, update: .modified)
        }
    }

    private func drainMainQueue() {
        let expectation = expectation(description: "drain main queue")
        DispatchQueue.main.async {
            expectation.fulfill()
        }
        wait(for: [expectation], timeout: 1)
    }
}

final class AudioPlayerBarViewTests: XCTestCase {
    func testDefaultEffectUsesNativeGlassWhenAvailable() throws {
        let effect = AudioPlayerBarEffectFactory.makeEffect()

        if #available(iOS 26.0, *) {
            let glassEffect = try XCTUnwrap(effect as? UIGlassEffect)
            XCTAssertTrue(glassEffect.isInteractive)
            XCTAssertEqual(glassEffect.tintColor, XabberGlassStyle.nativeGlassTintColor)
        } else {
            XCTAssertTrue(effect is UIBlurEffect)
        }
    }

    func testFallbackEffectUsesSystemMaterialBlur() {
        XCTAssertEqual(AudioPlayerBarEffectFactory.fallbackBlurStyle, XabberGlassStyle.fallbackBlurStyle(for: .audioPlayer))
        XCTAssertTrue(AudioPlayerBarEffectFactory.makeEffect(prefersNativeGlass: false) is UIBlurEffect)
    }

    func testControlsAreHostedInsideVisualEffectContentView() {
        let view = AudioPlayerBarView(frame: CGRect(x: 0, y: 0, width: 360, height: AudioPlayerBarView.Metrics.height))

        XCTAssertEqual(AudioPlayerBarView.Metrics.height, 44)
        XCTAssertEqual(view.intrinsicContentSize.height, 44)
        XCTAssertTrue(view.playPauseButton.superview === view.effectView.contentView)
        XCTAssertTrue(view.titleControl.superview === view.effectView.contentView)
        XCTAssertTrue(view.closeButton.superview === view.effectView.contentView)
        XCTAssertFalse(view.containsDescendant(ofType: UISlider.self))
        XCTAssertFalse(view.containsDescendant(ofType: UIProgressView.self))
        XCTAssertEqual(view.effectView.layer.borderWidth, 0, accuracy: 0.001)
        XCTAssertNil(view.effectView.layer.borderColor)
        XCTAssertEqual(view.effectView.layer.shadowOpacity, 0, accuracy: 0.001)
    }

    func testButtonsUseSharedIconOnlyStyle() {
        let view = AudioPlayerBarView(frame: CGRect(x: 0, y: 0, width: 360, height: AudioPlayerBarView.Metrics.height))
        view.layoutIfNeeded()

        XCTAssertNil(view.playPauseButton.configuration)
        XCTAssertNil(view.closeButton.configuration)
        XCTAssertEqual(view.playPauseButton.backgroundColor ?? .clear, .clear)
        XCTAssertEqual(view.closeButton.backgroundColor ?? .clear, .clear)
        XCTAssertEqual(view.playPauseButton.tintColor, AudioPlayerBarIconButtonStyle.tintColor)
        XCTAssertEqual(view.closeButton.tintColor, AudioPlayerBarIconButtonStyle.tintColor)
        XCTAssertEqual(view.playPauseButton.bounds.width, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001)
        XCTAssertEqual(view.playPauseButton.bounds.height, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001)
        XCTAssertEqual(view.closeButton.bounds.width, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001)
        XCTAssertEqual(view.closeButton.bounds.height, AudioPlayerBarIconButtonStyle.buttonSize, accuracy: 0.001)
        XCTAssertEqual(view.playPauseButton.contentHorizontalAlignment, .center)
        XCTAssertEqual(view.playPauseButton.contentVerticalAlignment, .center)
        XCTAssertEqual(view.closeButton.contentHorizontalAlignment, .center)
        XCTAssertEqual(view.closeButton.contentVerticalAlignment, .center)
        XCTAssertTrue(view.playPauseButton.adjustsImageWhenHighlighted)
        XCTAssertTrue(view.playPauseButton.adjustsImageWhenDisabled)
        XCTAssertTrue(view.closeButton.adjustsImageWhenHighlighted)
        XCTAssertTrue(view.closeButton.adjustsImageWhenDisabled)
    }

    func testPlayingPausedAndNilSnapshotRendering() {
        let view = AudioPlayerBarView(frame: CGRect(x: 0, y: 0, width: 360, height: AudioPlayerBarView.Metrics.height))

        view.render(
            snapshot: VoiceMessagePlaybackSnapshot(
                referencePrimary: "voice",
                containerMessagePrimary: "message",
                state: .playing(currentTime: 3, duration: 12),
                title: "Alice",
                subtitle: "Voice message",
                route: nil
            )
        )
        XCTAssertFalse(view.isHidden)
        XCTAssertEqual(view.renderedPlayPauseIconName, "pause.fill")
        XCTAssertEqual(view.timeLabel.text, "0:03 / 0:12")

        view.render(
            snapshot: VoiceMessagePlaybackSnapshot(
                referencePrimary: "voice",
                containerMessagePrimary: "message",
                state: .paused(currentTime: 6, duration: 12),
                title: "Alice",
                subtitle: "Voice message",
                route: nil
            )
        )
        XCTAssertEqual(view.renderedPlayPauseIconName, "play.fill")
        XCTAssertEqual(view.timeLabel.text, "0:06 / 0:12")

        view.render(snapshot: nil)
        XCTAssertTrue(view.isHidden)
        XCTAssertEqual(view.timeLabel.text, "0:00 / 0:00")
    }

    func testManualRenderingKeepsChatPreviewFallbackVisuallyAligned() {
        let view = AudioPlayerBarView(frame: CGRect(x: 0, y: 0, width: 360, height: AudioPlayerBarView.Metrics.height))

        view.render(title: "Alice", subtitle: "Voice message", state: .playing, currentTime: 4, duration: 9)

        XCTAssertFalse(view.isHidden)
        XCTAssertEqual(view.renderedPlayPauseIconName, "pause.fill")
        XCTAssertEqual(view.titleLabel.text, "Alice")
        XCTAssertEqual(view.subtitleLabel.text, "Voice message")
        XCTAssertEqual(view.timeLabel.text, "0:04 / 0:09")
    }
}

final class LastChatsPinnedPlayerInsetPolicyTests: XCTestCase {
    func testInsetPolicyPreservesVisibleContentWhenPlayerShowsAndHides() {
        let shownOffset = LastChatsPinnedVoicePlayerInsetPolicy.adjustedContentOffsetY(
            currentY: 120,
            insetDelta: 56,
            minimumY: -56,
            maximumY: 400
        )
        let hiddenOffset = LastChatsPinnedVoicePlayerInsetPolicy.adjustedContentOffsetY(
            currentY: shownOffset,
            insetDelta: -56,
            minimumY: 0,
            maximumY: 400
        )

        XCTAssertEqual(shownOffset, 64, accuracy: 0.001)
        XCTAssertEqual(hiddenOffset, 120, accuracy: 0.001)
    }

    func testInsetPolicyClampsToValidScrollRange() {
        XCTAssertEqual(
            LastChatsPinnedVoicePlayerInsetPolicy.adjustedContentOffsetY(
                currentY: -40,
                insetDelta: 56,
                minimumY: -56,
                maximumY: 200
            ),
            -56,
            accuracy: 0.001
        )
        XCTAssertEqual(
            LastChatsPinnedVoicePlayerInsetPolicy.adjustedContentOffsetY(
                currentY: 190,
                insetDelta: -56,
                minimumY: -56,
                maximumY: 200
            ),
            200,
            accuracy: 0.001
        )
    }
}

final class ChatFloatingAudioPlayerLayoutTests: XCTestCase {
    func testChatAudioPlayerUsesSharedBarMetrics() {
        let view = AudioPlayerBarView(frame: CGRect(x: 0, y: 0, width: 320, height: 44))

        XCTAssertEqual(AudioPlayerBarView.Metrics.height, 44, accuracy: 0.001)
        XCTAssertEqual(view.intrinsicContentSize.height, 44, accuracy: 0.001)
    }

    func testSharedGlassBubbleUsesExactFortyFourPointHeight() {
        let bubble = ChatFloatingGlassBubbleView(contentHeight: NativeGlassBarStyle.minimumHeight)

        XCTAssertEqual(bubble.measuredHeight(), 44, accuracy: 0.001)
    }

    func testFloatingHeaderLayoutUsesFortyFourPointSharedPlayerHeight() {
        let stackHeight = ChatFloatingHeaderLayoutPolicy.visibleStackHeight(
            visibleBubbleHeights: [AudioPlayerBarView.Metrics.height],
            spacing: ChatFloatingHeaderLayoutPolicy.floatingStackTopSpacing
        )
        let insets = ChatFloatingHeaderLayoutPolicy.scrollIndicatorInsets(
            composerHeight: 44,
            navigationVisualHeight: 52,
            floatingBubblesHeight: stackHeight
        )

        XCTAssertEqual(stackHeight, 44, accuracy: 0.001)
        XCTAssertEqual(insets.top, 52 + 8 + 44 + 8, accuracy: 0.001)
    }

    func testChatViewControllerAudioPlayerIsSharedBarNotFloatingGlassBubble() throws {
        let viewController = ChatViewController()
        let panel = try XCTUnwrap(viewController.sharedAudioPlayerPanel)

        XCTAssertTrue(type(of: panel) == AudioPlayerBarView.self)
    }
}

final class LastChatsPinnedVoicePlayerRoutingTests: XCTestCase {
    func testVoicePlayerRouteBuildsChatOpenMessageRequest() {
        let route = VoiceMessagePlaybackRoute(
            owner: "alice@example.com",
            jid: "bob@example.com",
            conversationType: .regular,
            messagePrimary: "message-1",
            archivedId: "archived-1",
            sourceDate: Date(timeIntervalSince1970: 1_711_500_000)
        )

        let request = LastChatsViewController.voicePlayerOpenRequest(route: route)

        XCTAssertEqual(request.owner, "alice@example.com")
        XCTAssertEqual(request.chatJid, "bob@example.com")
        XCTAssertEqual(request.conversationType, .regular)
        XCTAssertEqual(request.anchor.messagePrimary, "message-1")
        XCTAssertEqual(request.anchor.archivedId, "archived-1")
        XCTAssertEqual(request.anchor.sourceDate, Date(timeIntervalSince1970: 1_711_500_000))
        XCTAssertTrue(request.highlight)
        XCTAssertFalse(request.markReadOnVisible)
        XCTAssertEqual(request.source, .voicePlayer)
    }
}

final class InlineAudioViewVoiceStateRenderingTests: XCTestCase {
    func testRenderStatesUseExpectedIconsAndProgress() {
        let view = makeAudioView()

        view.render(state: .notDownloaded)
        XCTAssertEqual(view.renderedIconName, "square.and.arrow.down")
        XCTAssertEqual(view.renderedDownloadProgress, 0)

        view.render(state: .downloading(progress: 0.5))
        XCTAssertEqual(view.renderedIconName, "xmark")
        XCTAssertEqual(view.renderedDownloadProgress, 0.5)

        view.render(state: .downloaded)
        XCTAssertEqual(view.renderedIconName, "play.fill")

        view.render(state: .playing(currentTime: 3, duration: 12))
        XCTAssertEqual(view.renderedIconName, "pause")
        XCTAssertEqual(Double(view.waveform.currentGradientPercentage ?? 0), 0.25, accuracy: 0.001)

        view.render(state: .paused(currentTime: 6, duration: 12))
        XCTAssertEqual(view.renderedIconName, "play.fill")
        XCTAssertEqual(Double(view.waveform.currentGradientPercentage ?? 0), 0.5, accuracy: 0.001)
    }

    func testSamePrimaryAudioUpdateReusesViewAndRestoresCoordinatorProgress() {
        let grid = InlineAudiosGridView(frame: CGRect(x: 0, y: 0, width: 320, height: 44))
        let attachment = AudioAttachment(
            primary: "audio-1",
            url: URL(fileURLWithPath: "/tmp/audio-1.m4a"),
            size: 10,
            name: "voice",
            duration: 12,
            downloaded: true,
            pcm: [0.2]
        )
        grid.stateProvider = { _ in .paused(currentTime: 4, duration: 12) }

        grid.configure([attachment], palette: .blue)
        let original = grid.views.first
        grid.updateContent([attachment], palette: .blue)

        XCTAssertTrue(grid.views.first === original)
        XCTAssertEqual(grid.views.first?.waveform.currentGradientPercentage ?? 0, 4.0 / 12.0, accuracy: 0.001)
    }

    func testLocalURLRendersPlayIconWhenDownloadedFlagIsStaleFalse() {
        let view = InlineAudiosGridView.AudioView(
            frame: CGRect(x: 0, y: 0, width: 260, height: 44),
            url: URL(fileURLWithPath: "/tmp/local-url-audio.m4a")
        )

        view.configure(
            "local-url-audio-\(UUID().uuidString)",
            filename: "voice",
            size: "10 KB",
            duration: 12,
            pcm: [0.2],
            downloaded: false
        )

        XCTAssertEqual(view.renderedIconName, "play.fill")
    }

    func testGridReusePreservesPlayIconForLocalURLWithStaleDownloadedFlag() {
        let grid = InlineAudiosGridView(frame: CGRect(x: 0, y: 0, width: 320, height: 44))
        let attachment = AudioAttachment(
            primary: "local-grid-audio-\(UUID().uuidString)",
            url: URL(fileURLWithPath: "/tmp/local-grid-audio.m4a"),
            size: 10,
            name: "voice",
            duration: 12,
            downloaded: false,
            pcm: [0.2]
        )

        grid.configure([attachment], palette: .blue)
        let original = grid.views.first
        grid.updateContent([attachment], palette: .blue)

        XCTAssertTrue(grid.views.first === original)
        XCTAssertEqual(grid.views.first?.renderedIconName, "play.fill")
    }

    private func makeAudioView() -> InlineAudiosGridView.AudioView {
        let view = InlineAudiosGridView.AudioView(frame: CGRect(x: 0, y: 0, width: 260, height: 44), url: URL(fileURLWithPath: "/tmp/audio.m4a"))
        view.configure("audio", filename: "voice", size: "10 KB", duration: 12, pcm: [0.2, 0.4])
        return view
    }
}

private final class FakeVoiceDownloadTask: VoiceMessageDownloadTask {
    private(set) var cancelCalled = false

    func cancel() {
        cancelCalled = true
    }
}

private final class FakeVoiceMessageDownloader: VoiceMessageDownloading {
    private(set) var startedPrimaries: [String] = []
    private var completions: [String: (Result<VoiceMessageDownloadedFile, Error>) -> Void] = [:]
    var tasks: [String: FakeVoiceDownloadTask] = [:]

    func download(
        _ descriptor: VoiceMessageDescriptor,
        progress: @escaping (Double) -> Void,
        completion: @escaping (Result<VoiceMessageDownloadedFile, Error>) -> Void
    ) -> VoiceMessageDownloadTask {
        startedPrimaries.append(descriptor.referencePrimary)
        completions[descriptor.referencePrimary] = completion
        let task = FakeVoiceDownloadTask()
        tasks[descriptor.referencePrimary] = task
        return task
    }

    func completeSuccess(primary: String) {
        completions[primary]?(
            .success(
                VoiceMessageDownloadedFile(
                    decodedURL: URL(fileURLWithPath: "/tmp/\(primary).m4a"),
                    duration: 12,
                    pcm: [0.1, 0.5]
                )
            )
        )
    }

    func completeFailure(primary: String) {
        completions[primary]?(.failure(NSError(domain: "voice", code: 1)))
    }
}

private final class FakeVoiceMessagePlayer: VoiceMessagePlaying {
    var currentTime: TimeInterval = 0
    var duration: TimeInterval = 12
    var isPlaying: Bool = false
    var onFinish: (() -> Void)?
    private(set) var startedPrimaries: [String] = []
    private(set) var pauseCount = 0
    private(set) var resumeCount = 0
    private(set) var stopCount = 0

    func start(url: URL, referencePrimary: String, at time: TimeInterval) throws -> TimeInterval {
        startedPrimaries.append(referencePrimary)
        currentTime = time
        isPlaying = true
        return duration
    }

    func pause() {
        pauseCount += 1
        isPlaying = false
    }

    func resume() {
        resumeCount += 1
        isPlaying = true
    }

    func stop() {
        stopCount += 1
        isPlaying = false
    }

    func seek(to time: TimeInterval) {
        currentTime = time
    }
}
